def sieve_of_eratosthenes(limit):
    """Generate a list of prime numbers up to a given limit using the Sieve of Eratosthenes."""
    is_prime = [True] * (limit + 1)
    p = 2
    while (p * p <= limit):
        if (is_prime[p] == True):
            for i in range(p * p, limit + 1, p):
                is_prime[i] = False
        p += 1
    prime_numbers = [p for p in range(2, limit + 1) if is_prime[p]]
    return prime_numbers

def smartNumber(n):
    """Find the n-th smart number, which is the sum of the first n prime numbers."""
    limit = 10000  # Set a reasonable limit for prime generation
    primes = sieve_of_eratosthenes(limit)
    return sum(primes[:n])

