def magic_square_test(arr):
    n = len(arr)
    # Check if the sum of each row is equal
    if not all(sum(row) == sum(arr[0]) for row in arr):
        return False
    # Check if the sum of each column is equal
    if not all(sum(col) == sum(arr[0]) for col in zip(*arr)):
        return False
    # Check if the sum of the main diagonal is equal
    if sum(arr[i][i] for i in range(n)) != sum(arr[0]):
        return False
    # Check if the sum of the secondary diagonal is equal
    if sum(arr[i][n - i - 1] for i in range(n)) != sum(arr[0]):
        return False
    return True

