def longest_subseq_with_diff_one(arr, n):
    # Initialize a list to store the length of the longest subsequence ending at each index
    dp = [1] * n

    # Iterate through the array starting from the second element
    for i in range(1, n):
        # Check all previous elements to find a match with a difference of one
        for j in range(i):
            if abs(arr[i] - arr[j]) == 1:
                dp[i] = max(dp[i], dp[j] + 1)

    # The length of the longest subsequence is the maximum value in the dp list
    return max(dp)

