def next_Power_Of_2(n):
    # If n is 0, return 1 as the smallest power of 2
    if n == 0:
        return 1
    # If n is already a power of 2, return n
    if n & (n - 1) == 0:
        return n
    # Otherwise, find the next power of 2
    power = 1
    while power < n:
        power <<= 1
    return power

