def max_sum_increasing_subseq(arr, n, i, k):
    # Initialize the DP array with zeros
    dp = [0] * n

    # Fill the DP array
    for j in range(n):
        for l in range(j):
            if arr[j] > arr[l]:
                dp[j] = max(dp[j], dp[l])

        # Add the current element to the DP array
        dp[j] += arr[j]

    # Check if the kth element is included in the subsequence
