    map1 = {}
    map2 = {}

    # Iterate through the strings
    for i in range(len(str1)):
        # If the character in str1 is not in map1, add it with the corresponding character in str2
        if str1[i] not in map1:
            map1[str1[i]] = str2[i]
        # If the character in str1 is already in map1, check if it maps to the same character in str2
