def dealnnoy_num(n, k):
    # Initialize a 2D list to store the Delannoy numbers
    dp = [[0] * (k + 1) for _ in range(n + 1)]

    # Base case: There is one way to arrange 0 items in 0 slots
    dp[0][0] = 1

    # Fill the DP table
    for i in range(1, n + 1):
        for j in range(k + 1):
            if i == 0:
                dp[i][j] = dp[i][j - 1] + dp[i][j - 2]
            else:
                dp[i][j] = dp[i - 1][j] + dp[i][j - 1] + dp[i - 1][j - 2]

    # The nth Delannoy number is stored in dp[n][k]
    return dp[n][k]

