from collections import defaultdict, deque

def topological_sort(graph, indegree):
    queue = deque([i for i in range(len(graph)) if indegree[i] == 0])
    result = []

    while queue:
        node = queue.popleft()
        result.append(node)

        for neighbor in graph[node]:
            indegree[neighbor] -= 1
            if indegree[neighbor] == 0:
                queue.append(neighbor)

    return result

def min_reversals(words):
    n = len(words)
    graph = defaultdict(list)
    indegree = [0] * n

    # Build the graph and calculate indegree
    for i in range(n):
        for j in range(i + 1, n):
            if words[i][-1] == words[j][0]:
                graph[i].append(j)
                indegree[j] += 1

    # Find the topological order
    top_order = topological_sort(graph, indegree)

    # If the topological order is not complete, we need to reverse some words
    if len(top_order) != n:
        # Find the cycles
        visited = [False] * n
        cycles = []

        for i in range(n):
            if not visited[i]:
                cycle = []
                stack = [i]

                while stack:
                    node = stack.pop()
                    if not visited[node]:
                        visited[node] = True
                        cycle.append(node)
                        for neighbor in graph[node]:
                            stack.append(neighbor)
                    else:
                        if node in cycle:
                            cycles.append(cycle[cycle.index(node):])

        # If there are cycles, we need to reverse the minimum number of words
        if cycles:
            # Find the minimum number of reversals
            min_reversals = float('inf')
            for cycle in cycles:
                reversals = len(cycle) - 1
                if reversals < min_reversals:
                    min_reversals = reversals

            # Reverse the words in the cycle
            for i in range(min_reversals):
                words[cycle[i]] = words[cycle[i]][::-1]

            # Perform the topological sort again
            top_order = topological_sort(graph, indegree)

        # If the topological order is still not complete, return -1
        if len(top_order) != n:
            return -1

    # Return the number of reversals and the indices of the words to reverse
    return len(top_order) - n, [i + 1 for i in range(n) if words[i] != words[top_order[i]]]

