from collections import defaultdict

def find_dangerous_paths(n, m, edges):
    graph = defaultdict(list)
    for x, y in edges:
        graph[x].append(y)

    dangerous_paths = []

    def dfs(node, parent, visited):
        visited[node] = True
        for neighbor in graph[node]:
            if neighbor == parent:
                continue
            if visited[neighbor]:
                dangerous_paths.append((node, neighbor))
            else:
                dfs(neighbor, node, visited)

    visited = [False] * (n + 1)
    for node in range(1, n + 1):
        if not visited[node]:
            dfs(node, -1, visited)

    return dangerous_paths

def find_safe_configuration(n, m, edges):
    graph = defaultdict(list)
    for x, y in edges:
        graph[x].append(y)

    # Find all cycles of length 2
    cycles = []
    visited = [False] * (n + 1)
    for node in range(1, n + 1):
        if not visited[node]:
            stack = [node]
            while stack:
                current = stack.pop()
                visited[current] = True
                for neighbor in graph[current]:
                    if not visited[neighbor]:
                        stack.append(neighbor)
                    else:
                        if neighbor != stack[-1]:
                            cycles.append((stack[-1], neighbor))

    # Remove cycles of length 2
    for u, v in cycles:
        graph[u].remove(v)
        graph[v].remove(u)

    # Count the number of spots to be closed
    spots_to_close = 0
    spots_to_close_set = set()

    for node in range(1, n + 1):
        if not graph[node]:
            spots_to_close += 1
            spots_to_close_set.add(node)

    return spots_to_close, spots_to_close_set

