def simulate_game(s):
    score = 0
    i = 0
    while i < len(s):
        # Find the length of the current sequence of consecutive '1's
        j = i
        while j < len(s) and s[j] == s[i]:
            j += 1
        # If the current sequence is '1's, Alice can delete it
        if s[i] == '1':
