def min_grid_area(s):
    min_x, max_x = 0, 0
    min_y, max_y = 0, 0
    current_x, current_y = 0, 0

    for command in s:
        if command == 'W':
            current_y -= 1
        elif command == 'S':
            current_y += 1
        elif command == 'A':
            current_x -= 1
        elif command == 'D':
            current_x += 1

        min_x = min(min_x, current_x)
        max_x = max(max_x, current_x)
        min_y = min(min_y, current_y)
        max_y = max(max_y, current_y)

    return (max_x - min_x + 1) * (max_y - min_y + 1)

