from itertools import permutations

def is_good_permutation(p):
    decomposition = []
    marked = [False] * len(p)
    for i in range(len(p)):
        if not marked[i]:
            stack = [i]
            reachable = []
            while stack:
                j = stack.pop()
                if not marked[j]:
                    marked[j] = True
                    reachable.append(j)
                    stack.extend([p[j]])
            reachable.sort()
            decomposition.append(reachable)

    sorted_decomposition = sorted(decomposition, key=lambda x: x[0])
    new_permutation = []
    for sublist in sorted_decomposition:
        new_permutation.extend(sublist)

    return new_permutation == p

def find_kth_good_permutation(n, k):
    count = 0
    for perm in permutations(range(1, n + 1)):
        if is_good_permutation(perm):
            count += 1
            if count == k:
                return perm

    return -1

