def lcm(a, b):
    return a * b // gcd(a, b)

def find_min_moves(n):
    divisors = [i for i in range(2, n + 1) if n % i == 0]
    if len(divisors) == 0:
        return 0, []

    # Find the smallest divisor that is not coprime with the first divisor
    for i in range(1, len(divisors)):
        if gcd(divisors[0], divisors[i]) != 1:
            break

    # Place the smallest non-coprime divisor between the first and second divisors
    divisors.insert(1, divisors.pop(i))

    # Calculate the minimum number of moves
    moves = 0
    for i in range(1, len(divisors)):
        if gcd(divisors[i], divisors[i - 1]) == 1:
            moves += 1
            divisors[i] = lcm(divisors[i], divisors[i - 1])

    return moves, divisors

