from collections import defaultdict

def is_segment_intersecting(s1, s2):
    x1, y1 = s1
    x2, y2 = s2
    return min(y1, y2) <= max(x1, x2) <= max(y1, y2)

def dfs(node, parent, tree, segments, visited, max_size):
    visited[node] = True
    max_size[node] = 1

    for neighbor in tree[node]:
        if neighbor != parent:
            dfs(neighbor, node, tree, segments, visited, max_size)
            max_size[node] += max_size[neighbor]

    # Check if the subtree rooted at node corresponds to the segments
    for i in range(len(segments)):
        for j in range(i + 1, len(segments)):
            if is_segment_intersecting(segments[i], segments[j]):
                if max_size[node] > max_size[segments[i][0]] + max_size[segments[j][0]]:
                    max_size[node] = max_size[segments[i][0]] + max_size[segments[j][0]]

    return max_size[node]

def solve():
