        data = data[2:]

        tree = defaultdict(list)
        for _ in range(n - 1):
            x, y = map(int, data[0:2])
            tree[x].append(y)
            tree[y].append(x)
            data = data[2:]

        segments = []
        for _ in range(n - 1):
