def count_paths(n, m, labyrinth):
    MOD = 10**9 + 7

    # Initialize dp array with zeros
    dp = [[0] * (m + 1) for _ in range(n + 1)]

    # Starting cell
    dp[1][1] = 1

    # Fill the dp array
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if labyrinth[i - 1][j - 1] == 'R':
                # If the current cell contains a rock, we need to check the previous cell
                if i > 1 and labyrinth[i - 2][j - 1] != 'R':
                    dp[i][j] += dp[i - 1][j]
                if j > 1 and labyrinth[i - 1][j - 2] != 'R':
                    dp[i][j] += dp[i][j - 1]
            else:
                # If the current cell is empty, we can move right or down
                if i > 1:
                    dp[i][j] += dp[i - 1][j]
                if j > 1:
                    dp[i][j] += dp[i][j - 1]

    # Return the number of ways to reach the bottom-right cell modulo 10^9 + 7
    return dp[n][m] % MOD

