def median_smoothing(sequence):
    n = len(sequence)
    if n < 3:
        return sequence

    # Apply the median smoothing algorithm
    new_sequence = [sequence[0]]
    for i in range(1, n - 1):
        # Find the median of the three numbers: a[i-1], a[i], a[i+1]
        values = sorted([sequence[i-1], sequence[i], sequence[i+1]])
        new_sequence.append(values[1])
    new_sequence.append(sequence[-1])

    return new_sequence

def is_stable(sequence):
    seen = set()
    while sequence not in seen:
        seen.add(tuple(sequence))
        sequence = median_smoothing(sequence)

    return sequence

