def count_operations(n, heights):
    operations = 0
    while True:
        boundary_blocks = 0
        for i in range(n):
            if i == 0 or i == n - 1:
                # First and last blocks are always boundary
                boundary_blocks += heights[i]
            else:
                # Check if the block is boundary
                if heights[i - 1] > 0 and heights[i + 1] > 0:
                    boundary_blocks += heights[i]

        if boundary_blocks == 0:
            break

        operations += 1

        # Destroy all boundary blocks
        for i in range(n):
            if i == 0 or i == n - 1:
                heights[i] = 0
            else:
                if heights[i - 1] > 0 and heights[i + 1] > 0:
                    heights[i] = 0

        # Update the number of blocks in each tower
        for i in range(n):
            if heights[i] > 0:
                heights[i] -= 1

        # If any tower is still non-zero, reset the boundary block count
        if any(heights):
            boundary_blocks = 0
        else:
            break

    return operations

