def arrange_numbers(n):
    # Create a list to store the numbers in the desired order
    numbers = []

    # Use two pointers to alternate between the smallest and largest numbers
    left = 1
    right = 2 * n

    while left <= right:
        if left <= right:
            numbers.append(left)
            left += 1
        if left <= right:
            numbers.append(right)
            right -= 1

    # Output the result
    if len(numbers) == 2 * n:
        return "YES\n" + " ".join(map(str, numbers))
