def unite_doubly_linked_lists(n, connections):
    # Step 1: Identify the starting cell of each list
    start_cells = [i for i in range(1, n + 1) if connections[i - 1][0] == 0]

    # Step 2: Unify the lists
    # We will use a dictionary to keep track of the last cell of each list
    last_cells = {}

    for start in start_cells:
        current = start
        while current != 0:
            last_cells[current] = current
            current = connections[current - 1][1]

    # Step 3: Update connections
    for i in range(1, n + 1):
        if i in last_cells:
            # If the cell is the last cell of a list, connect it to the first cell of the next list
            if connections[i - 1][1] != 0:
                last_cells[connections[i - 1][1] - 1] = last_cells[i]
            # If the cell is not the last cell of a list, connect it to the next cell
            else:
                last_cells[i] = connections[i - 1][0]
        else:
            # If the cell is not the last cell of any list, connect it to the next cell
            last_cells[i] = connections[i - 1][1]

    # Output the updated connections
    for i in range(1, n + 1):
        print(last_cells[i], connections[i - 1][0])

