from collections import defaultdict, deque

def max_efficiency(n, edges):
    # Build the graph
    graph = defaultdict(list)
    for p, a in edges:
        graph[p].append(a)

    # Topological sorting
    in_degree = [0] * (n + 1)
    for u in range(1, n + 1):
        for v in graph[u]:
            in_degree[v] += 1

    queue = deque([u for u in range(1, n + 1) if in_degree[u] == 0])
    topo_order = []

    while queue:
        u = queue.popleft()
        topo_order.append(u)
        for v in graph[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)

    # Initialize DP table
    dp = [[0] * (n + 1) for _ in range(n + 1)]
    dp[0][0] = 0  # Base case: no employees in the workgroup

    # Fill the DP table
    for u in topo_order:
        for v in graph[u]:
            for k in range(n + 1):
                if k % 2 == 0:
                    dp[u][k + 1] = max(dp[u][k + 1], dp[v][k] + a)

    # Find the maximum efficiency
    max_eff = 0
    for k in range(n + 1):
        max_eff = max(max_eff, dp[n][k])

    return max_eff

