    magnets = []
    for _ in range(n):
        x1, y1, x2, y2 = map(int, input().split())
        magnets.append(((x1, y1), (x2, y2)))
    return n, k, magnets

def calculate_overlap(m1, m2):
    x1, y1 = m1[0]
    x2, y2 = m1[1]
    x3, y3 = m2[0]
    x4, y4 = m2[1]

    # Calculate the overlap rectangle
    overlap_x1 = max(x1, x3)
    overlap_y1 = max(y1, y3)
    overlap_x2 = min(x2, x4)
    overlap_y2 = min(y2, y4)

    # Check if there is an overlap
    if overlap_x1 < overlap_x2 and overlap_y1 < overlap_y2:
        return (overlap_x1, overlap_y1, overlap_x2, overlap_y2)
    else:
        return None

def calculate_overlap_area(overlap):
    if overlap:
        x1, y1, x2, y2 = overlap
        return (x2 - x1) * (y2 - y1)
    return 0

def find_min_door_dimensions(magnets, k):
    # Calculate all overlaps
    overlaps = []
    for i in range(len(magnets)):
        for j in range(i + 1, len(magnets)):
            overlap = calculate_overlap(magnets[i], magnets[j])
            if overlap:
                overlaps.append(overlap)

    # Sort overlaps by area in descending order
    overlaps.sort(key=calculate_overlap_area, reverse=True)

    # Remove overlaps until we have at least n - k magnets
    remaining_magnets = len(magnets) - k
    for overlap in overlaps:
        if remaining_magnets > 0:
            remaining_magnets -= 1
        else:
            break

    # Calculate the dimensions of the door
    if remaining_magnets == 0:
        # No overlaps to remove, use the maximum dimensions
        x1, y1, x2, y2 = magnets[0][0], magnets[0][1], magnets[-1][1], magnets[-1][1]
        for m in magnets:
            x1 = min(x1, m[0][0])
            y1 = min(y1, m[0][1])
            x2 = max(x2, m[1][0])
            y2 = max(y2, m[1][1])
    else:
        # Use the remaining magnets to determine the dimensions
        x1, y1 = magnets[0][0]
        x2, y2 = magnets[-1][1]
        for m in magnets:
            x1 = min(x1, m[0][0])
            y1 = min(y1, m[0][1])
            x2 = max(x2, m[1][0])
            y2 = max(y2, m[1][1])

    # Calculate the area of the door
    return (x2 - x1) * (y2 - y1)

def main():
