def can_divide_into_sets(n, a, b, p):
    # Create a set to store numbers that are symmetric around a
    symmetric_around_a = set()
    # Create a set to store numbers that are symmetric around b
    symmetric_around_b = set()

    # Populate the sets
    for x in p:
        if x <= a:
            symmetric_around_a.add(a - x)
        if x <= b:
            symmetric_around_b.add(b - x)

    # Check if we can partition the numbers
    for x in p:
        if x in symmetric_around_a and x in symmetric_around_b:
            # If x is symmetric around both a and b, it's impossible to partition
            return "NO"

    # If we can partition, determine the sets
    set_A = set()
    set_B = set()

    for x in p:
        if x in symmetric_around_a:
            set_A.add(x)
        elif x in symmetric_around_b:
            set_B.add(x)
        else:
            # If x is not symmetric around either a or b, it must be in one of the sets
            if a - x in set_A or b - x in set_A:
                set_A.add(x)
            else:
                set_B.add(x)

    # Output the result
    if len(set_A) == 0 or len(set_B) == 0:
        return "NO"

    # Determine the binary representation for each number
    result = []
    for x in p:
        if x in set_A:
            result.append(0)
        else:
            result.append(1)

    # Output the result
    print("YES")
    print(" ".join(map(str, result)))

