from typing import List

def find_lis(sequence: List[int]) -> List[int]:
    n = len(sequence)
    lis = [1] * n
    prev = [-1] * n

    for i in range(1, n):
        for j in range(i):
            if sequence[i] > sequence[j] and lis[i] < lis[j] + 1:
                lis[i] = lis[j] + 1
                prev[i] = j

    max_length = max(lis)
    lis_indices = []

    for i in range(n):
        if lis[i] == max_length:
            lis_indices.append(i)

    return lis_indices

def split_sequence(sequence: List[int]) -> List[List[int]]:
    lis_indices = find_lis(sequence)
    subsequences = []

    for i in lis_indices:
        subsequence = []
        j = i
        while j >= 0 and sequence[j] == sequence[i]:
            subsequence.append(j + 1)
            j -= 1
        j = i
        while j < len(sequence) and sequence[j] == sequence[i]:
            subsequence.append(j + 1)
            j += 1
        subsequences.append(subsequence)

    return subsequences

