def count_pretty_substrings(s):
    n = len(s)
    left = [0] * n
    right = [0] * n

    # Calculate the left balance array
    balance = 0
    for i in range(n):
        if s[i] == '(':
            balance += 1
        elif s[i] == ')':
            balance -= 1
        left[i] = balance

    # Calculate the right balance array
    balance = 0
    for i in range(n - 1, -1, -1):
        if s[i] == '(':
            balance += 1
        elif s[i] == ')':
            balance -= 1
        right[i] = balance

    # Count pretty substrings
    pretty_count = 0
    for i in range(n):
        if s[i] == '?':
            # For '?' at position i, we need to find the number of valid substrings
            # that can be formed by replacing '?' with '(' or ')'
            # We need to ensure that the balance is non-negative at all points
            # in the substring
            for j in range(i + 1, n):
                if left[i] + right[j] >= 0:
                    pretty_count += 1
        else:
            # For non-?' characters, we need to ensure that the balance is non-negative
            # at the current position
            if left[i] >= 0:
                pretty_count += 1

    return pretty_count

