from typing import List

def count_ways(n: int, m: int, relationships: List[List[int]]) -> int:
    MOD = 1_000_000_007

    # Build the adjacency matrix
    G = defaultdict(lambda: defaultdict(int))
    for a, b, c in relationships:
        G[a][b] = c
        G[b][a] = c

    # DP table to store the number of valid configurations
    dp = {}

    def is_valid_subset(subset: set) -> bool:
        for i in subset:
            for j in subset:
                if i != j and G[i][j] == 1:
                    return False
        return True

    def count_ways_recursive(subset: set) -> int:
        if len(subset) == n:
            return 1

        if tuple(subset) in dp:
            return dp[tuple(subset)]

        count = 0
        for i in range(1, n + 1):
            if i not in subset:
                # Add i to the subset
                new_subset = subset | {i}
                if is_valid_subset(new_subset):
                    count += count_ways_recursive(new_subset)

        dp[tuple(subset)] = count % MOD
        return dp[tuple(subset)]

    # Start the recursion with an empty subset
    return count_ways_recursive(set())

