from collections import deque

def bfs(start, target, n):
    queue = deque([(start, 0)])
    visited = set()

    while queue:
        current, steps = queue.popleft()

        # If we have reached the target, return True
        if current == target:
            return True

        # If we have already visited this state, skip it
        if current in visited:
            continue

        # Mark the current state as visited
        visited.add(current)

        # Generate all possible transformations
        for i in range(n - 2):
            # Replace "011" with "110"
            if current[i] == '0' and current[i + 1] == '1' and current[i + 2] == '1':
                new_state = current[:i] + '110' + current[i + 3:]
                queue.append((new_state, steps + 1))

            # Replace "110" with "011"
            if current[i] == '1' and current[i + 1] == '1' and current[i + 2] == '0':
                new_state = current[:i] + '011' + current[i + 3:]
                queue.append((new_state, steps + 1))

    # If we exhaust the queue without finding the target, return False
    return False

