def max_total_gain(n, m, a):
    # Initialize the DP table
    dp = [[0] * (m + 1) for _ in range(n + 1)]

    # Fill the DP table
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            dp[i][j] = a[i - 1][j - 1]
            if i > 1:
                dp[i][j] += dp[i - 1][j]
            if j > 1:
                dp[i][j] += dp[i][j - 1]

    # Calculate the maximum total gain
    max_gain = 0
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            max_gain = max(max_gain, dp[i][j])

    return max_gain

