from collections import defaultdict

def can_win(n, s1, s2):
    # Create a graph to represent the game
    graph = defaultdict(list)
    for i in range(1, n):
        for x in s1:
            graph[i].append((i + x) % n)
        for x in s2:
            graph[i].append((i + x) % n)

    # Function to determine if a player can win from a given position
    def dfs(pos, player):
        if pos == 0:
            return player == 1
        if (pos, player) in memo:
            return memo[(pos, player)]

        if player == 1:
            # Rick's turn
            for next_pos in graph[pos]:
                if not dfs(next_pos, 2):
                    memo[(pos, player)] = True
                    return True
            memo[(pos, player)] = False
            return False
        else:
            # Morty's turn
            for next_pos in graph[pos]:
                if not dfs(next_pos, 1):
                    memo[(pos, player)] = True
                    return True
            memo[(pos, player)] = False
            return False

    # Memoization dictionary
    memo = {}

    # Determine the outcome for each initial position
    outcomes = []
    for i in range(1, n):
        if dfs(i, 1):
            outcomes.append("Win")
        elif dfs(i, 2):
            outcomes.append("Lose")
        else:
            outcomes.append("Loop")

    return outcomes

