from math import gcd

def sieve_of_eratosthenes(limit):
    is_prime = [True] * (limit + 1)
    p = 2
    while (p * p <= limit):
        if (is_prime[p] == True):
            for i in range(p * p, limit + 1, p):
                is_prime[i] = False
        p += 1
    prime_numbers = [p for p in range(2, limit + 1) if is_prime[p]]
    return prime_numbers

def find_largest_prime_less_than_or_equal_to(n, primes):
    for prime in reversed(primes):
        if prime <= n:
            return prime

def find_smallest_prime_greater_than(n, primes):
    for prime in primes:
        if prime > n:
            return prime

def sum_of_reciprocals(n):
    primes = sieve_of_eratosthenes(n)
    total_sum = 0
    for i in range(2, n + 1):
        largest_prime = find_largest_prime_less_than_or_equal_to(i, primes)
        smallest_prime = find_smallest_prime_greater_than(i, primes)
        total_sum += 1 / (largest_prime * smallest_prime)

    # Convert to irreducible fraction
    numerator = int(total_sum * (10**18))  # Multiply by 10^18 to avoid floating-point precision issues
    denominator = 10**18
    common_divisor = gcd(numerator, denominator)
    numerator //= common_divisor
    denominator //= common_divisor

    return f"{numerator}/{denominator}"

