def count_ways(n, actions):
    MOD = 10**9 + 7

    # Initialize DP table
    dp = defaultdict(lambda: defaultdict(lambda: defaultdict(int)))
    dp[0][0][0] = 1  # Base case: 1 way to have no actions

    # Process each action
    for i, (action, price) in enumerate(actions):
        if action == "ADD":
            # Add a new order with price p
            for j in range(len(best_sell)):
                if best_sell[j] > price:
                    dp[i+1][j][k] += dp[i][j][k]
                    dp[i+1][j][k] %= MOD
            for k in range(len(best_buy)):
                if best_buy[k] < price:
                    dp[i+1][j][k] += dp[i][j][k]
                    dp[i+1][k][k] %= MOD
        elif action == "ACCEPT":
            # Accept the best SELL or BUY offer
            if best_sell:
                dp[i+1][j-1][k] += dp[i][j][k]
                dp[i+1][j-1][k] %= MOD
            if best_buy:
                dp[i+1][j][k-1] += dp[i][j][k]
                dp[i+1][j][k-1] %= MOD

    # Sum up all valid ways to restore directions
    result = 0
    for j in range(len(best_sell)):
        for k in range(len(best_buy)):
            result += dp[n][j][k]
            result %= MOD

    return result

