def lis(arr):
    n = len(arr)
    lis = [1] * n
    for i in range(1, n):
        for j in range(i):
            if arr[i] > arr[j]:
                lis[i] = max(lis[i], lis[j] + 1)
    return max(lis)

def lds(arr):
    n = len(arr)
    lds = [1] * n
    for i in range(n-2, -1, -1):
        for j in range(n-1, i, -1):
            if arr[i] > arr[j]:
                lds[i] = max(lds[i], lds[j] + 1)
    return max(lds)

def min_additional_requests(a):
    n = len(a)
    if n == 1:
        return 0

    lis_length = lis(a)
    lds_length = lds(a)

    # If the sequence is already strictly increasing or decreasing, no additional requests are needed
    if lis_length == n or lds_length == n:
        return 0

    # Calculate the minimum additional requests
    return lis_length + lds_length - n

