from collections import Counter

def optimal_company_name(oleg_set, igor_set):
    # Convert sets to counters for easy manipulation
    oleg_counter = Counter(oleg_set)
    igor_counter = Counter(igor_set)

    # Initialize the company name with '?' characters
    company_name = ['?'] * len(oleg_set)

    # Function to find the smallest available character
    def find_smallest_char():
        for char in 'abcdefghijklmnopqrstuvwxyz':
            if oleg_counter[char] > 0:
                return char

    # Function to find the largest available character
    def find_largest_char():
        for char in 'abcdefghijklmnopqrstuvwxyz'[::-1]:
            if igor_counter[char] > 0:
                return char

    # Oleg's turn
    for i in range(len(oleg_set)):
        if oleg_counter[company_name[i]] > 0:
            company_name[i] = find_smallest_char()
            oleg_counter[company_name[i]] -= 1

    # Igor's turn
    for i in range(len(igor_set)):
        if igor_counter[company_name[i]] > 0:
            company_name[i] = find_largest_char()
            igor_counter[company_name[i]] -= 1

    return ''.join(company_name)

