def simulate_killing(psychos):
    steps = 0
    n = len(psychos)

    while True:
        killed = False
        for i in range(n - 1):
            if psychos[i] > psychos[i + 1]:
                psychos[i] = psychos[i + 1]
                psychos[i + 1] = 0  # Mark the killed psycho as 0
                killed = True
        if not killed:
            break
        steps += 1

    return steps

