from collections import defaultdict

def normalize_word(word):
    # Replace 'u' with 'oo' and 'h' with 'kh'
    normalized = []
    for char in word:
        if char == 'u':
            normalized.append('oo')
        elif char == 'h':
            normalized.append('kh')
        else:
            normalized.append(char)
    return ''.join(normalized)

def group_words(words):
    # Use a dictionary to group words based on their normalized form
    word_groups = defaultdict(list)

    for word in words:
        normalized_word = normalize_word(word)
        word_groups[normalized_word].append(word)

    # Count the number of unique groups
    return len(word_groups)

