    return True

def has_common_subsequence(word, desc1, desc2):
    # Check if desc1 is a subsequence of word
    i = 0
    for c in desc1:
        while i < len(word) and word[i] != c:
            i += 1
        if i == len(word):
            return False
        i += 1
    # Check if desc2 is a subsequence of word
    i = 0
    for c in desc2:
        while i < len(word) and word[i] != c:
            i += 1
        if i == len(word):
            return False
        i += 1
    return True

