def find_regular_subsequence(s, k):
    n = len(s)
    balance = 0
    subsequence = []

    for i in range(n):
        if s[i] == '(':
            balance += 1
        else:
            balance -= 1

        # If balance is negative, it means there are more closing brackets than opening ones
        if balance < 0:
            continue

        # If we have found k characters, stop
        if len(subsequence) == k:
            break

        # If balance is zero, it means the current subsequence is balanced
        if balance == 0:
            subsequence.append(s[i])

    # If we didn't find a valid subsequence, we need to adjust
    if len(subsequence) < k:
        # We need to add more characters to make the subsequence balanced and of length k
        for i in range(k - len(subsequence)):
            if balance > 0:
                subsequence.append(')')
                balance -= 1
            else:
                subsequence.append('(')
                balance += 1

    return ''.join(subsequence)

