from collections import defaultdict, deque

def bfs(graph, start):
    queue = deque([start])
    visited = set([start])
    level = {start: 0}

    while queue:
        current = queue.popleft()
        for neighbor in graph[current]:
            if neighbor not in visited:
                visited.add(neighbor)
                level[neighbor] = level[current] + 1
                queue.append(neighbor)

    return level

def find_max_distance(graph, root):
    level = bfs(graph, root)
    max_distance = 0
    max_distance_city = root
    for city, distance in level.items():
        if distance > max_distance:
            max_distance = distance
            max_distance_city = city
    return max_distance_city, max_distance

def min_captures_to_isolate(graph, important_cities):
    n = len(graph)
    max_distance_city, max_distance = find_max_distance(graph, 0)

    # Check if all important cities are in different subtrees
    for city in important_cities:
        if city != max_distance_city:
            return -1

    # Calculate the number of leaves in the subtree rooted at max_distance_city
    leaves = 0
    for city in graph[max_distance_city]:
        if len(graph[city]) == 1:
            leaves += 1

    return leaves

