def dp(n, m, graph):
    # Initialize DP table
    dp = [[[False] * (n + 1) for _ in range(n + 1)] for _ in range(2)]

    # Base case: if a player has no valid moves, they lose
    for j in range(1, n + 1):
        for k in range(1, n + 1):
            if not can_move(graph, j, k):
                dp[0][j][k] = True
                dp[1][j][k] = True

    # Fill the DP table
    for i in range(1, n + 1):
        for j in range(1, n + 1):
            for k in range(1, n + 1):
                if dp[i % 2][j][k]:
                    continue
                for u in graph[j]:
                    if dp[(i + 1) % 2][u[0]][k]:
                        dp[i % 2][j][k] = True
                        break
                for v in graph[k]:
                    if dp[(i + 1) % 2][j][v[0]]:
                        dp[i % 2][j][k] = True
                        break

    # Output the results
    for j in range(1, n + 1):
        for k in range(1, n + 1):
            if dp[0][j][k]:
                print('A', end='')
            else:
                print('B', end='')
        print()

