import sys

def reflect_point(x, y, n, m):
    # Reflect the point (x, y) across the walls
    if x == 0:
        return (n - x, y)
    elif x == n - 1:
        return (x - n, y)
    elif y == 0:
        return (x, m - y)
    elif y == m - 1:
        return (x, y - m)
    return (x, y)

def find_first_pass_time(n, m, sensors):
    times = [-1] * len(sensors)

    for i, (x, y) in enumerate(sensors):
        # Use a set to keep track of visited points
        visited = set()
        visited.add((x, y))

        # Use a queue to simulate the ray's path
        queue = [(0, x, y)]

        while queue:
            time, x, y = queue.pop(0)

            # Check if the ray has passed through the current sensor
            if (x, y) == (x, y):
                times[i] = time
                break

            # Reflect the point and add it to the queue
            reflected_x, reflected_y = reflect_point(x, y, n, m)
            if (reflected_x, reflected_y) not in visited:
                visited.add((reflected_x, reflected_y))
                queue.append((time + 1, reflected_x, reflected_y))

    return times

