    # Convert the grid to a list of lists for easier manipulation
    grid = [list(row) for row in S]

    # Function to calculate the area of a rectangle
    def rectangle_area(x1, y1, x2, y2):
        return (x2 - x1 + 1) * (y2 - y1 + 1)

    # Function to invert a row
    def invert_row(row):
        return ['#' if cell == '.' else '.' for cell in row]

    # Function to invert a column
    def invert_column(col):
        return [row[col] for row in grid]

    # Initialize the maximum area
    max_area = 0

    # Iterate over all possible rectangles
    for x1 in range(H):
        for y1 in range(W):
            for x2 in range(x1, H):
                for y2 in range(y1, W):
                    # Check if the rectangle is black
                    is_black = True
                    for i in range(x1, x2 + 1):
                        for j in range(y1, y2 + 1):
                            if grid[i][j] == '.':
                                is_black = False
                                break
                        if not is_black:
                            break
                    if is_black:
                        # Calculate the area of the rectangle
                        area = rectangle_area(x1, y1, x2, y2)
                        # Update the maximum area
                        max_area = max(max_area, area)

    return max_area

