def dfs(current_station, previous_company, visited, graph, fare):
    if current_station == N:
        return fare

    min_fare = float('inf')

    for next_station, company in graph[current_station]:
        if company != previous_company:
            new_fare = fare + 1
        else:
            new_fare = fare

        if (current_station, next_station, company) not in visited:
