def calculate_rating_changes(n, a):
    rating_changes = [0] * n
    for i in range(1, n):
        for j in range(i):
            rating_changes[i] += a[j] * (j - 1) - (n - i) * a[i]
    return rating_changes

def find_excluded_participants(n, k, a):
    rating_changes = calculate_rating_changes(n, a)
    excluded = []

    for i in range(n):
        if rating_changes[i] < k:
            excluded.append(i + 1)
            # Update the remaining participants' ratings
            for j in range(i + 1, n):
                rating_changes[j] += a[i] * (j - i - 1) - (n - j) * a[j]

    return excluded

