    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    # Find all paths from a to b
    paths = []
    for i in range(1, n + 1):
        for j in range(i + 1, n + 1):
            if i != j:
                path = []
                queue = deque([(i, 0)])
                visited = set([i])
                while queue:
                    current, distance = queue.popleft()
                    path.append(current)
                    if current == j:
                        paths.append(path)
                        break
                    for neighbor in graph[current]:
                        if neighbor not in visited:
                            visited.add(neighbor)
                            queue.append((neighbor, distance + 1))

    # Check if any path can be reversed
    for path in paths:
        if bfs(graph, b, a) == len(path) - 1:
            return "YES"

    return "NO"

