def transform(a, b):
    n = len(a)
    operations = []

    # Try to match the strings by flipping and reversing prefixes
    for i in range(n):
        if a[i] != b[i]:
            # Find the longest matching prefix
            j = i
            while j < n and a[j] == b[j]:
                j += 1

            # If no matching prefix is found, return -1 (not possible)
            if j == i:
                return -1

            # Calculate the number of operations needed
            operations.append(j - i)

            # Flip and reverse the prefix
            a = a[:i] + a[i:j][::-1] + a[j:]

    return operations

