def is_connected(n, row1, row2):
    # Create a graph
    graph = [[] for _ in range(2 * n)]

    # Add edges between adjacent pipes
    for i in range(n):
        graph[i].append(i + n)
        graph[i + n].append(i)

    # Add edges between pipes in the same row
    for i in range(n):
        if row1[i] == row2[i]:
            graph[i].append(i + n)
            graph[i + n].append(i)

