    for i in range(n):
        if row1[i] != row2[i]:
            graph[i].append(i + n + 1)
            graph[i + n + 1].append(i)

    # Check if the graph is connected
    visited = [False] * (2 * n)
    queue = deque([0])
    visited[0] = True

    while queue:
        node = queue.popleft()
        for neighbor in graph[node]:
            if not visited[neighbor]:
                visited[neighbor] = True
                queue.append(neighbor)

    return all(visited)

