def min_operations_to_sort(arr):
    n = len(arr)
    operations = 0
    for i in range(1, n):
        if arr[i] < arr[i - 1]:
            # Find the position where arr[i] should be
            j = i
            while j > 0 and arr[j - 1] > arr[i]:
                j -= 1
            # Move arr[i] to the correct position
            arr = arr[j:] + arr[:j] + arr[j + 1:i] + [arr[j]]
            operations += i - j
    return operations

