from collections import defaultdict

def is_valid_sequence(s):
    x, y = 0, 0
    visited = defaultdict(int)
    visited[(x, y)] += 1

    for move in s:
        if move == 'L':
            x -= 1
        elif move == 'R':
            x += 1
        elif move == 'U':
            y += 1
        elif move == 'D':
            y -= 1

        if (x, y) in visited:
            visited[(x, y)] += 1
            if visited[(x, y)] > 2:
                return False
        else:
            visited[(x, y)] = 1

    return x == 0 and y == 0 and visited[(x, y)] <= 2

def rearrange_sequence(s):
    visited = defaultdict(int)
    visited[(0, 0)] += 1

    for move in s:
        if move == 'L':
            x, y = x - 1, y
        elif move == 'R':
            x, y = x + 1, y
        elif move == 'U':
            x, y = x, y + 1
        elif move == 'D':
            x, y = x, y - 1

        if (x, y) in visited:
            visited[(x, y)] += 1
            if visited[(x, y)] > 2:
                return False
        else:
            visited[(x, y)] = 1

    return x == 0 and y == 0 and visited[(x, y)] <= 2

def solve():
    q = int(input())
    for _ in range(q):
        s = input()
        if is_valid_sequence(s):
            print(len(s))
            print(s)
        else:
            valid_length = 0
            valid_sequence = ""
            for i in range(len(s)):
                for j in range(i + 1, len(s) + 1):
                    subseq = s[i:j]
                    if rearrange_sequence(subseq):
                        valid_length = max(valid_length, len(subseq))
                        valid_sequence = subseq
            print(valid_length)
            print(valid_sequence)

