def ternary_xor(a, b):
    return ''.join(str((int(a[i]) + int(b[i])) % 3) for i in range(len(a)))

def find_min_xor(a, b):
    return min(int(a, 3), int(b, 3))

def solve_test_case(n, x):
    a = '0' * n
    b = '0' * n
    carry = 0

    for i in range(n):
        # Calculate the current digit of the XOR result
        xor_digit = (int(x[i]) + carry) % 3

        # Determine the digits of a and b
        if xor_digit == 0:
            a = a[:i] + '0' + a[i+1:]
            b = b[:i] + '2' + b[i+1:]
        elif xor_digit == 1:
            a = a[:i] + '1' + a[i+1:]
            b = b[:i] + '1' + b[i+1:]
        else:  # xor_digit == 2
            a = a[:i] + '2' + a[i+1:]
            b = b[:i] + '0' + b[i+1:]

        # Update the carry
        carry = (int(x[i]) + carry) // 3

    return a, b

def main():
