import re

def is_valid_credit_card(card_number):
    # Regular expression to match the valid credit card number pattern
    pattern = r'^[456]\d{15}$|^[456]\d{3}-\d{4}-\d{4}-\d{4}$'

    # Check if the card number matches the pattern
    if re.match(pattern, card_number):
        # Check for consecutive digits
        for i in range(len(card_number) - 3):
            if card_number[i:i+4].count(card_number[i]) >= 4:
                return False
        return True
    return False

