from html.parser import HTMLParser

class MyHTMLParser(HTMLParser):
    def __init__(self):
        super().__init__()
        self.single_line_comments = []
        self.multi_line_comments = []
        self.data = []

    def handle_comment(self, data):
        if data.startswith('<!--') and data.endswith('-->'):
            self.multi_line_comments.append(data[4:-3])
        else:
            self.single_line_comments.append(data)

    def handle_data(self, data):
        if data.strip():
            self.data.append(data)

    def get_results(self):
        results = []
        if self.single_line_comments:
            results.append("Single-line Comment")
            for comment in self.single_line_comments:
                results.append(comment)
            results.append("Data")
        if self.multi_line_comments:
            results.append("Multi-line Comment")
            for comment in self.multi_line_comments:
                results.append(comment)
            results.append("Data")
        if self.data:
            results.append("Data")
            for data in self.data:
                results.append(data)
        return results

def main():
    n = int(input())
    parser = MyHTMLParser()

    for _ in range(n):
        parser.feed(input())

    results = parser.get_results()
    for result in results:
        print(result)

