import re

def is_valid_uid(uid):
    # Check if the UID has exactly 10 characters
    if len(uid) != 10:
        return False

    # Check if there are at least 2 uppercase English alphabet characters
    if sum(1 for c in uid if c.isupper()) < 2:
        return False

    # Check if there are at least 3 digits
    if sum(1 for c in uid if c.isdigit()) < 3:
        return False

    # Check if all characters are alphanumeric
    if not uid.isalnum():
        return False

    # Check if no character repeats
    if len(set(uid)) != 10:
        return False

    return True

def main():
    T = int(input().strip())
    for _ in range(T):
        uid = input().strip()
        if is_valid_uid(uid):
            print("Valid")
        else:
            print("Invalid")

