def solve(a, b, c):
    # Calculate the minimum number of operations needed
    operations = 0
    while b % a != 0 or c % b != 0:
        if b % a != 0:
            b += 1
            operations += 1
        if c % b != 0:
            c += 1
            operations += 1
    return operations, a, b, c

