def is_regular(s):
    balance = 0
    for char in s:
        if char == '(':
            balance += 1
        else:
            balance -= 1
        if balance < 0:
            return False
    return balance == 0

def count_regular_positions(n, s):
    count = 0
    for i in range(n):
        # Change the i-th bracket to '('
        if s[i] == ')':
            new_s = s[:i] + '(' + s[i+1:]
        else:
            new_s = s[:i] + ')' + s[i+1:]

        # Check if the new sequence is regular
        if is_regular(new_s):
            count += 1
    return count

