    # Check if the lengths of S and T are equal
    if len(S) != len(T):
        return "No"

    # Create a dictionary to count the frequency of each character in S
    S_count = {}
    for char in S:
        if char in S_count:
            S_count[char] += 1
        else:
            S_count[char] = 1

    # Create a dictionary to count the frequency of each character in T
    T_count = {}
    for char in T:
        if char in T_count:
            T_count[char] += 1
