def is_power_of_two(x):
    return x > 0 and (x & (x - 1)) == 0

def min_deletions_to_make_good(sequence):
    n = len(sequence)
    if n == 0:
        return 0

    # Dictionary to store the frequency of each number
    frequency = defaultdict(int)
    for num in sequence:
        frequency[num] += 1

    deletions = 0

    # Iterate over each number in the sequence
    for num in sequence:
        if frequency[num] > 0:
            # Check if there exists another number such that their sum is a power of two
            for j in range(1, 10**9 + 1):
                if is_power_of_two(num + j) and frequency[j] > 0:
                    frequency[num] -= 1
                    frequency[j] -= 1
                    deletions += 1
                    break
            else:
                deletions += 1

    return deletions

