def count_valid_choices(H, W, K, grid):
    total_black_squares = 0

    # Count the total number of black squares in the grid
    for i in range(H):
        for j in range(W):
            if grid[i][j] == '#':
                total_black_squares += 1

    # Initialize the count of valid choices
    valid_choices = 0

    # Iterate over all possible numbers of rows and columns to choose
    for rows in range(H + 1):
        for cols in range(W + 1):
            # Calculate the number of black squares remaining after painting
            remaining_black_squares = total_black_squares - rows * W - cols * H + rows * cols

            # Check if the remaining black squares equal K
            if remaining_black_squares == K:
                valid_choices += 1

    return valid_choices

