def draw_star_grid(n, m, grid):
    # Check if it's possible to draw the grid using stars
    for i in range(n):
        for j in range(m):
            if grid[i][j] == '*':
                # Try to find a star that can cover this cell
                found = False
                for size in range(1, min(n, m) + 1):
                    if i - size >= 0 and i + size < n and j - size >= 0 and j + size < m:
                        if all(grid[i - k][j] == '.' for k in range(1, size + 1)) and \
                           all(grid[i + k][j] == '.' for k in range(1, size + 1)) and \
                           all(grid[i][j - k] == '.' for k in range(1, size + 1)) and \
                           all(grid[i][j + k] == '.' for k in range(1, size + 1)):
                            found = True
                            break
                if not found:
                    return -1
    # If all cells are covered, draw the grid using stars
    stars = []
    for i in range(n):
        for j in range(m):
            if grid[i][j] == '*':
                size = 1
                while i - size >= 0 and i + size < n and j - size >= 0 and j + size < m:
                    if all(grid[i - k][j] == '.' for k in range(1, size + 1)) and \
                       all(grid[i + k][j] == '.' for k in range(1, size + 1)) and \
                       all(grid[i][j - k] == '.' for k in range(1, size + 1)) and \
                       all(grid[i][j + k] == '.' for k in range(1, size + 1)):
                        size += 1
                stars.append((i + 1, j + 1, size - 1))
    # Output the number of stars and their positions
    print(len(stars))
    for x, y, s in stars:
        print(x, y, s)

