def solve_query(k, n, a, b):
    if k < a:
        return -1
    if k < b:
        return -1
    if k == a and k == b:
        return -1

    # Calculate the maximum number of first type turns
    max_first_type_turns = (k - a) // b + 1
    if max_first_type_turns > n:
        return -1

    # Calculate the remaining charge after max_first_type_turns
    remaining_charge = k - max_first_type_turns * b

    # Check if the remaining charge is enough for the last turn
    if remaining_charge < a:
        return -1

    return max_first_type_turns

