def compress_grid(H, W, grid):
    # Convert the input grid to a list of lists for easier manipulation
    grid = [list(row) for row in grid]

    # Function to check if a row or column is entirely white
    def is_all_white(row):
        return all(cell == '.' for cell in row)

    # Function to check if a column is entirely white
    def is_all_white_column(col):
        return all(grid[row][col] == '.' for row in range(H))

    # List to keep track of rows and columns to remove
    rows_to_remove = []
    cols_to_remove = []

    # Identify rows to remove
    for i in range(H):
        if is_all_white(grid[i]):
            rows_to_remove.append(i)

    # Identify columns to remove
    for j in range(W):
        if is_all_white_column(j):
            cols_to_remove.append(j)

    # Remove identified rows and columns
    for i in rows_to_remove:
        del grid[i]

    for j in cols_to_remove:
        for row in grid:
            del row[j]

    # Convert the grid back to a string format
    final_grid = [''.join(row) for row in grid]

    # Print the final grid
    for row in final_grid:
        print(row)

