from collections import defaultdict

def solve_queries(queries):
    results = []
    for n, p in queries:
        seen = defaultdict(int)
        day = 0
        for i in range(n):
            if seen[p[i]] > 0:
                results.append(day - seen[p[i]] + 1)
            else:
                seen[p[i]] = day + 1
            day += 1
    return results

