def find_shortest_substring_to_remove(path):
    n = len(path)
    x_move = 0
    y_move = 0
    min_length = n + 1
    start_index = -1
    end_index = -1

    for i, char in enumerate(path):
        if char == 'L':
            x_move -= 1
        elif char == 'R':
            x_move += 1
        elif char == 'U':
            y_move += 1
        elif char == 'D':
            y_move -= 1

        if x_move == 0 and y_move == 0:
            if i - start_index + 1 < min_length:
                min_length = i - start_index + 1
                start_index = i - min_length + 1
                end_index = i

    if start_index == -1:
        return -1
    else:
        return start_index, end_index

def main():
    t = int(input())
    for _ in range(t):
        n = int(input())
        path = input()
        result = find_shortest_substring_to_remove(path)
        if result == -1:
            print(-1)
        else:
            print(result[0] + 1, result[1] + 1)

