def min_moves_to_divisible(a, k):
    n = len(a)
    total_moves = 0
    for i in range(n):
        remainder = a[i] % k
        if remainder != 0:
            moves = k - remainder
            total_moves += moves
            a[i] += moves
    return total_moves

