def can_partition(a):
    n = len(a)
    even_count = sum(1 for x in a if x % 2 == 0)
    odd_count = n - even_count

    if even_count == odd_count:
        return "YES"
    elif even_count == odd_count + 1:
        return "YES"
    elif odd_count == even_count + 1:
        return "YES"
    elif even_count == odd_count + 2:
        return "YES"
    elif odd_count == even_count + 2:
        return "YES"
    else:
        return "NO"

