def find_smallest_good_number(n):
    # Convert n to a list of its digits in base 3
    digits = []
    while n > 0:
        digits.append(n % 3)
        n //= 3
    digits.reverse()

    # Find the smallest good number greater than or equal to n
    for i in range(len(digits)):
        if digits[i] == 2:
            # If the current digit is 2, replace it with 0 and carry over 1 to the next digit
            digits[i] = 0
            if i > 0:
                digits[i - 1] += 1
            else:
                # If the first digit is 2, we need to add a new digit 1 at the beginning
                digits.insert(0, 1)
                break
        elif digits[i] == 1:
            # If the current digit is 1, replace it with 0 and carry over 1 to the next digit
            digits[i] = 0
            if i > 0:
                digits[i - 1] += 1
            else:
                # If the first digit is 1, we need to add a new digit 1 at the beginning
                digits.insert(0, 1)
                break
        else:
            # If the current digit is 0, we can leave it as is
            continue

    # Convert the list of digits back to an integer
    return sum(digit * (3 ** i) for i, digit in enumerate(reversed(digits)))

