def solve(n, k):
    if n % 2 == 0:
        # If n is even, we can split it into k even numbers
        if n // k % 2 == 0:
            return "YES", [n // k] * k
        else:
            return "NO"
    else:
        # If n is odd, we need to split it into k odd numbers
        if n // k % 2 == 1:
            return "YES", [n // k] * k
        else:
            return "NO"

