import sys

def gcd(x, y):
    while y:
        x, y = y, x % y
    return x

def max_gcd(a):
    max_gcd_val = 0
    for b in range(1, a):
        xor_val = a ^ b
        and_val = a & b
        current_gcd = gcd(xor_val, and_val)
        if current_gcd > max_gcd_val:
            max_gcd_val = current_gcd
    return max_gcd_val

def main():
    q = int(sys.stdin.readline())
    results = []
    for _ in range(q):
        a = int(sys.stdin.readline())
        results.append(max_gcd(a))
    for result in results:
        print(result)

