import sys

def can_transform(A, B):
    n, m = len(A), len(A[0])
    operations = []

    for i in range(n - 1):
        for j in range(m - 1):
            if A[i][j] != B[i][j]:
                operations.append((i + 1, j + 1))

    if len(operations) > 2500:
        return -1

    return operations

def main():
    n, m = map(int, sys.stdin.readline().split())
    A = [list(map(int, sys.stdin.readline().split())) for _ in range(n)]
    B = [[0] * m for _ in range(n)]

    result = can_transform(A, B)
    if result == -1:
        print(-1)
    else:
        print(len(result))
        for x, y in result:
            print(x, y)

if __name__ == "__main__":
    main()

