def min_p_binary_summands(n, p):
    if n == 0:
        return 0

    # Check if p is zero
    if p == 0:
        # If n is a power of two, return 1
        if n & (n - 1) == 0:
            return 1
        else:
            return -1

    # Check if p is negative
    if p < 0:
        # If n is a power of two, return 1
        if n & (n - 1) == 0:
            return 1
        else:
            # If n is less than or equal to -p, return 1
            if n <= -p:
                return 1
            else:
                # Otherwise, return 2
                return 2

    # If p is positive
    # Check if n is a power of two
    if n & (n - 1) == 0:
        # If n is less than or equal to p, return 1
        if n <= p:
            return 1
        else:
            # Otherwise, return 2
            return 2

