def solve(n, k, initial_state, subsets):
    m = [0] * (n + 1)

    for i in range(1, n + 1):
        # Determine which lamps are affected by the current subset
        affected = set()
        for j in range(k):
            if i in subsets[j]:
                affected.add(i)

        # Calculate the minimum operations required to make the first i lamps on
        for j in range(1, i + 1):
            if j in affected:
                m[i] = min(m[i], m[j - 1] + 1)
            else:
                m[i] = min(m[i], m[j - 1])

    return m[1:]

