import sys

def find_triangle(a, b, c, d):
    # Iterate over possible values of x, y, z
    for x in range(a, b + 1):
        for y in range(b, c + 1):
            for z in range(c, d + 1):
                # Check the triangle inequality
                if x + y > z:
                    return x, y, z
    return None

