import sys

def min_moves_to_k_periodic(s, k):
    n = len(s)
    moves = 0
    last_on = -1

    for i in range(n):
        if s[i] == '1':
            if last_on != -1 and (i - last_on) % k != 0:
                moves += 1
            last_on = i

    return moves

