def count_stable_arrays(n, k):
    # If k is greater than n, it's impossible to choose k distinct elements from {1, 2, ..., n}
    if k > n:
        return 0

    # The number of ways to choose k distinct elements from {1, 2, ..., n} is given by the binomial coefficient C(n, k)
    return comb(n, k)

