def is_valid_test_case(n, a, b):
    # Check if the arrays are already equal
    if a == b:
        return "Yes"

    # Check if the arrays are palindromes
    if a == b[::-1]:
        return "Yes"

    # Check if the arrays can be transformed into each other by swapping prefixes and suffixes
    for k in range(1, n // 2 + 1):
        if a[:k] == b[-k:] and a[k:] == b[:-k]:
            return "Yes"

    return "No"

