from fractions import Fraction

def princess_wins(w, b):
    if w == 0:
        return Fraction(0)
    if b == 0:
        return Fraction(1)

    # Calculate the probability of the princess winning
    # The princess wins if she draws a white mouse on her first turn
    # or if the dragon draws a black mouse and the princess wins on her second turn
    # or if the dragon draws a black mouse and the princess wins on her third turn, etc.
    # This can be represented as a geometric series
    p = Fraction(1, w)
    for i in range(1, b + 1):
        p += Fraction(1, w) * Fraction(b - i, b) * Fraction(1, w)

    return p

