from collections import defaultdict

def process_queries(n, m, friendships, queries):
    # Initialize the graph
    graph = defaultdict(list)
    for u, v in friendships:
        graph[u].append(v)
        graph[v].append(u)

    # Function to check if a noble is vulnerable
    def is_vulnerable(noble):
        if not graph[noble]:
            return False
        for friend in graph[noble]:
            if friend <= noble:
                return False
        return True

    # Function to perform the process
    def process():
        while True:
            vulnerable_nobles = [noble for noble in range(1, n + 1) if is_vulnerable(noble)]
            if not vulnerable_nobles:
                break
            for noble in vulnerable_nobles:
                for friend in graph[noble]:
                    graph[friend].remove(noble)
                graph[noble] = []

    # Process each query
    for query in queries:
        if query[0] == 1:
            u, v = query[1], query[2]
            graph[u].append(v)
            graph[v].append(u)
        elif query[0] == 2:
            u, v = query[1], query[2]
            graph[u].remove(v)
            graph[v].remove(u)
        elif query[0] == 3:
            process()
            remaining_nobles = [noble for noble in range(1, n + 1) if graph[noble]]
            print(len(remaining_nobles))

