def largest_friend_group(a):
    n = len(a)
    max_size = 0

    for i in range(n):
        for j in range(i, n):
            m = a[i] % a[j]
            if all(a[k] % m == m for k in range(i, j + 1)):
                max_size = max(max_size, j - i + 1)

    return max_size

