def find_wonderful_red_count(s):
    n = len(s)
    if n % 2 != 0:
        return 0

    # Count the frequency of each character
    char_count = {}
    for char in s:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    # Find the maximum frequency of any character
    max_freq = max(char_count.values())

    # If the maximum frequency is greater than half the length of the string, return 0
    if max_freq > n // 2:
        return 0

    # Otherwise, return the maximum frequency
    return max_freq

