from math import comb

def dfs(graph, node, parent, path):
    path.append(node)
    for neighbor in graph[node]:
        if neighbor != parent:
            dfs(graph, neighbor, node, path)
    return path

def count_valid_paths(graph, n, k):
    total_ways = 0
    for u in range(1, n + 1):
        for v in range(u + 1, n + 1):
            path = dfs(graph, u, None, [])
            path = [i for i in path if i <= v]
            if len(path) >= k:
                total_ways += comb(len(path), k)
    return total_ways % (10**9 + 7)

