def can_obtain_t(s, t):
    n = len(s)
    m = len(t)

    # Check if the length of t is within the possible range
    if m < n or m > 2 * n - 1:
        return "NO"

    # Check if the last character of t is the same as the last character of s
    if t[-1] != s[-1]:
        return "NO"

    # Check if the first character of t is the same as the first character of s
    if t[0] != s[0]:
        return "NO"

    # Check if the number of characters in t that are not in s is even
    count = 0
    for i in range(m):
        if t[i] != s[i]:
            count += 1
    if count % 2 != 0:
        return "NO"

    return "YES"

