from math import gcd
from collections import defaultdict

def min_new_nodes(n, queries):
    # Initialize the graph
    graph = defaultdict(list)
    for i in range(1, n + 1):
        for j in range(i + 1, n + 1):
            if gcd(i, j) > 1:
                graph[i].append(j)
                graph[j].append(i)

    # Precompute the prime factors for each node
    prime_factors = [set() for _ in range(n + 1)]
    for i in range(2, n + 1):
        for j in range(2, i + 1):
            if i % j == 0:
                prime_factors[i].add(j)
                while i % j == 0:
                    i //= j

    # Function to find the minimum number of new nodes to reach t from s
    def min_nodes_to_reach(s, t):
        if s == t:
            return 0
        visited = set()
        queue = [(s, 0)]
        while queue:
            node, steps = queue.pop(0)
            if node == t:
                return steps
            if node in visited:
                continue
            visited.add(node)
            for neighbor in graph[node]:
                if neighbor not in visited:
                    queue.append((neighbor, steps + 1))
        return float('inf')

    # Process each query
    results = []
    for s, t in queries:
        results.append(min_nodes_to_reach(s, t))

    return results

