def max_product_of_max_min(arr):
    n = len(arr)
    max_val = arr[0]
    min_val = arr[0]
    max_product = 0

    for i in range(1, n):
        if arr[i] > max_val:
            max_val = arr[i]
        elif arr[i] < min_val:
            min_val = arr[i]

        max_product = max(max_product, max_val * min_val)

    return max_product

