def is_palindrome(s):
    return s == s[::-1]

def min_operations_to_make_beautiful(s):
    n = len(s)
    dp = [[0] * n for _ in range(n)]

    # Fill the DP table
    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            if is_palindrome(s[i:j+1]):
                dp[i][j] = 1
            else:
                dp[i][j] = min(dp[i+1][j], dp[i][j-1]) + 1

    return dp[0][n-1]

