def min_swaps_to_alternate_parity(arr):
    n = len(arr)
    if n < 2:
        return 0

    # Count the number of odd and even elements
    odd_count = sum(1 for x in arr if x % 2 != 0)
    even_count = n - odd_count

    # If the difference between odd and even counts is more than 1, it's impossible
    if abs(odd_count - even_count) > 1:
        return -1

    # If the counts are equal, we can alternate them by swapping
    if odd_count == even_count:
        swaps = 0
        for i in range(1, n):
            if arr[i] % 2 == arr[i - 1] % 2:
                swaps += 1
        return swaps

    # If the counts differ by 1, we need to swap to make them equal
    swaps = 0
    if odd_count > even_count:
        # Swap odd elements to the end
        for i in range(n):
            if arr[i] % 2 != 0:
                swaps += 1
    else:
        # Swap even elements to the end
        for i in range(n):
            if arr[i] % 2 == 0:
                swaps += 1

    return swaps

