def min_imperfectness(s):
    n = len(s)
    min_imperfectness = float('inf')
    best_coloring = None

    # Try all possible colorings for the blank squares
    for i in range(n):
        if s[i] == '?':
            for color in ['B', 'R']:
                new_s = s[:i] + color + s[i+1:]
                current_imperfectness = 0
                for j in range(n-1):
                    if new_s[j] == new_s[j+1]:
                        current_imperfectness += 1
                if current_imperfectness < min_imperfectness:
                    min_imperfectness = current_imperfectness
                    best_coloring = new_s

    return best_coloring

