import sys

def find_hamiltonian_path(n, a):
    # Create the graph as an adjacency list
    graph = [[] for _ in range(n + 1)]
    for i in range(1, n):
        graph[i].append(i + 1)
    for i in range(n):
        if a[i] == 0:
            graph[n].append(i + 1)
        else:
            graph[i + 1].append(n)

    # Function to perform DFS and check for Hamiltonian path
    def dfs(node, visited, path):
        if len(path) == n + 1:
            return True
        visited[node] = True
        for neighbor in graph[node]:
            if not visited[neighbor]:
                if dfs(neighbor, visited, path + [neighbor]):
                    return True
        visited[node] = False
        return False

    # Try to find a Hamiltonian path starting from each vertex
    for start in range(1, n + 1):
        visited = [False] * (n + 1)
        if dfs(start, visited, [start]):
            return path

    return [-1]

