from collections import defaultdict

def can_reconstruct(t):
    n = len(t)
    last_occurrence = defaultdict(int)

    # Find the last occurrence of each letter in t
    for i, char in enumerate(t):
        last_occurrence[char] = i

    # Try to reconstruct s
    s = []
    for i in range(n):
        if t[i] in last_occurrence:
            # Remove the last occurrence of t[i] from s
            s.append(t[i])
            # Update the last occurrence of t[i] to the current position
            last_occurrence[t[i]] = i

    # Check if we have removed all occurrences of each letter
    for char in last_occurrence:
        if last_occurrence[char] != n - 1:
            return False

    return True

def solve(t):
    if can_reconstruct(t):
        # Find the order of removing letters
        order = []
        for i in range(len(t)):
            if t[i] in last_occurrence:
                order.append(t[i])
                last_occurrence[t[i]] = -1

        return ''.join(order), ' '.join(order)
    else:
        return '-1', '-1'

