import math

def is_prime(num):
    """Check if a number is prime."""
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

def max_digits_to_remove(n):
    """Find the maximum number of digits to remove to make n not prime."""
    k = len(str(n))
    for i in range(1, k):
        # Try removing the i-th digit
        num_str = str(n)
        for j in range(k - i):
            new_num_str = num_str[:j] + num_str[j + 1:]
            new_num = int(new_num_str)
            if not is_prime(new_num):
                return i, new_num_str
    return k, str(n)

