def find_lis(expansion):
    n = len(expansion)
    dp = [1] * n
    for i in range(1, n):
        for j in range(i):
            if expansion[i] >= expansion[j]:
                dp[i] = max(dp[i], dp[j] + 1)
    return max(dp)

