        # n is odd, median is the largest x such that x <= s and x >= ceil(s/2)
        return max(0, s - (n - 1))
    else:
        # n is even, median is the largest x such that x <= s and x >= ceil(s/2) - 1
        return max(0, s - (n - 2))

