from collections import defaultdict

def find_buds(n, edges):
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    def is_leaf(v):
        return len(graph[v]) == 1

    def is_bud(v):
        if is_leaf(v):
            return False
        for child in graph[v]:
            if not is_leaf(child):
                return False
        return True

    buds = [v for v in range(2, n + 1) if is_bud(v)]
    return buds

def rehang_buds(n, edges, buds):
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    def count_leaves(v):
        if is_leaf(v):
            return 1
        return sum(count_leaves(child) for child in graph[v])

    def rehang_bud(bud, target):
        nonlocal graph
        # Remove the bud and its children
        for child in graph[bud]:
            graph[child].remove(bud)
            if is_leaf(child):
                graph[child].append(target)
        # Add the bud to the target
        graph[target].append(bud)
        # Update the graph
        graph[bud] = []

    # Re-hang each bud to the vertex with the minimum number of leaves
    for bud in buds:
        min_leaves = float('inf')
        best_target = None
        for child in graph[bud]:
            if count_leaves(child) < min_leaves:
                min_leaves = count_leaves(child)
                best_target = child
        rehang_bud(bud, best_target)

    return count_leaves(1)

