    for i, char in enumerate(s):
        if char == '1':
            # Player with expectation 1 should not have any outgoing edges
            pass
        elif char == '2':
            # Player with expectation 2 should have at least one outgoing edge
            # Choose any other player to win against
            for j in range(n):
                if i != j and not graph[j]:
                    graph[i].append(j)
                    break

    # Construct the adjacency matrix
    matrix = [['X' if i == j else '+' if j in graph[i] else '-' if i in graph[j] else '=' for j in range(n)] for i in range(n)]

