from collections import defaultdict

def can_understand_book(chapters):
    n = len(chapters)
    required = defaultdict(list)

    # Build the graph of required chapters
    for i, reqs in enumerate(chapters):
        for req in reqs:
            required[req].append(i)

    # Check if the graph is acyclic
    visited = [False] * n
    stack = []

    def dfs(node):
        if visited[node]:
            return False
        visited[node] = True
        stack.append(node)
        for neighbor in required[node]:
            if not dfs(neighbor):
                return False
        stack.pop()
        return True

    if not all(dfs(i) for i in range(n)):
        return -1

    # Calculate the number of times the book needs to be read
    read_count = 0
    while True:
        read_count += 1
        all_understood = True
        for i in range(n):
            if not visited[i]:
                all_understood = False
                break
        if all_understood:
            break

    return read_count

