def min_erases_to_palindrome(s):
    n = len(s)
    if n == 1:
        return 0

    # Count the frequency of each character
    char_count = {}
    for char in s:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    # Count the number of characters that appear an odd number of times
    odd_count = sum(1 for count in char_count.values() if count % 2 != 0)

    # If there is more than one character with an odd count, it's impossible to make the string a palindrome
    if odd_count > 1:
        return -1

    # If there is exactly one character with an odd count, we can erase all occurrences except one
    if odd_count == 1:
        return n - char_count[s[odd_count // 2]]

    # If all characters appear an even number of times, we can erase all occurrences
    return 0

