def is_composite(n: int) -> bool:
    """Check if a number is composite."""
    if n <= 1:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return True
    return False

def find_largest_composite_subset(arr: List[int]) -> List[int]:
    """Find the largest subset with a composite sum."""
    n = len(arr)
    max_subset_size = 0
    best_subset = []

    # Try all possible subset sizes
    for size in range(1, n + 1):
        for subset in combinations(arr, size):
            if is_composite(sum(subset)):
                if size > max_subset_size:
                    max_subset_size = size
                    best_subset = subset

    return best_subset

