def dfs(node, parent, visited, restrictions, tree):
    visited[node] = True
    for neighbor in tree[node]:
        if not visited[neighbor]:
            # Check if the edge (node, neighbor) violates any restrictions
            if any((node, neighbor) in restrictions or (neighbor, node) in restrictions):
                # If it does, we need to find a different path
                # We can do this by temporarily removing the edge and trying to insert it again
                tree[node].remove(neighbor)
                tree[neighbor].remove(node)
                if dfs(neighbor, node, visited, restrictions, tree):
                    return True
                tree[node].append(neighbor)
                tree[neighbor].append(node)
            else:
                # If it doesn't violate any restrictions, proceed with the DFS
                if dfs(neighbor, node, visited, restrictions, tree):
                    return True
    return False

