def is_mastapeece(grid):
    n = len(grid)
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def dfs(x, y, color):
        stack = deque([(x, y, color)])
        visited = set()
        visited.add((x, y))

        while stack:
            cx, cy, ccolor = stack.popleft()
            for dx, dy in directions:
                nx, ny = cx + dx, cy + dy
                if 0 <= nx < n and 0 <= ny < n and grid[nx][ny] == ccolor and (nx, ny) not in visited:
                    stack.append((nx, ny, ccolor))
                    visited.add((nx, ny))

        return len(visited) == n * n

    for i in range(n):
        for j in range(n):
            if grid[i][j] == '.':
                grid[i][j] = 'G'
                if is_mastapeece(grid):
                    return True
                grid[i][j] = 'S'
                if is_mastapeece(grid):
                    return True
                grid[i][j] = '.'

    return False

