def is_special_number(n, number):
    # Check if the number can be expressed as a sum of different non-negative powers of n
    for i in range(n):
        power = n ** i
        if power > number:
            break
        if number - power >= 0:
            number -= power
            if number == 0:
                return True
    return False

def kth_special_number(n, k):
    count = 0
    number = 0
    while count < k:
        number += 1
        if is_special_number(n, number):
            count += 1
    return number % (10**9 + 7)

