def count_good_colorings(k):
    MOD = 10**9 + 7
    n = 2**k - 1
    dp = [[0] * 6 for _ in range(n + 1)]

    # Base case: the first node can be any of the 6 colors
    for j in range(6):
        dp[1][j] = 1

    # Fill the dp table
    for i in range(2, n + 1):
        for j in range(6):
            for k in range(6):
                if (j != k and (j != 0 or k != 5) and (j != 1 or k != 4) and (j != 2 or k != 3)):
                    dp[i][j] = (dp[i][j] + dp[i - 1][k]) % MOD

    # The total number of good colorings is the sum of dp[n][j] for all j
    total_good_colorings = sum(dp[n]) % MOD
    return total_good_colorings

