    # Case 1: All three problems have different topics
    ways_different_topics = 0
    for topic1 in topic_count:
        for topic2 in topic_count:
            if topic1 != topic2:
                for topic3 in topic_count:
                    if topic2 != topic3 and topic1 != topic3:
                        ways_different_topics += 1

    # Case 2: All three problems have different difficulties
    ways_different_difficulties = 0
    for difficulty1 in difficulty_count:
        for difficulty2 in difficulty_count:
            if difficulty1 != difficulty2:
                for difficulty3 in difficulty_count:
                    if difficulty2 != difficulty3 and difficulty1 != difficulty3:
                        ways_different_difficulties += 1

    # Total ways is the sum of both cases
    total_ways = ways_different_topics + ways_different_difficulties

    return total_ways

