def find_possible_k(n, a):
    # Create a dictionary to store the minimum AND result for each element
    min_and_results = defaultdict(lambda: float('inf'))

    # Iterate over all possible subsets of indices
    for i in range(1, n + 1):
        for j in range(i + 1, n + 1):
            for k in range(j + 1, n + 1):
                # Calculate the bitwise AND of the elements at indices i, j, and k
                and_result = a[i - 1] & a[j - 1] & a[k - 1]
                # Update the minimum AND result for each element
                for l in range(1, n + 1):
                    min_and_results[l] = min(min_and_results[l], and_result)

    # Find all possible values of k
    possible_k = set()
    for i in range(1, n + 1):
        for j in range(i + 1, n + 1):
            for k in range(j + 1, n + 1):
                # Calculate the bitwise AND of the elements at indices i, j, and k
                and_result = a[i - 1] & a[j - 1] & a[k - 1]
                # Check if the minimum AND result can be subtracted from each element
                if and_result <= min_and_results[i] and and_result <= min_and_results[j] and and_result <= min_and_results[k]:
                    possible_k.add(i)
                    possible_k.add(j)
                    possible_k.add(k)

    # Output the possible values of k
    print(' '.join(map(str, sorted(possible_k))))

