def count_valid_colorings(n, dominoes):
    mod = 998244353
    count = 0

    # Initialize the DP table
    dp = [0] * (1 << n)
    dp[0] = 1  # Base case: all cells are colored

    for i in range(n):
        left, right = dominoes[i]

        # Determine the possible states for the yet to be colored cells
        possible_states = 0
        if left == '?':
            possible_states |= 1 << i
        if right == '?':
            possible_states |= 1 << (i + 1) % n

        # Update the DP table
        for state in range(1 << n):
            if dp[state] == 0:
                continue
            if (state & possible_states) == 0:
                continue

            # Check if the current state is valid
            valid = True
            for j in range(n):
                if (state & (1 << j)) == 0:
                    continue
                if (state & (1 << (j + 1) % n)) != 0:
                    valid = False
                    break

            if valid:
                count = (count + dp[state]) % mod

    return count

