def can_reach_lab(grid, lab_row, lab_col):
    n, m = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]  # up, down, left, right

    def is_valid(x, y):
        return 0 <= x < n and 0 <= y < m and grid[x][y] != '#'

    def can_reach(x, y):
        if (x, y) == (lab_row, lab_col):
            return True
        visited = set()
        queue = [(x, y)]
        while queue:
            cx, cy = queue.pop(0)
            if (cx, cy) in visited:
                continue
            visited.add((cx, cy))
            for dx, dy in directions:
                nx, ny = cx + dx, cy + dy
                if is_valid(nx, ny) and (nx, ny) not in visited:
                    queue.append((nx, ny))
        return False

    for i in range(n):
        for j in range(m):
            if grid[i][j] == '.' and can_reach(i, j):
                grid[i][j] = '+'

    return grid

