from collections import defaultdict

def dfs(node, parent, value, visited, target_parity, path):
    visited[node] = True
    path.append(node)

    # Calculate the XOR of the values on the path
    xor_value = value

    for neighbor in graph[node]:
        if not visited[neighbor]:
            xor_value ^= dfs(neighbor, node, value, visited, target_parity, path)

    # Check if the parity of the number of set bits matches the target parity
    if bin(xor_value).count('1') % 2 != target_parity:
        return False

    # If we reach the root, check if the path is valid
    if node == 1:
        return True

    # Try assigning different values to the edge
    for v in range(2**30):
        if v != value:
            if dfs(node, parent, v, visited, target_parity, path):
                return True

    # Backtrack
    path.pop()
    visited[node] = False
    return False

