def max_min_joy(n, m, p):
    # Function to check if it's possible to achieve a minimum joy of at least 'min_joy'
    def is_possible(min_joy):
        visited = [False] * m
        for j in range(n):
            found = False
            for i in range(m):
                if not visited[i] and p[i][j] >= min_joy:
                    visited[i] = True
                    found = True
                    break
            if not found:
                return False
        return True

    # Binary search for the maximum possible minimum joy
    left, right = 1, 10**9
    while left < right:
        mid = (left + right + 1) // 2
        if is_possible(mid):
            left = mid
        else:
            right = mid - 1

    return left

