import sys

def min_operations_to_mex(n, a):
    # Initialize the result array with -1
    result = [-1] * (n + 1)

    # Iterate over each possible MEX value
    for i in range(n + 1):
        # Check if it is possible to achieve MEX = i
        if i in a:
            # If i is already present, we need to decrement the elements to ensure 0 to i-1 are not present
            for j in range(i):
                if j in a:
                    a[j] -= 1
            # Now, we need to increment the elements to ensure i is present
            for j in range(i):
                if j not in a:
                    a[j] += 1
            # Finally, we need to decrement the elements to ensure i+1 and above are not present
            for j in range(i + 1, n + 1):
                if j in a:
                    a[j] -= 1
            # Calculate the number of operations
            operations = sum(a)
            result[i] = operations

    return result

