import sys

def is_bipartite(p):
    n = len(p)
    color = [0] * n
    for i in range(n):
        if color[i] == 0:
            color[i] = 1
            stack = [i]
            while stack:
                u = stack.pop()
                for v in range(n):
                    if p[u] > p[v] and color[v] == 0:
                        color[v] = -color[u]
                        stack.append(v)
                    elif p[u] < p[v] and color[v] == 0:
                        return False
                    elif p[u] == p[v]:
                        return False
    return True

