import math

def is_square(x):
    s = int(math.sqrt(x))
    return s * s == x

def find_max_quadratic_subset(n):
    # Start with the largest number and work downwards
    subset = []
    for i in range(n, 0, -1):
        if is_square(math.factorial(i)):
            subset.append(i)
            # Check if the remaining numbers can form a square with the current subset
            if is_square(math.prod(math.factorial(j) for j in range(1, i))):
                break
    return subset

