from typing import List

def generate_fibonacci_strings(k: int) -> List[str]:
    fib_strings = ["a", "b"]
    while len(fib_strings) < k:
        next_fib = fib_strings[-1] + fib_strings[-2]
        fib_strings.append(next_fib)
    return fib_strings

def rolling_hash(s: str, base: int, mod: int) -> int:
    hash_value = 0
    for char in s:
        hash_value = (hash_value * base + ord(char)) % mod
    return hash_value

def count_occurrences(fib_strings: List[str], queries: List[str]) -> List[int]:
    mod = 10**9 + 7
    base = 256  # ASCII value of 'a' and 'b'

    # Precompute the rolling hash values for each query string
    query_hashes = {query: rolling_hash(query, base, mod) for query in queries}

    # Precompute the rolling hash values for each Fibonacci string
    fib_hashes = {i: rolling_hash(fib_strings[i], base, mod) for i in range(len(fib_strings))}

    # Initialize the result list
    result = []

    # Iterate over each query string
    for query in queries:
        count = 0
        query_hash = query_hashes[query]

        # Iterate over each Fibonacci string
        for i in range(len(fib_strings)):
            fib_hash = fib_hashes[i]
            if i > 0:
                fib_hash = (fib_hash - rolling_hash(fib_strings[i-1], base, mod) * base) % mod
            if fib_hash == query_hash:
                count += 1
                count %= mod

        result.append(count)

    return result

def main():
    k, m = map(int, input().split())
    queries = [input().strip() for _ in range(m)]

    fib_strings = generate_fibonacci_strings(k)
    result = count_occurrences(fib_strings, queries)

    for count in result:
        print(count)

