def dfs(r, c, reclaimed, turn):
    # If all cells are reclaimed, the current player loses
    if len(reclaimed) == r * 2:
        return False

    # If it's the current player's turn, try to reclaim a cell
    if turn == 1:
        for i in range(1, r + 1):
            for j in range(1, 3):
                if can_reclaim(i, j, reclaimed):
                    # Reclaim the cell and switch turns
                    new_reclaimed = reclaimed + [(i, j)]
                    if not dfs(i, j, new_reclaimed, 2):
                        return True
    # If it's the opponent's turn, try to block the current player
    else:
        for i in range(1, r + 1):
            for j in range(1, 3):
                if can_reclaim(i, j, reclaimed):
                    # Reclaim the cell and switch turns
                    new_reclaimed = reclaimed + [(i, j)]
                    if dfs(i, j, new_reclaimed, 1):
                        return False

    # If the current player cannot reclaim a cell, they lose
    return False

def solve(r, n, reclaimed):
    # Convert the list of reclaimed cells to a set for faster lookup
    reclaimed_set = set(reclaimed)

    # Start the DFS from the first cell
    if dfs(1, 1, reclaimed, 1):
        return "WIN"
    else:
        return "LOSE"

