from collections import deque

def can_transform(s, t):
    n = len(s)
    if n != len(t):
        return False

    # Function to perform the shift operation
    def shift(s, x):
        return s[x:] + s[:x]

    # BFS to find the shortest sequence of operations
    queue = deque([(s, [])])
    visited = set([s])

    while queue:
        current, path = queue.popleft()

        # Check if the current state is the target state
        if current == t:
            return path

        # Try all possible shift operations
        for x in range(n + 1):
            new_state = shift(current, x)
            if new_state not in visited:
                visited.add(new_state)
                queue.append((new_state, path + [x]))

    # If no transformation is found
    return None

def main():
