import heapq

def dijkstra(graph, start):
    distances = {node: float('inf') for node in graph}
    distances[start] = 0
    pq = [(0, start)]

    while pq:
        current_distance, current_node = heapq.heappop(pq)

        if current_distance > distances[current_node]:
            continue

        for neighbor, weight in graph[current_node].items():
            distance = current_distance + weight

            if distance < distances[neighbor]:
                distances[neighbor] = distance
                heapq.heappush(pq, (distance, neighbor))

    return distances

def count_valid_pairs(n, m, s, t, roads):
    graph = {i: {} for i in range(1, n + 1)}

    for u, v in roads:
        graph[u][v] = 1
        graph[v][u] = 1

    # Calculate the shortest path from s to t
    distances = dijkstra(graph, s)

    # Count pairs that are not connected and would not decrease the distance from s to t
    valid_pairs = 0

    for u in range(1, n + 1):
        for v in range(u + 1, n + 1):
            if v not in graph[u]:
                # Check if building a road between u and v would decrease the distance from s to t
                if distances[u] + 1 < distances[t]:
                    valid_pairs += 1

    return valid_pairs

