def caesar_cipher_decrypt(ciphertext, shift):
    alphabet = 'abcdefghijklmnopqrstuvwxyz'
    decrypted_text = ''
    for char in ciphertext:
        if char.isalpha():
            original_index = alphabet.index(char.lower())
            new_index = (original_index - shift) % 26
            new_char = alphabet[new_index]
            decrypted_text += new_char.upper() if char.isupper() else new_char
        else:
            decrypted_text += char
    return decrypted_text

def find_decoded_text(ciphertexts):
    for ciphertext in ciphertexts:
        for shift in range(26):
            decrypted_text = caesar_cipher_decrypt(ciphertext, shift)
            if 'the' in decrypted_text or 'this' in decrypted_text or 'that' in decrypted_text:
                return decrypted_text

