from math import gcd
from collections import defaultdict

def coprime_sortable(sequence):
    n = len(sequence)
    prime_factors = defaultdict(list)

    # Find prime factors for each number in the sequence
    for i in range(n):
        for j in range(i + 1, n):
            if gcd(sequence[i], sequence[j]) > 1:
                prime_factors[sequence[i]].append(sequence[j])
                prime_factors[sequence[j]].append(sequence[i])

    # Check if the sequence can be sorted using coprime swaps
    visited = [False] * n
    for i in range(n):
        if not visited[i]:
            stack = [i]
            while stack:
                node = stack.pop()
                visited[node] = True
                for neighbor in prime_factors[node]:
                    if not visited[neighbor]:
                        stack.append(neighbor)

    # If all nodes are visited, the sequence is coprime-sortable
    return all(visited)

