def count_commuting_routes(w, h):
    # Initialize a 2D list to store the number of valid paths to each cell
    dp = [[0] * (h + 1) for _ in range(w + 1)]

    # Base case: There is one way to stay at the starting point (1, 1)
    dp[1][1] = 1

    # Fill the dp table
    for i in range(1, w + 1):
        for j in range(1, h + 1):
            # A car cannot turn immediately after turning, so we need to check the previous cell
            if i > 1:
                dp[i][j] += dp[i - 1][j]
            if j > 1:
                dp[i][j] += dp[i][j - 1]

    # The number of valid paths to (w, h) is stored in dp[w][h]
    return dp[w][h]

