import sys

def max_profit(C, D, W, X, E, F):
    # Initialize the DP table
    dp = [[[0 for _ in range(X + 1)] for _ in range(D + 1)] for _ in range(C + 1)]

    # Fill the DP table
    for i in range(1, C + 1):
        for j in range(1, D + 1):
            for k in range(X + 1):
                if E[i][j] == 0:
                    dp[i][j][k] = dp[i-1][j][k]
                else:
                    for l in range(max(0, k - F[i][j]), min(X, k) + 1):
                        dp[i][j][k] = max(dp[i][j][k], dp[i-1][j][l] + E[i][j])

    # Find the maximum profit for the last day
    max_profit = 0
    for k in range(X + 1):
        max_profit = max(max_profit, dp[C][D][k])

    return max_profit

