def count_members(group_specs):
    group_members = {}

    for spec in group_specs:
        group, members = spec.split(':')
        members = members.split(',')
        group_members[group] = set(members)

    def find_members(group):
        if group not in group_members:
            return set()
        members = group_members[group]
        for member in members:
            members.update(find_members(member))
        return members

    first_group = group_specs[0].split(':')[0]
    return len(find_members(first_group))

