def othello_board(n, m, a, b, c, d):
    board = [['.' for _ in range(m)] for _ in range(n)]
    board[a-1][b-1] = 'x'
    board[c-1][d-1] = 'o'

    def flip_stones(x, y, dx, dy):
        if x < 1 or x > n or y < 1 or y > m or board[x-1][y-1] != 'o':
            return 0
        board[x-1][y-1] = 'x'
        count = 1
        while True:
            x += dx
            y += dy
            if x < 1 or x > n or y < 1 or y > m or board[x-1][y-1] != 'x':
                break
            board[x-1][y-1] = 'o'
            count += 1
        return count

    def count_stones_in_area(x1, y1, x2, y2):
        count = 0
        for i in range(x1, x2+1):
            for j in range(y1, y2+1):
                if board[i-1][j-1] == 'x':
                    count += 1
        return count

    max_stones = 0
    for i in range(1, n+1):
        for j in range(1, m+1):
            if board[i-1][j-1] == 'x':
                for dx in [-1, 0, 1]:
                    for dy in [-1, 0, 1]:
                        if dx != 0 or dy != 0:
                            stones_flipped = flip_stones(i, j, dx, dy)
                            stones_in_area = count_stones_in_area(i, j, i+stones_flipped-1, j+stones_flipped-1)
                            max_stones = max(max_stones, stones_in_area)

    return max_stones

