from collections import defaultdict

def min_roads_to_same_state(N, M, roads):
    # Build the graph
    graph = defaultdict(list)
    for u, v in roads:
        graph[u].append(v)
        graph[v].append(u)

    # Check if the graph is bipartite
    def is_bipartite(graph):
        color = [-1] * (N + 1)
        for i in range(1, N + 1):
            if color[i] == -1:
                if not dfs(i, 0, graph, color):
                    return False
        return True

    def dfs(node, color, graph, color_map):
        color_map[node] = color
        for neighbor in graph[node]:
            if color_map[neighbor] == color:
                return False
            if color_map[neighbor] == -1:
                if not dfs(neighbor, 1 - color, graph, color_map):
                    return False
        return True

    if not is_bipartite(graph):
        return -1

    # Count the number of roads between different parts of the bipartite graph
    def count_roads_between_parts(graph, color_map):
        count = 0
        for i in range(1, N + 1):
            for neighbor in graph[i]:
                if color_map[i] != color_map[neighbor]:
                    count += 1
        return count

    return count_roads_between_parts(graph, color_map)

