import heapq
from collections import defaultdict

def dijkstra(grid, start):
    H, W = len(grid), len(grid[0])
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    distances = [[float('inf')] * W for _ in range(H)]
    distances[start[0]][start[1]] = 0
    pq = [(0, start)]

    while pq:
        dist, (x, y) = heapq.heappop(pq)

        if dist > distances[x][y]:
            continue

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < H and 0 <= ny < W and grid[nx][ny] == 0:
                new_dist = dist + 1
                if new_dist < distances[nx][ny]:
                    distances[nx][ny] = new_dist
                    heapq.heappush(pq, (new_dist, (nx, ny)))

    return distances

def shortest_distances(H, W, N, black_squares):
    grid = [[1] * W for _ in range(H)]
    for x, y in black_squares:
        grid[x][y] = 0

    total_distance = 0
    for i in range(H):
        for j in range(W):
            if grid[i][j] == 0:
                distances = dijkstra(grid, (i, j))
                for k in range(H):
                    for l in range(W):
                        if grid[k][l] == 0:
                            total_distance += distances[k][l]

    return total_distance % (10**9 + 7)

