import heapq

def func(lists, k):
    # Flatten the list of lists and count the frequency of each integer
    frequency = Counter(num for sublist in lists for num in sublist)
    # Use a min heap to keep track of the top k frequent integers
    min_heap = []
    for num, freq in frequency.items():
        if len(min_heap) < k:
            heapq.heappush(min_heap, (freq, num))
        elif freq > min_heap[0][0]:
            heapq.heappop(min_heap)
            heapq.heappush(min_heap, (freq, num))
    # Extract the integers from the heap and sort them in descending order
    top_k = [heapq.heappop(min_heap)[1] for _ in range(len(min_heap))]
    return sorted(top_k, reverse=True)

