    while start <= end:
        if arr[start] <= arr[end]:
            return start
        mid = (start + end) // 2
        next_index = (mid + 1) % n
        prev_index = (mid - 1 + n) % n
        if arr[mid] <= arr[next_index] and arr[mid] <= arr[prev_index]:
