def roman_to_int(s):
    roman_dict = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    total = 0
    prev_value = 0
    for char in reversed(s):
        value = roman_dict[char]
        if value < prev_value:
            total -= value
        else:
            total += value
        prev_value = value
    return total

def join_tuples(test_list):
    res = []
    for ele in test_list:
        if not res or ele[0] != res[-1][0]:
            res.append(ele)
        else:
            res[-1] = res[-1] + ele[1:]
    return res

def maximum_segments(n, a, b, c):
    # Initialize a list to store the maximum number of segments for each length up to n
    dp = [-1] * (n + 1)
    dp[0] = 0  # Base case: 0 segments for length 0

    # Iterate through each length from 1 to n
    for i in range(1, n + 1):
        # Check if segments of lengths a, b, and c can be used to form the current length
        if i >= a and dp[i - a] != -1:
            dp[i] = max(dp[i], dp[i - a] + 1)
        if i >= b and dp[i - b] != -1:
            dp[i] = max(dp[i], dp[i - b] + 1)
        if i >= c and dp[i - c] != -1:
            dp[i] = max(dp[i], dp[i - c] + 1)

    # Return the maximum number of segments for length n
    return dp[n]

def min_sum_path(triangle):
    n = len(triangle)
    for i in range(n-2, -1, -1):
        for j in range(len(triangle[i])):
            triangle[i][j] += min(triangle[i+1][j], triangle[i+1][j+1])
    return triangle[0][0]

def decimal_to_binary(decimal_number):
    binary_number = ''
    while decimal_number > 0:
        binary_number = str(decimal_number % 2) + binary_number
        decimal_number = decimal_number // 2
    return binary_number

