def histogram(test):
    if not test:
        return {}

    words = test.split()
    count = {}
    max_count = 0

    for word in words:
        if word in count:
            count[word] += 1
        else:
            count[word] = 1
        max_count = max(max_count, count[word])

    return {word: cnt for word, cnt in count.items() if cnt == max_count}

