from datetime import datetime

def valid_date(date):
    if not date:
        return False
    try:
        month, day, year = map(int, date.split('-'))
        if month < 1 or month > 12:
            return False
        if day < 1 or day > 31:
            return False
        if month in [4, 6, 9, 11] and day > 30:
            return False
        if month == 2 and day > 29:
            return False
        datetime(year, month, day)
        return True
    except ValueError:
        return False

