def prime_length(string):
    length = len(string)
    if length < 2:
        return False
    for i in range(2, int(length ** 0.5) + 1):
        if length % i == 0:
            return False
    return True

def starts_one_ends(n):
    if n == 1:
        return 1
    return 18 * (10 ** (n - 2))

def get_row(lst, x):
    result = []
    for i, row in enumerate(lst):
        for j, value in enumerate(row):
            if value == x:
                result.append((i, j))
    result.sort(key=lambda x: (x[0], -x[1]))
    return result

def sort_array(array):
    if not array:
        return []
    if len(array) == 1:
        return array[:]
    if (array[0] + array[-1]) % 2 == 0:
        return sorted(array, reverse=True)
    else:
        return sorted(array)

def encrypt(s):
    result = []
    for char in s:
        if char.isalpha():
            shift = (2 * 2) % 26
            if char.islower():
                result.append(chr((ord(char) - ord('a') + shift) % 26 + ord('a')))
            else:
                result.append(chr((ord(char) - ord('A') + shift) % 26 + ord('A')))
        else:
            result.append(char)
    return ''.join(result)

from typing import List


def rolling_max(numbers: List[int]) -> List[int]:
    if not numbers:
        return []

    result = []
    current_max = numbers[0]
    for number in numbers:
        current_max = max(current_max, number)
        result.append(current_max)

    return result

def next_smallest(lst):
    unique_elements = sorted(set(lst))
    return unique_elements[1] if len(unique_elements) > 1 else None

def is_bored(S):
    import re
    sentences = re.split(r'[.?!]\s*', S)
    return sum(1 for sentence in sentences if sentence.startswith("I "))

def encode(message):
    vowels = 'aeiou'
    shifted_vowels = {v: chr((ord(v) - 97 + 2) % 26 + 97) for v in vowels}
    shifted_vowels.update({v.upper(): shifted_vowels[v].upper() for v in vowels})
    return ''.join(shifted_vowels.get(c, c).swapcase() for c in message)

def is_prime(n):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def skjkasdkd(lst):
    max_prime = 0
    for num in lst:
        if num > max_prime and is_prime(num):
            max_prime = num
    return sum(int(digit) for digit in str(max_prime))

def count_up_to(n):
    def is_prime(num):
        if num <= 1:
            return False
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                return False
        return True

    return [num for num in range(2, n) if is_prime(num)]

def count_upper(s):
    vowels = 'AEIOU'
    return sum(1 for i, char in enumerate(s) if i % 2 == 0 and char in vowels)

def closest_integer(value):
    num = float(value)
    if num > 0:
        return int(num + 0.5)
    else:
        return int(num - 0.5)

