import sys

def min_grid_area(s):
    def calculate_area(commands):
        x, y = 0, 0
        min_x, max_x, min_y, max_y = 0, 0, 0, 0
        for command in commands:
            if command == 'W':
                y -= 1
            elif command == 'S':
                y += 1
            elif command == 'A':
                x -= 1
            elif command == 'D':
                x += 1
            min_x = min(min_x, x)
            max_x = max(max_x, x)
            min_y = min(min_y, y)
            max_y = max(max_y, y)
        return (max_x - min_x + 1) * (max_y - min_y + 1)

    best_area = calculate_area(s)
    for i in range(len(s) + 1):
        for command in 'WASD':
            new_s = s[:i] + command + s[i:]
            area = calculate_area(new_s)
            if area < best_area:
                best_area = area
    return best_area

def main():
    input = sys.stdin.read
    data = input().split()
    T = int(data[0])
    results = []
    for i in range(1, T + 1):
        s = data[i]
        results.append(min_grid_area(s))
    for result in results:
        print(result)

