def minDigit(n):
    return min(int(digit) for digit in str(n))

def maxDigit(n):
    return max(int(digit) for digit in str(n))

def solve(a1, K):
    a = a1
    for _ in range(K - 1):
        a += minDigit(a) * maxDigit(a)
    return a

