def can_form_abacaba(s):
    n = len(s)
    if n < 7:
        return False
    for i in range(n - 6):
        if s[i:i+7] == "abacaba":
            return True
    return False

def replace_question_marks(s):
    n = len(s)
    if n < 7:
        return "No"
    if can_form_abacaba(s):
        return "Yes\n" + s
    for i in range(n - 6):
        if s[i:i+7] == "abacaba":
            continue
        for j in range(26):
            new_s = s[:i] + chr(97 + j) + s[i+1:]
            if can_form_abacaba(new_s):
                return "Yes\n" + new_s
    return "No"

