from math import gcd

def find_chairs(n):
    chairs = []
    for i in range(1, 4*n + 1):
        if all(gcd(i, j) != 1 and i % j != 0 and j % i != 0 for j in chairs):
            chairs.append(i)
        if len(chairs) == n:
            break
    return chairs

