import sys
from collections import defaultdict

def is_valid_layout(s):
    graph = defaultdict(list)
    for i in range(len(s) - 1):
        graph[s[i]].append(s[i + 1])

    visited = set()
    stack = []

    def dfs(node):
        if node in visited:
            return False
        if node in stack:
            return True
        visited.add(node)
        stack.append(node)
        for neighbor in graph[node]:
            if not dfs(neighbor):
                return False
        stack.pop()
        return True

    for node in graph:
        if node not in visited:
            if not dfs(node):
                return False

    return True

def find_layout(s):
    graph = defaultdict(list)
    for i in range(len(s) - 1):
        graph[s[i]].append(s[i + 1])

    visited = set()
    stack = []
    order = []

    def dfs(node):
        if node in visited:
            return
        visited.add(node)
        for neighbor in graph[node]:
            dfs(neighbor)
        stack.append(node)

    for node in graph:
        if node not in visited:
            dfs(node)

    order = stack[::-1]

    if len(order) != 26:
        return None

    layout = [''] * 26
    for i, char in enumerate(order):
        layout[ord(char) - ord('a')] = chr(ord('a') + i)

    return ''.join(layout)

def main():
    input = sys.stdin.read
    data = input().split()

    T = int(data[0])
    results = []

    for i in range(1, T + 1):
        s = data[i]
        if is_valid_layout(s):
            layout = find_layout(s)
            results.append(f"YES\n{layout}")
        else:
            results.append("NO")

    for result in results:
        print(result)

if __name__ == "__main__":
    main()

