def find_divisors(n):
    divisors = set()
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            divisors.add(i)
            divisors.add(n // i)
    return sorted(divisors)

def min_moves(divisors):
    n = len(divisors)
    if n == 1:
        return 0, [divisors[0]]
    if n == 2:
        return 0, [divisors[0], divisors[1]]
    if n == 3:
        return 0, [divisors[0], divisors[1], divisors[2]]
    if n == 4:
        return 0, [divisors[0], divisors[1], divisors[2], divisors[3]]
    if n == 5:
        return 0, [divisors[0], divisors[1], divisors[2], divisors[3], divisors[4]]
    if n == 6:
        return 0, [divisors[0], divisors[1], divisors[2], divisors[3], divisors[4], divisors[5]]
    if n == 7:
        return 0, [divisors[0], divisors[1], divisors[2], divisors[3], divisors[4], divisors[5], divisors[6]]
    if n == 8:
        return 0, [divisors[0], divisors[1], divisors[2], divisors[3], divisors[4], divisors[5], divisors[6], divisors[7]]
    if n == 9:
