def min_toggles_to_compress(n, m, image):
    def is_compressible(k):
        padded_n = (n + k - 1) // k * k
        padded_m = (m + k - 1) // k * k
        padded_image = ['0' * padded_m] * (padded_n - n) + image + ['0' * m] * (padded_n - n - len(image))
        for i in range(0, padded_n, k):
            for j in range(0, padded_m, k):
                block = [padded_image[x][y] for x in range(i, i + k) for y in range(j, j + k)]
                if len(set(block)) > 1:
                    return False
        return True

    for k in range(2, min(n, m) + 1):
        if is_compressible(k):
            return (n * m - sum(row.count('1') for row in image))
    return n * m

