def find_vertices(N, grid):
    vertices = []
    for y in range(1, N - 1):
        for x in range(1, N - 1):
            if grid[y][x] > 0:
                if (x - 1, y) not in vertices and grid[y][x - 1] == 0:
                    vertices.append((x - 1, y))
                if (x + 1, y) not in vertices and grid[y][x + 1] == 0:
                    vertices.append((x + 1, y))
                if (x, y - 1) not in vertices and grid[y - 1][x] == 0:
                    vertices.append((x, y - 1))
                if (x, y + 1) not in vertices and grid[y + 1][x] == 0:
                    vertices.append((x, y + 1))
    return vertices

