def process_queries(N, S, queries):
    from collections import defaultdict
    from bisect import bisect_left, bisect_right

    def update(i, c):
        if S[i] != c:
            S[i] = c
            pos = bisect_left(pos_dict[S[i]], i)
            if pos > 0 and pos_dict[S[i]][pos - 1] == i - 1:
                pos_dict[S[i]].pop(pos - 1)
            if pos < len(pos_dict[S[i]]) and pos_dict[S[i]][pos] == i + 1:
                pos_dict[S[i]].pop(pos)
            if i not in pos_dict[S[i]]:
                pos_dict[S[i]].insert(bisect_left(pos_dict[S[i]], i), i)

    def query(l, r):
        unique_chars = set()
        for char in pos_dict:
            left = bisect_left(pos_dict[char], l)
            right = bisect_right(pos_dict[char], r)
            if left < right:
                unique_chars.add(char)
        return len(unique_chars)

    pos_dict = defaultdict(list)
    for i, char in enumerate(S):
        pos_dict[char].append(i)

    results = []
    for query_type, l, r in queries:
        if query_type == 1:
            update(l, r)
        elif query_type == 2:
            results.append(query(l, r))

    return results

