from collections import defaultdict, deque

def longest_increasing_subsequence(sequence):
    if not sequence:
        return 0
    dp = [1] * len(sequence)
    for i in range(1, len(sequence)):
        for j in range(i):
            if sequence[i] > sequence[j]:
                dp[i] = max(dp[i], dp[j] + 1)
    return max(dp)

def solve_tree(n, a, edges):
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    def dfs(node, parent):
        path = [a[node-1]]
        stack = [(node, parent)]
        while stack:
            current, parent = stack.pop()
            for neighbor in graph[current]:
                if neighbor != parent:
                    stack.append((neighbor, current))
                    path.append(a[neighbor-1])
        return path

    results = []
    for k in range(1, n+1):
        path = dfs(k, None)
        results.append(longest_increasing_subsequence(path))

    return results

