MOD = 10**9 + 7

def solve(n, m, labyrinth):
    directions = [(0, 1), (1, 0)]
    dp = [[[0, 0] for _ in range(m)] for _ in range(n)]
    dp[0][0][0] = 1

    for i in range(n):
        for j in range(m):
            if labyrinth[i][j] == 'R':
                continue
            for di, dj in directions:
                ni, nj = i + di, j + dj
                if 0 <= ni < n and 0 <= nj < m:
                    if labyrinth[ni][nj] == 'R':
                        ni, nj = ni + di, nj + dj
                        while 0 <= ni < n and 0 <= nj < m and labyrinth[ni][nj] == 'R':
                            ni, nj = ni + di, nj + dj
                    dp[ni][nj][1] = (dp[ni][nj][1] + dp[i][j][0]) % MOD
                    dp[ni][nj][0] = (dp[ni][nj][0] + dp[i][j][1]) % MOD
                else:
                    dp[i][j][1] = (dp[i][j][1] + dp[i][j][0]) % MOD

    return (dp[n-1][m-1][0] + dp[n-1][m-1][1]) % MOD

