from typing import List

def median_smoothing(sequence: List[int]) -> List[int]:
    n = len(sequence)
    result = [sequence[0]]
    for i in range(1, n - 1):
        result.append(sorted([sequence[i] - 1, sequence[i], sequence[i] + 1])[1])
    result.append(sequence[-1])
    return result

def is_stable(sequence: List[int]) -> bool:
    return sequence == median_smoothing(sequence)

def find_stable_sequence(sequence: List[int]) -> List[int]:
    steps = 0
    while not is_stable(sequence):
        sequence = median_smoothing(sequence)
        steps += 1
    return steps, sequence

