import sys
from itertools import combinations

def manhattan_distance(p1, p2):
    return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

def is_convex(polygon):
    n = len(polygon)
    for i in range(n):
        x1, y1 = polygon[i]
        x2, y2 = polygon[(i + 1) % n]
        x3, y3 = polygon[(i + 2) % n]
        cross_product = (x2 - x1) * (y3 - y1) - (y2 - y1) * (x3 - x1)
        if cross_product < 0:
            return False
    return True

def f(k, points):
    max_perimeter = 0
    for combo in combinations(points, k):
        if is_convex(combo):
            perimeter = sum(manhattan_distance(combo[i], combo[(i + 1) % k]) for i in range(k))
            max_perimeter = max(max_perimeter, perimeter)
    return max_perimeter

def main():
    input = sys.stdin.read
