from collections import deque

def count_segments(n, x, a):
    result = [0] * (n + 1)
    less_than_x = 0
    greater_than_x = 0
    queue = deque()

    for i in range(n):
        if a[i] < x:
            less_than_x += 1
        elif a[i] > x:
            greater_than_x += 1
            queue.append(i)

        while queue and a[queue[0]] < x:
            queue.popleft()

        if less_than_x == i - len(queue):
            result[less_than_x] += 1

    for i in range(n - 1, -1, -1):
        result[less_than_x] += 1
        if a[i] < x:
            less_than_x -= 1
        elif a[i] > x:
            greater_than_x -= 1
            queue.appendleft(i)

        while queue and a[queue[-1]] < x:
            queue.pop()

    return result

