def min_seconds_to_destroy(n, colors):
    dp = [0] * (n + 1)
    for length in range(1, n + 1):
        for start in range(n - length + 1):
            end = start + length - 1
            if length == 1:
                dp[end + 1] = dp[end]
            elif length == 2:
                dp[end + 1] = dp[end] + (colors[start] != colors[end])
            else:
                dp[end + 1] = dp[end] + 1
                for mid in range(start + 1, end):
                    if colors[start] == colors[end] and colors[start] == colors[mid]:
                        dp[end + 1] = min(dp[end + 1], dp[mid] + dp[end - mid - 1])
    return dp[n]

