MOD = 998244353

def factorial(n):
    if n == 0:
        return 1
    result = 1
    for i in range(2, n + 1):
        result = (result * i) % MOD
    return result

def inverse(n):
    return pow(n, MOD - 2, MOD)

def solve(n, edges):
    if n == 2:
        return 2
    degree = [0] * (n + 1)
    for u, v in edges:
        degree[u] += 1
        degree[v] += 1
    leaves = [i for i in range(1, n + 1) if degree[i] == 1]
    if len(leaves) != 2:
        return 0
    root = [i for i in range(1, n + 1) if degree[i] != 1][0]
    def dfs(node, parent):
        if degree[node] == 1:
            return 1
        count = 1
        for neighbor in range(1, n + 1):
            if neighbor != node and neighbor != parent:
                count *= dfs(neighbor, node)
                count %= MOD
        return count
    return (factorial(n - 2) * dfs(root, -1)) % MOD

