def restore_tree(n, edges):
    if n == 1:
        return [1]

    parent = [0] * (n + 1)
    children = defaultdict(list)
    for i, (p, c) in enumerate(edges, 1):
        parent[i] = p
        children[p].append(i)

    def dfs(node):
        if not children[node]:
            return [node]
        sub = []
        for child in children[node]:
            sub.extend(dfs(child))
        sub.sort()
        return [node] + sub

    order = dfs(1)
    values = [0] * (n + 1)
    for i, node in enumerate(order, 1):
        values[node] = i

    def check():
        for i, (_, c) in enumerate(edges, 1):
            if sum(1 for j in children[i] if values[j] < values[i]) != c:
                return False
        return True

    if check():
        return values[1:]
    else:
        return None

