def count_connected_components(n, m, elements):
    graph = defaultdict(list)
    for x in elements:
        for y in elements:
            if x & y == 0:
                graph[x].append(y)
                graph[y].append(x)

    visited = set()
    components = 0

    for x in elements:
        if x not in visited:
            components += 1
            queue = deque([x])
            while queue:
                node = queue.popleft()
                if node not in visited:
                    visited.add(node)
                    for neighbor in graph[node]:
                        queue.append(neighbor)

    return components

