def floyd_warshall(graph, n):
    dist = [[float('inf')] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            if graph[i][j] != 0:
                dist[i][j] = graph[i][j]
    for k in range(n):
        for i in range(n):
            for j in range(n):
                if dist[i][k] + dist[k][j] < dist[i][j]:
                    dist[i][j] = dist[i][k] + dist[k][j]
    return dist

def solve(n, graph, deletions):
    result = []
    dist = floyd_warshall(graph, n)
    total_sum = sum(dist[i][j] for i in range(n) for j in range(i+1, n))
    result.append(total_sum)
    for x in deletions:
        x -= 1
        for i in range(n):
            for j in range(n):
                if i != x and j != x:
                    dist[i][j] = min(dist[i][j], dist[i][x] + dist[x][j])
        total_sum = sum(dist[i][j] for i in range(n) for j in range(i+1, n))
        result.append(total_sum)
    return result

