def count_ways(n, actions):
    from collections import deque

    buy_stack = deque()
    sell_stack = deque()
    buy_count = 0
    sell_count = 0

    for action in actions:
        if action[0] == "ADD":
            price = action[1]
            if buy_stack and price <= buy_stack[-1]:
                buy_count += 1
            elif sell_stack and price >= sell_stack[-1]:
                sell_count += 1
            else:
                return 0
        elif action[0] == "ACCEPT":
            price = action[1]
            if buy_stack and buy_stack[-1] == price:
                buy_stack.pop()
                buy_count -= 1
            elif sell_stack and sell_stack[-1] == price:
                sell_stack.pop()
                sell_count -= 1
            else:
                return 0

    return (buy_count * sell_count) % MOD

