def min_additional_requests(n, a):
    if n == 1:
        return 0
    if n == 2:
        return max(0, 2 - a[0] - a[1])

    i = 1
    while i < n and a[i] > a[i - 1]:
        i += 1

    j = n - 2
    while j >= 0 and a[j] < a[j + 1]:
        j -= 1

    if i > j:
        return 0

    if i == 0:
        return max(0, 2 * a[0] - a[1] - a[2])

    if j == n - 1:
        return max(0, 2 * a[-1] - a[-2] - a[-3])

    return max(0, a[i - 1] - a[i] + a[j + 1] - a[j])

