def bfs_distance(n, edges, start):
    distance = [-1] * (n + 1)
    distance[start] = 0
    queue = deque([start])
    while queue:
        current = queue.popleft()
        for neighbor in edges[current]:
            if distance[neighbor] == -1:
                distance[neighbor] = distance[current] + 1
                queue.append(neighbor)
    return distance

