def min_time_to_reach_n(n, m, edges):
    graph = [[] for _ in range(n)]
    for u, v in edges:
        graph[u-1].append(v-1)

    def bfs(start):
        queue = deque([(start, 0)])
        visited = [False] * n
        visited[start] = True
        while queue:
            u, time = queue.popleft()
            if u == n-1:
                return time
            for v in graph[u]:
                if not visited[v]:
                    visited[v] = True
                    queue.append((v, time + 1))
        return float('inf')

    return bfs(0)

