def count_palindrome_pairs(words):
    word_set = set(words)
    count = 0

    for word in words:
        n = len(word)
        for i in range(n + 1):
            prefix = word[:i]
            suffix = word[i:]
            if is_palindrome(prefix):
                reversed_suffix = suffix[::-1]
                if reversed_suffix in word_set and reversed_suffix != word:
                    count += 1
            if is_palindrome(suffix):
                reversed_prefix = prefix[::-1]
                if reversed_prefix in word_set and reversed_prefix != word:
                    count += 1

    return count

