def find_lexicographically_smallest_permutation(n, edges):
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    def dfs(node, parent):
        if node == 1:
            return [1]
        for neighbor in graph[node]:
            if neighbor != parent:
                path = dfs(neighbor, node)
                if path:
                    path.append(node)
                    return path
        return []

    path = dfs(1, -1)
    if len(path) != n:
        return -1

    def find_permutation(path):
        if len(path) == 1:
            return [1]
        for i in range(1, len(path)):
            if path[i] < path[i - 1]:
                return find_permutation(path[:i]) + find_permutation(path[i:])
        return path

    permutation = find_permutation(path)
    return permutation

