MOD = 10**9 + 7

def count_regular_sequences(n, s):
    m = len(s)
    if m > 2 * n:
        return 0

    dp = [[0] * (2 * n + 1) for _ in range(m + 1)]
    dp[0][0] = 1

    for i in range(m):
        for j in range(2 * n + 1):
            if dp[i][j] == 0:
                continue
            if j > 0:
                dp[i + 1][j - 1] = (dp[i + 1][j - 1] + dp[i][j]) % MOD
            if j < 2 * n:
                dp[i + 1][j + 1] = (dp[i + 1][j + 1] + dp[i][j]) % MOD

    result = 0
    for j in range(n, 2 * n + 1):
        if s == s[:j - n]:
            result = (result + dp[m][j]) % MOD

    return result

