    return True

def find_order(strings):
    n = len(strings)
    for i in range(n):
        for j in range(n):
            if i != j and strings[i] not in strings[j]:
                strings[i], strings[j] = strings[j], strings[i]
                if can_form_substrings(strings):
                    return strings
                strings[i], strings[j] = strings[j], strings[i]
    return None

