def min_perimeter(a, b):
    min_per = float('inf')
    for i in range(1, a + 1):
        if a % i == 0:
            j = a // i
            if i * j == a and (j >= b or i >= b):
                per = 2 * (i + j)
                if per < min_per:
                    min_per = per
    for i in range(1, b + 1):
        if b % i == 0:
            j = b // i
            if i * j == b and (j >= a or i >= a):
                per = 2 * (i + j)
                if per < min_per:
                    min_per = per
    return min_per

