def cat_furrier_transform(x):
    operations = []
    while x != (1 << (x.bit_length())) - 1:
        if x % 2 == 0:
            n = 0
            while (1 << n) - 1 < x:
                n += 1
            operations.append(n - 1)
            x ^= (1 << (n - 1)) - 1
        else:
            x += 1
    return len(operations), operations

