def min_p_binary_sum(n, p):
    if n == 0:
        return 0
    if p == 0:
        return n.bit_length()
    if p > 0:
        return min_p_binary_sum(n, p - 1) + 1 if n % 2 == 1 else min_p_binary_sum(n // 2, p)
    else:
        if n < -p:
            return -1
        return min_p_binary_sum(n + p, p + 1) + 1 if n % 2 == 1 else min_p_binary_sum(n // 2, p)

