def count_camels(n, t):
    if t == 1:
        return 6 * (n - 2)
    if t >= n - 1:
        return 0
    count = 0
    for humps in combinations(range(2, n-1), t-1):
        for i in range(1, n-1):
            if i in humps:
                if i == 1:
                    if humps[0] > 2:
                        count += 1
                elif i == n-2:
                    if humps[-1] < n-3:
                        count += 1
                else:
                    if humps[humps.index(i)-1] < i < humps[humps.index(i)+1]:
                        count += 1
    return count

