def process_queries(n, m, friendships, queries):
    graph = defaultdict(set)
    power = list(range(1, n + 1))
    vulnerable = set(range(1, n + 1))

    for u, v in friendships:
        graph[u].add(v)
        graph[v].add(u)

    def is_vulnerable(noble):
        if not graph[noble]:
            return False
        for friend in graph[noble]:
            if power[friend - 1] <= power[noble - 1]:
                return False
        return True

    def update_vulnerability():
        nonlocal vulnerable
        vulnerable = {noble for noble in range(1, n + 1) if is_vulnerable(noble)}

    def process():
        while vulnerable:
            new_vulnerable = set()
            for noble in vulnerable:
                for friend in graph[noble]:
                    graph[friend].discard(noble)
                    if is_vulnerable(friend):
                        new_vulnerable.add(friend)
            vulnerable = new_vulnerable

    results = []
    for query in queries:
        if query[0] == 1:
            u, v = query[1], query[2]
            graph[u].add(v)
            graph[v].add(u)
            if u in vulnerable:
                vulnerable.remove(u)
            if v in vulnerable:
                vulnerable.remove(v)
            update_vulnerability()
        elif query[0] == 2:
            u, v = query[1], query[2]
            graph[u].discard(v)
            graph[v].discard(u)
            if u in vulnerable:
                vulnerable.remove(u)
            if v in vulnerable:
                vulnerable.remove(v)
            update_vulnerability()
        elif query[0] == 3:
            process()
            results.append(n - len(vulnerable))

    return results

