def min_kicks(s):
    first_team = 0
    second_team = 0
    first_team_max = 0
    second_team_max = 0
    first_team_min = 0
    second_team_min = 0
    n = len(s)

    for i in range(n):
        if s[i] == '1':
            if i % 2 == 0:
                first_team += 1
                first_team_max += 1
                second_team_max += 1
            else:
                second_team += 1
                second_team_max += 1
                first_team_max += 1
        elif s[i] == '0':
            if i % 2 == 0:
                second_team_max += 1
            else:
                first_team_max += 1
        else:
            if i % 2 == 0:
                first_team_max += 1
                second_team_min += 1
            else:
                second_team_max += 1
                first_team_min += 1

    if first_team > second_team_max:
        return n
    if second_team > first_team_max:
        return n

    for i in range(n):
        if s[i] == '1':
            if i % 2 == 0:
                first_team += 1
            else:
                second_team += 1
        if first_team > second_team_max:
            return i + 1
        if second_team > first_team_max:
            return i + 1

    return n

