def get_prime_factors(x):
    factors = defaultdict(int)
    for i in range(2, int(x**0.5) + 1):
        while x % i == 0:
            factors[i] += 1
            x //= i
    if x > 1:
        factors[x] += 1
    return factors

def get_gcds(a):
    gcds = defaultdict(set)
    for i in range(n):
        for j in range(i+1, n):
            g = gcd(a[i], a[j])
            gcds[g].add(i)
            gcds[g].add(j)
    return gcds

def get_min_new_nodes(a, queries):
    gcds = get_gcds(a)
    prime_factors = [get_prime_factors(x) for x in a]
    graph = defaultdict(set)
    for i in range(n):
        for j in range(i+1, n):
            if gcd(a[i], a[j]) > 1:
                graph[i].add(j)
                graph[j].add(i)

    def bfs(start, end):
        queue = deque([start])
        visited = set([start])
        while queue:
            node = queue.popleft()
            if node == end:
                return 0
            for neighbor in graph[node]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    queue.append(neighbor)
            for i in range(n):
                if i not in visited and any(prime_factors[i][p] % prime_factors[node][p] == 0 for p in prime_factors[node]):
                    visited.add(i)
                    queue.append(i)
        return -1

    return [bfs(s, t) for s, t in queries]

