def min_baking_time(n):
    small = 6
    medium = 8
    large = 10
    small_time = 15
    medium_time = 20
    large_time = 25

    min_time = float('inf')

    for i in range(n // small + 1):
        for j in range(n // medium + 1):
            for k in range(n // large + 1):
                if i * small + j * medium + k * large >= n:
                    time = i * small_time + j * medium_time + k * large_time
                    if time < min_time:
                        min_time = time

    return min_time

