def count_regular_subsequences(n, c):
    total = 0
    stack = []
    for i in range(n):
        if i % 2 == 0:
            stack.append(c[i])
        else:
            while stack and stack[-1] < c[i]:
                stack.pop()
            if stack and stack[-1] == c[i]:
                stack.pop()
            else:
                stack.append(c[i])
            total += len(stack)
    return total

