    iterations = 0
    while True:
        if all(a[i] <= a[i + 1] for i in range(n - 1)):
            return iterations
        if iterations % 2 == 0:
            for i in range(0, n - 2, 2):
                if a[i] > a[i + 1]:
                    a[i], a[i + 1] = a[i + 1], a[i]
        else:
            for i in range(1, n - 1, 2):
                if a[i] > a[i + 1]:
                    a[i], a[i + 1] = a[i + 1], a[i]
        iterations += 1

