from collections import defaultdict, deque

def min_leaves(n, edges):
    tree = defaultdict(list)
    for u, v in edges:
        tree[u].append(v)
        tree[v].append(u)

    def is_bud(v, parent):
        if v == 1:
            return False
        if len(tree[v]) == 1:
            return False
        for child in tree[v]:
            if child != parent and len(tree[child]) != 1:
                return False
        return True

    def count_leaves(v, parent):
        if v not in tree:
            return 1
        return sum(count_leaves(child, v) for child in tree[v] if child != parent)

    buds = [v for v in range(2, n + 1) if is_bud(v, 1)]
    leaves = count_leaves(1, -1)

    for bud in buds:
        for child in tree[bud]:
            if child != 1:
                new_leaves = leaves - count_leaves(bud, -1) + count_leaves(child, -1)
                leaves = min(leaves, new_leaves)

    return leaves

