MOD = 998244353

def count_nice_permutations(n, a):
    from collections import deque
    from math import factorial

    def mod_inv(x):
        return pow(x, MOD - 2, MOD)

    def comb(n, k):
        if k > n:
            return 0
        return factorial(n) * mod_inv(factorial(k)) % MOD * mod_inv(factorial(n - k)) % MOD

    tasks = sum(a)
    nice_permutations = 0

    for i in range(1, n + 1):
        if tasks % i == 0:
            nice_permutations += comb(n, i) * pow(i, n - i, MOD)
            nice_permutations %= MOD

    return nice_permutations

