from collections import defaultdict, deque

def read_input():
    input = sys.stdin.read
    data = input().split()
    index = 0
    def next_int():
        nonlocal index
        result = int(data[index])
        index += 1
        return result
    return next_int, data[index:]

def solve():
    next_int, data = read_input()
    t = next_int()
    results = []
    for _ in range(t):
        n = next_int()
        graph = defaultdict(list)
        in_degree = [0] * (n + 1)
        for i in range(1, n + 1):
            k = next_int()
            for _ in range(k):
                j = next_int()
                graph[j].append(i)
                in_degree[i] += 1
        queue = deque([i for i in range(1, n + 1) if in_degree[i] == 0])
        read_count = 0
        while queue:
            if not queue:
                read_count += 1
                queue = deque([i for i in range(1, n + 1) if in_degree[i] == 0])
            current = queue.popleft()
            for neighbor in graph[current]:
                in_degree[neighbor] -= 1
                if in_degree[neighbor] == 0:
                    queue.append(neighbor)
        if sum(in_degree) == 0:
            results.append(read_count)
        else:
            results.append(-1)
    for result in results:
