def min_operations_to_portal(n, m, grid):
    def is_portal(x1, y1, x2, y2):
        if x2 - x1 < 4 or y2 - y1 < 3:
            return False
        for x in range(x1 + 1, x2):
            if grid[x][y1] != '1' or grid[x][y2] != '1':
                return False
        for y in range(y1 + 1, y2):
            if grid[x1][y] != '1' or grid[x2][y] != '1':
                return False
        for x in range(x1 + 1, x2):
            for y in range(y1 + 1, y2):
                if grid[x][y] != '0':
                    return False
        return True

    def count_operations(x1, y1, x2, y2):
        obsidian_count = 0
        for x in range(x1, x2 + 1):
            for y in range(y1, y2 + 1):
                if grid[x][y] == '1':
                    obsidian_count += 1
        return obsidian_count

    min_ops = float('inf')
    for x1 in range(n - 4):
        for y1 in range(m - 3):
            if is_portal(x1, y1, x1 + 4, y1 + 3):
                min_ops = min(min_ops, count_operations(x1, y1, x1 + 4, y1 + 3))
    return min_ops if min_ops != float('inf') else 0

