def is_composite(num):
    if num < 4:
        return False
    for i in range(2, int(num**0.5) + 1):
        if num % i == 0:
            return True
    return False

def largest_composite_subset(arr):
    n = len(arr)
    max_size = 0
    best_subset = []
    for size in range(n, 0, -1):
        for subset in combinations(arr, size):
            if is_composite(sum(subset)):
                max_size = size
                best_subset = subset
                break
        if best_subset:
            break
    return max_size, [arr.index(x) + 1 for x in best_subset]

