def find_tree(n, m, restrictions):
    graph = defaultdict(list)
    for a, b, c in restrictions:
        graph[a].append((b, c))
        graph[b].append((a, c))
        graph[c].append((a, b))

    def dfs(node, parent, path):
        if node == parent:
            return path
        for neighbor, _ in graph[node]:
            if neighbor != parent:
                result = dfs(neighbor, node, path + [neighbor])
                if result:
                    return result
        return None

    def find_path(a, b, c):
        path_a = dfs(a, -1, [a])
        path_b = dfs(b, -1, [b])
        path_c = dfs(c, -1, [c])
        if path_a and path_b and path_c:
            return path_a, path_b, path_c
        return None

    def find_edges(n, m, restrictions):
        edges = []
        for a, b, c in restrictions:
            path_a, path_b, path_c = find_path(a, b, c)
            if path_a and path_b and path_c:
                for i in range(len(path_a) - 1):
                    edges.append((path_a[i], path_a[i + 1]))
                for i in range(len(path_b) - 1):
                    edges.append((path_b[i], path_b[i + 1]))
                for i in range(len(path_c) - 1):
                    edges.append((path_c[i], path_c[i + 1]))
        return edges

    edges = find_edges(n, m, restrictions)
    return edges

