            tree[i].append(i * 2 + 1)

    def dfs(node, parent_color):
        if node not in chosen:
            count = 0
            for color in 'white yellow green blue red orange':
                if color != parent_color:
                    count = (count + dfs(tree[node][0], color) * dfs(tree[node][1], color)) % MOD
            return count
        else:
            color = chosen[node]
            count = 1
            for child in tree[node]:
                if child not in chosen:
                    count = (count * dfs(child, color)) % MOD
            return count

    return dfs(1, None)

