def min_unrepresentable(s, k, denominations):
    dp = [float('inf')] * (s + 1)
    dp[0] = 0
    for i in range(1, s + 1):
        for denom in denominations:
            if i >= denom:
                dp[i] = min(dp[i], dp[i - denom] + 1)
    return dp[s] > k

