def count_valid_colorings(n, dominoes):
    def count_ways(left, right):
        if left == 'B':
            return 1 if right == 'W' else 0
        elif left == 'W':
            return 1 if right == 'B' else 0
        else:
            return 2 if right == '?' else 0

    def dp(i, left, right):
        if i == n:
            return 1 if left != right else 0
        if (i, left, right) in memo:
            return memo[(i, left, right)]
        ways = 0
        if dominoes[i][0] == '?':
            ways = (ways + dp(i + 1, 'B', right)) % MOD
            ways = (ways + dp(i + 1, 'W', right)) % MOD
        if dominoes[i][1] == '?':
            ways = (ways + dp(i + 1, left, 'B')) % MOD
            ways = (ways + dp(i + 1, left, 'W')) % MOD
        memo[(i, left, right)] = ways
        return ways

    memo = {}
    total_ways = 0
    for i in range(n):
        total_ways = (total_ways + dp(i, dominoes[i][0], dominoes[i][1])) % MOD
    return total_ways

