import sys
from collections import defaultdict, deque

def read_input():
    input = sys.stdin.read
    data = input().split()
    index = 0
    def next_int():
        nonlocal index
        result = int(data[index])
        index += 1
        return result
    def next_str():
        nonlocal index
        result = data[index]
        index += 1
        return result
    return next_int, next_str

def solve():
    next_int, next_str = read_input()
    t = next_int()
    results = []
    for _ in range(t):
        n = next_int()
        m = next_int()
        edges = defaultdict(int)
        for _ in range(n - 1):
            x = next_int()
            y = next_int()
            v = next_int()
            edges[(x, y)] = v
            edges[(y, x)] = v
        elves = []
        for _ in range(m):
            a = next_int()
            b = next_int()
            p = next_int()
            elves.append((a, b, p))
        result = []
        if check_consistency(edges, elves):
            result = get_tree(edges)
        results.append(result)
    for result in results:
        if result == "NO":
            print("NO")
        else:
            print("YES")
            for edge in result:
                print(edge[0], edge[1], edge[2])

def check_consistency(edges, elves):
    n = len(edges) + 1
    graph = defaultdict(list)
    for (x, y), v in edges.items():
        graph[x].append((y, v))
        graph[y].append((x, v))
    for a, b, p in elves:
        path = find_path(graph, a, b)
        xor_value = 0
        for x, y, v in path:
            xor_value ^= v
        if (xor_value.bit_count() % 2) != p:
            return False
    return True

def find_path(graph, start, end):
    queue = deque([(start, [])])
    visited = set()
    while queue:
        node, path = queue.popleft()
        if node == end:
            return path + [(node, node, 0)]
        visited.add(node)
        for neighbor, v in graph[node]:
            if neighbor not in visited:
                queue.append((neighbor, path + [(node, neighbor, v)]))
    return []

def get_tree(edges):
    n = len(edges) + 1
    result = []
    for (x, y), v in edges.items():
        result.append((x, y, v))
    return result

