def smallest_permutation(S, T):
    count = Counter(S)
    T = list(T)
    result = []
    for char in S:
        if char not in T:
            result.append(char)
            count[char] -= 1
            if count[char] == 0:
                T.remove(char)
    for char in T:
        result.append(char)
    return ''.join(result)

