def reconstruct_word(bigrams):
    word = [bigrams[0][0]]
    for bigram in bigrams:
        word.append(bigram[1])
    return ''.join(word)

def find_missing_bigram(word, bigrams):
    for i in range(len(bigrams)):
        test_word = word[:i*2] + word[i*2+2:]
        test_bigrams = [test_word[j:j+2] for j in range(len(test_word)-1)]
        if test_bigrams == bigrams:
            return word[i*2:i*2+2]
    return None

