import sys
from collections import defaultdict, deque

def min_time_to_detonate_mines(t):
    for _ in range(t):
        n, k = map(int, input().split())
        mines = []
        for _ in range(n):
            x, y, timer = map(int, input().split())
            mines.append((x, y, timer))

        graph = defaultdict(list)
        for i in range(n):
            for j in range(n):
                if i != j:
                    dx, dy = abs(mines[i][0] - mines[j][0]), abs(mines[i][1] - mines[j][1])
                    if dx <= k and dy <= k:
                        graph[i].append(j)

        visited = [False] * n
        times = [float('inf')] * n

        for i in range(n):
            if not visited[i]:
                queue = deque([(i, 0)])
                while queue:
                    current, time = queue.popleft()
                    if time >= times[current]:
                        continue
                    times[current] = time
                    visited[current] = True
                    for neighbor in graph[current]:
                        queue.append((neighbor, time + 1))

        print(max(times))

