from math import comb

def solve(n, k, x, s):
    result = []
    i = 0
    while i < n:
        if s[i] == '*':
            count = 0
            while i < n and s[i] == '*':
                i += 1
                count += 1
            if count == 1:
                result.append('a')
            else:
                if x <= comb(count + 1, 2):
                    result.append('b' * (count - 1) + 'a')
                    x -= comb(count, 2)
                else:
                    result.append('b' * count)
        else:
            result.append(s[i])
            i += 1
    return ''.join(result)

