from collections import Counter

MOD = 998244353

def count_distinct_strings(n, k, s):
    if k == 0:
        return 1

    count = Counter(s)
    if count['1'] < k:
        return 1

    distinct_strings = set()

    for i in range(n):
        for j in range(i, n):
            if s[i:j].count('1') == k:
                distinct_strings.add(''.join(sorted(s[i:j])))

    return len(distinct_strings) % MOD

