def is_quadratic(subset):
    product = 1
    for num in subset:
        product *= math.factorial(num)
    return math.isqrt(product) ** 2 == product

def find_max_quadratic_subset(n):
    max_size = 0
    max_subset = []
    for i in range(1, n + 1):
        subset = list(range(1, i + 1))
        if is_quadratic(subset):
            if len(subset) > max_size:
                max_size = len(subset)
                max_subset = subset
    return max_size, max_subset

