def smallest_string_representation(n, k, c, children):
    def dfs(u, parent_duplicated):
        if u == 0:
            return ""
        left = dfs(children[u][0], parent_duplicated)
        right = dfs(children[u][1], parent_duplicated)
        if parent_duplicated or k > 0:
            return left + c[u-1] * 2 + right
        else:
            return left + c[u-1] + right

    return dfs(1, False)

