def find_max_square_brackets(sequence):
    stack = []
    max_count = 0
    current_count = 0
    result = ""

    for char in sequence:
        if char == '[':
            stack.append(char)
            current_count += 1
        elif char == ']':
            if stack and stack[-1] == '[':
                stack.pop()
                current_count += 1
                if current_count > max_count:
                    max_count = current_count
                    result = '[' * max_count
            else:
                current_count = 0
        elif char == '(' or char == ')':
            current_count = 0

    return max_count, result

