def find_stair_sequence(cards):
    n = len(cards)
    if n == 1:
        return [cards[0]], 1
    left = []
    right = []
    for i in range(n):
        if not left or cards[i] > left[-1]:
            left.append(cards[i])
        else:
            break
    for i in range(n-1, -1, -1):
        if not right or cards[i] > right[-1]:
            right.append(cards[i])
        else:
            break
    if len(left) + len(right) - 1 > n:
        left = left[:-1]
    return left + right[::-1], len(left) + len(right) - 1

