import sys

def feed_golorp(golorp_name):
    stack = []
    for char in golorp_name:
        if char.isdigit():
            stack.append(char)
        elif char == '_':
            if not stack:
                return "false"
            stack.pop()
        elif char == '-':
            if len(stack) < 2:
                return "false"
            b = stack.pop()
            a = stack.pop()
            stack.append(str(int(a) - int(b)))
        elif char == '+':
            if len(stack) < 2:
                return "false"
            b = stack.pop()
            a = stack.pop()
            stack.append(str(int(a) + int(b)))
        elif char == '*':
            if len(stack) < 2:
                return "false"
            b = stack.pop()
            a = stack.pop()
            stack.append(str(int(a) * int(b)))
        elif char == '/':
            if len(stack) < 2:
                return "false"
            b = stack.pop()
            a = stack.pop()
            if b == '0':
                return "false"
            stack.append(str(int(a) // int(b)))
        elif char == '<':
            if not stack:
                return "false"
            stack.pop()
        elif char == '>':
            if not stack:
                return "false"
            stack.pop()
    if len(stack) != 1:
        return "false"
    return stack[0]

