def find_max_beautiful_cuts(n, beads):
    total_beads = sum(beads)
    if total_beads <= 2:
        return total_beads - 1, ''.join(chr(ord('a') + i) * beads[i] for i in range(n))

    max_cuts = 0
    for i in range(n):
        for j in range(i + 1, n):
            if beads[i] == beads[j]:
                max_cuts = max(max_cuts, beads[i] + beads[j])

    necklace = ''.join(chr(ord('a') + i) * beads[i] for i in range(n))
    return max_cuts, necklace

