def min_compressed_length(s):
    n = len(s)
    dp = [float('inf')] * (n + 1)
    dp[0] = 0
    for i in range(1, n + 1):
        for j in range(1, i + 1):
            count = defaultdict(int)
            for k in range(j, i + 1):
                count[s[k - 1]] += 1
            for char, freq in count.items():
                if freq == 1:
                    dp[i] = min(dp[i], dp[j - 1] + len(char))
                else:
                    dp[i] = min(dp[i], dp[j - 1] + len(str(freq)) + len(char))
    return dp[n]

