def posterization_filter(n, k, pixels):
    groups = []
    current_group = [pixels[0]]
    for i in range(1, n):
        if pixels[i] - current_group[-1] <= k:
            current_group.append(pixels[i])
        else:
            groups.append((min(current_group), max(current_group)))
            current_group = [pixels[i]]
    groups.append((min(current_group), max(current_group)))

    group_keys = {group: (group[0] + group[1]) // 2 for group in groups}

    result = []
    for pixel in pixels:
        for group, key in group_keys.items():
            if group[0] <= pixel <= group[1]:
                result.append(key)
                break

    return result

