from collections import deque

def count_segments(n, x, arr):
    result = [0] * (n + 1)
    less_than_x = deque()
    greater_than_x = deque()

    for i in range(n):
        while less_than_x and arr[i] < arr[less_than_x[-1]]:
            less_than_x.pop()
        less_than_x.append(i)

        while greater_than_x and arr[i] > arr[greater_than_x[-1]]:
            greater_than_x.pop()
        greater_than_x.append(i)

        while less_than_x and arr[less_than_x[0]] < x:
            less_than_x.popleft()
        while greater_than_x and arr[greater_than_x[0]] >= x:
            greater_than_x.popleft()

        if less_than_x and greater_than_x:
            result[len(greater_than_x) - len(less_than_x)] += 1

    return result

