def decode_caesar_cipher(text, shift):
    decoded = []
    for char in text:
        if char.isalpha():
            shift_base = ord('a') if char.islower() else ord('A')
            decoded_char = chr((ord(char) - shift_base - shift) % 26 + shift_base)
            decoded.append(decoded_char)
        else:
            decoded.append(char)
    return ''.join(decoded)

