def min_jumps(n, a, b):
    def bfs(start, walls):
        queue = deque([(start, 0)])
        visited = [False] * n
        visited[start] = True
        while queue:
            floor, jumps = queue.popleft()
            if floor == n - 1:
                return jumps
            for next_floor in range(max(0, floor - 2), min(n, floor + 3)):
                if not visited[next_floor] and walls[next_floor] != 1:
                    visited[next_floor] = True
                    queue.append((next_floor, jumps + 1))
        return float('inf')

    jumps1 = bfs(0, a)
    jumps2 = bfs(0, b)
    if jumps1 == float('inf') and jumps2 == float('inf'):
        return "NA"
    return min(jumps1, jumps2)

