from typing import List

def max_profit(C: int, D: int, W: int, X: int, E: List[List[int]], F: List[List[int]]) -> int:
    dp = [[[-1] * (W + 1) for _ in range(X + 1)] for _ in range(D + 1)]

    def dfs(day: int, burden: int, repeat: int) -> int:
        if day == D:
            return 0
        if dp[day][burden][repeat] != -1:
            return dp[day][burden][repeat]

        max_profit = 0
        for region in range(1, C + 1):
            if E[region - 1][day] == 0:
                continue
            new_burden = burden + F[region - 1][day]
            if new_burden <= W:
                new_repeat = repeat + 1 if region == 1 or region == C else repeat
                if new_repeat <= X:
                    max_profit = max(max_profit, E[region - 1][day] + dfs(day + 1, new_burden, new_repeat))

        dp[day][burden][repeat] = max_profit
        return max_profit

    return dfs(0, 0, 0)

