def get_neighbors(board, x, y):
    N = len(board)
    neighbors = []
    if x > 0:
        neighbors.append((x-1, y))
    if x < N-1:
        neighbors.append((x+1, y))
    if y > 0:
        neighbors.append((x, y-1))
    if y < x:
        neighbors.append((x, y+1))
    return neighbors

def get_group(board, x, y, visited):
    N = len(board)
    group = []
    stack = [(x, y)]
    while stack:
        cx, cy = stack.pop()
        if (cx, cy) in visited:
            continue
        visited.add((cx, cy))
        group.append((cx, cy))
        for nx, ny in get_neighbors(board, cx, cy):
            if 0 <= nx < N and 0 <= ny < nx+1 and board[nx][ny] == board[x][y]:
                stack.append((nx, ny))
    return group

def get_points(board, C):
    N = len(board)
    visited = set()
    points = 0
    for x in range(N):
        for y in range(x+1):
            if board[x][y] != 0 and (x, y) not in visited:
                group = get_group(board, x, y, visited)
                if any(board[nx][ny] == C for nx, ny in group):
                    points += sum(1 for nx, ny in group if board[nx][ny] != C)
                else:
                    points -= sum(1 for nx, ny in group if board[nx][ny] == C)
    return points

