    data = input().split()
    n = int(data[0])
    nodes = {}
    index = 1
    for i in range(n):
        id = int(data[index])
        k = int(data[index + 1])
        children = list(map(int, data[index + 2:index + 2 + k]))
        nodes[id] = {'parent': None, 'depth': None, 'type': None, 'children': children}
        index += 2 + k
    return nodes

def find_root(nodes):
    for node in nodes:
        if nodes[node]['parent'] is None:
            return node
    return None

def assign_depth_and_parent(node, parent, depth, nodes):
    nodes[node]['parent'] = parent
    nodes[node]['depth'] = depth
    if parent is not None:
        nodes[parent]['children'].append(node)
    for child in nodes[node]['children']:
        assign_depth_and_parent(child, node, depth + 1, nodes)

def determine_node_type(node, nodes):
    if node in nodes[node]['children']:
        nodes[node]['type'] = 'root'
    elif nodes[node]['children']:
        nodes[node]['type'] = 'internal node'
    else:
        nodes[node]['type'] = 'leaf'

