            right = (0 if col == n-1 else table[row][col+1])
            right_up = (0 if (row == 0 or col == n-1) else table[row-1][col+1])
            right_down = (0 if (row == m-1 or col == n-1) else table[row+1][col+1])
            table[row][col] = gold[row][col] + max(right, right_up, right_down)
    res = table[0][0]
