def max_sum_of_three_consecutive(arr, n):
    if n == 0:
        return 0
    if n == 1:
        return arr[0]
    if n == 2:
        return max(arr[0], arr[1])

    # Initialize the lookup table
    lookup = [0] * n
    lookup[0] = arr[0]
    lookup[1] = max(arr[0], arr[1])
    lookup[2] = max(max(arr[0], arr[1]), arr[0] + arr[2])

    # Fill the lookup table
    for i in range(3, n):
        lookup[i] = max(max(lookup[i-1], lookup[i-2] + arr[i]), arr[i] + arr[i-1] + lookup[i-3])

    return lookup[n-1]

