def min_Swaps(str1, str2):
    # Check if lengths are different
    if len(str1) != len(str2):
        return "Not Possible"

    # Initialize counts of 0s and 1s in str1 and str2
    count1 = count0 = 0
    for i in range(len(str1)):
        if str1[i] == '0':
            count0 += 1
        else:
            count1 += 1
        if str2[i] == '0':
            count0 -= 1
        else:
            count1 -= 1

    # If counts are not balanced, it's not possible to convert
    if count0 != 0 or count1 != 0:
        return "Not Possible"

    # Count mismatches
    mis1 = mis0 = 0
    for i in range(len(str1)):
        if str1[i] != str2[i]:
            if str1[i] == '0':
                mis0 += 1
            else:
                mis1 += 1

    # Minimum swaps required is half the number of mismatches
    return mis0 // 2 + mis1 // 2

