def dealnnoy_num(m, n):
    # Initialize a 2D list with zeros
    dp = [[0 for _ in range(n + 1)] for _ in range(m + 1)]

    # Base case: D(0, 0) = 1
    dp[0][0] = 1

    # Fill the dp table
    for i in range(m + 1):
        for j in range(n + 1):
            if i > 0:
                dp[i][j] += dp[i - 1][j]
            if j > 0:
                dp[i][j] += dp[i][j - 1]
            if i > 0 and j > 0:
                dp[i][j] += dp[i - 1][j - 1]

    # Return the nth Delannoy number
    return dp[m][n]

