    if n < 0:
        return -float('inf')
    # Base case: if n is 0, no more segments are needed
    if n == 0:
        return 0
    # Recursively find the maximum number of segments by including one of each type
    return 1 + max(maximum_segments(n - a, a, b, c), maximum_segments(n - b, a, b, c), maximum_segments(n - c, a, b, c))

