            i += 6
        return True

    largest_factor = None
    factor = 2
    while n % factor == 0:
        largest_factor = factor
        n //= factor

    factor = 3
    while factor * factor <= n:
        while n % factor == 0:
            largest_factor = factor
            n //= factor
        factor += 2

    if n > 2:
        largest_factor = n

    return largest_factor

