def calculate_alice_score(s):
    n = len(s)
    dp = [[0] * (n + 1) for _ in range(2)]
    count_ones = [0] * (n + 1)

    for i in range(1, n + 1):
        count_ones[i] = count_ones[i - 1] + (s[i - 1] == '1')

    for i in range(1, n + 1):
        for j in range(1, i + 1):
            if s[j - 1] == s[i - 1]:
                dp[i % 2][j] = max(dp[i % 2][j], dp[(i - 1) % 2][j - 1] + count_ones[i] - count_ones[j - 1])
            else:
                dp[i % 2][j] = max(dp[i % 2][j], dp[(i - 1) % 2][j])

    return dp[n % 2][n]

