def solve(d):
    if d == 0:
        return "Y", 0.0, 0.0
    discriminant = d**2 - 4*d
    if discriminant < 0:
        return "N", None, None
    sqrt_discriminant = math.sqrt(discriminant)
    a1 = (d + sqrt_discriminant) / 2
    a2 = (d - sqrt_discriminant) / 2
    if a1 * a2 == d:
        return "Y", a1, a2
    else:
        return "N", None, None

