    n = len(s)
    target = "abacaba"
    target_len = len(target)

    # Check all possible starting positions for "abacaba"
    for start in range(n - target_len + 1):
        can_place = True
        for i in range(target_len):
            if s[start + i] != '?' and s[start + i] != target[i]:
                can_place = False
                break
        if can_place:
            # Replace '?' with 'a' to form "abacaba"
            result = list(s)
            for i in range(target_len):
                if result[start + i] == '?':
                    result[start + i] = target[i]
            return "Yes", "".join(result)

    return "No", ""

