def find_kth_good_permutation(n, k):
    def generate_permutation(perm, used, k, fact):
        if len(perm) == n:
            return perm
        for i in range(1, n + 1):
            if not used[i]:
                block_size = 1
                j = i
                while not used[p[j]]:
                    used[p[j]] = True
                    j = p[j]
                    block_size += 1
                used[i] = True
                if block_size == 1:
                    if k == 1:
                        return generate_permutation(perm + [i], used, k, fact)
                    k -= 1
                else:
                    block = []
                    j = i
                    while not used[p[j]]:
                        block.append(p[j])
                        j = p[j]
                    block.append(i)
                    for _ in range(block_size - 1):
                        block = block[1:] + block[:1]
                    if k <= fact[block_size - 1]:
                        return generate_permutation(perm + block, used, k, fact)
                    k -= fact[block_size - 1]
        return []

    if n == 1:
        return [1]

    p = list(range(1, n + 1))
    fact = [1] * (n + 1)
    for i in range(2, n + 1):
        fact[i] = fact[i - 1] * i

    used = [False] * (n + 1)
    good_perm = generate_permutation([], used, k, fact)

    if len(good_perm) < n:
        return [-1]
    return good_perm

