def is_balanced(s):
    balance = 0
    for char in s:
        if char == '(':
            balance += 1
        else:
            balance -= 1
        if balance < 0:
            return False
    return balance == 0

def make_neat_and_clean(n, k, s):
    operations = []
    balanced_prefixes = 0

    for i in range(1, n + 1):
        if is_balanced(s[:i]):
            balanced_prefixes += 1
        if balanced_prefixes == k:
            break

    if balanced_prefixes < k:
        # Reverse the entire string to make it balanced
        operations.append((1, n))
        s = s[::-1]
        balanced_prefixes = 0

        for i in range(1, n + 1):
            if is_balanced(s[:i]):
                balanced_prefixes += 1
            if balanced_prefixes == k:
                break

    return len(operations), operations

