def min_cost_to_break_chocolate(n, m, k):
    if k == 1:
        return n * m - 1
    if k == n * m:
        return 0
    if k == n:
        return m - 1
    if k == m:
        return n - 1
    if k < n:
        return min_cost_to_break_chocolate(n, k, k) + m * m
    if k < m:
        return min_cost_to_break_chocolate(k, m, k) + n * n
    if k > n * m - n:
        return min_cost_to_break_chocolate(n, m, n * m - k) + n * n
    if k > n * m - m:
        return min_cost_to_break_chocolate(n, m, n * m - k) + m * m
    return min(min_cost_to_break_chocolate(n, k, k) + m * m, min_cost_to_break_chocolate(k, m, k) + n * n)

