def can_form_keyboard(s):
    n = len(s)
    if n == 1:
        return "YES", "abcdefghijklmnopqrstuvwxyz"

    # Create a list of unique characters in the order they appear
    unique_chars = []
    for char in s:
        if char not in unique_chars:
            unique_chars.append(char)

    # Check if we can form a valid keyboard layout
    if len(unique_chars) > 26:
        return "NO", ""

    # Try to form a valid layout
    layout = [None] * 26
    for i, char in enumerate(unique_chars):
        layout[i] = char

    # Check if the layout is valid
    for i in range(1, len(unique_chars)):
        if abs(layout.index(unique_chars[i]) - layout.index(unique_chars[i-1])) != 1:
            return "NO", ""

    # Fill the remaining positions in the layout
    remaining_chars = [chr(i) for i in range(97, 123) if chr(i) not in unique_chars]
    for i in range(26):
        if layout[i] is None:
            layout[i] = remaining_chars.pop(0)

    return "YES", ''.join(layout)

