def is_beautiful(arr, k):
    target_sum = sum(arr[:k])
    for i in range(len(arr) - k + 1):
        if sum(arr[i:i+k]) != target_sum:
            return False
    return True

def make_beautiful(arr, n, k):
    if is_beautiful(arr, k):
        return n, arr

    # Try to find a pattern
    for i in range(n - k + 1):
        target_sum = sum(arr[i:i+k])
        pattern = arr[i:i+k]
        can_make_beautiful = True
        for j in range(i + k, n - k + 1):
            if sum(arr[j:j+k]) != target_sum:
                can_make_beautiful = False
                break
        if can_make_beautiful:
            # Extend the pattern to the whole array
            extended_array = []
            for j in range(n // k):
                extended_array.extend(pattern)
            if n % k != 0:
                extended_array.extend(pattern[:n % k])
            return len(extended_array), extended_array

    return -1, []

