import math
from collections import defaultdict

def get_divisors(n):
    divisors = set()
    for i in range(2, int(math.sqrt(n)) + 1):
        if n % i == 0:
            divisors.add(i)
            divisors.add(n // i)
    divisors.add(n)
    return sorted(divisors)

def is_coprime(a, b):
    return math.gcd(a, b) == 1

def find_initial_order_and_moves(n):
    divisors = get_divisors(n)
    if len(divisors) == 1:
        return [divisors[0]], 0

    # Check if any two adjacent numbers are already not coprime
    for i in range(len(divisors)):
        if not is_coprime(divisors[i], divisors[(i + 1) % len(divisors)]):
            return divisors, 0

    # If all adjacent numbers are coprime, we need to insert LCMs
    # Start with the smallest divisor and try to form a valid circle
    initial_order = [divisors[0]]
    remaining_divisors = divisors[1:]

    while remaining_divisors:
        next_divisor = None
        for d in remaining_divisors:
            if not is_coprime(initial_order[-1], d):
                next_divisor = d
                break
        if next_divisor:
            initial_order.append(next_divisor)
            remaining_divisors.remove(next_divisor)
        else:
            # If no valid next divisor is found, we need to insert LCM
            lcm = (initial_order[-1] * remaining_divisors[0]) // math.gcd(initial_order[-1], remaining_divisors[0])
            initial_order.append(lcm)
            remaining_divisors.remove(remaining_divisors[0])

    return initial_order, len(divisors) - 1

