def clean_string(s):
    result = []
    i = 0
    while i < len(s):
        if s[i] == '1':
            # Find the next '0' after the current '1'
            j = i + 1
            while j < len(s) and s[j] == '1':
                j += 1
            if j < len(s) and s[j] == '0':
                # Erase the '0' by skipping it
                i = j + 1
            else:
                # If no '0' is found, add all '1's to the result
                result.append('1' * (j - i))
                i = j
        else:
            # Add '0' to the result
            result.append('0')
            i += 1
    return ''.join(result)

