def is_sharpened(arr):
    n = len(arr)
    if n == 1:
        return True

    # Find the first peak
    peak_index = 0
    while peak_index + 1 < n and arr[peak_index] < arr[peak_index + 1]:
        peak_index += 1

    # If the array is strictly increasing or strictly decreasing
    if peak_index == n - 1 or peak_index == 0:
        return True

    # Check if the array can be made sharpened
    for i in range(peak_index, n):
        if arr[i] > arr[i - 1]:
            return False

    return True

