def min_toggles_to_compress(image, n, m):
    max_k = min(n, m)
    min_toggles = float('inf')

    for k in range(2, max_k + 1):
        padded_n = ((n + k - 1) // k) * k
        padded_m = ((m + k - 1) // k) * k
        padded_image = [['0'] * padded_m for _ in range(padded_n)]

        for i in range(n):
            for j in range(m):
                padded_image[i][j] = image[i][j]

        toggles = 0
        for i in range(0, padded_n, k):
            for j in range(0, padded_m, k):
                block_value = padded_image[i][j]
                for x in range(i, i + k):
                    for y in range(j, j + k):
                        if padded_image[x][y] != block_value:
                            toggles += 1
                            padded_image[x][y] = block_value

        min_toggles = min(min_toggles, toggles)

    return min_toggles

