def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    N = int(data[0])
    S = data[1]
    Q = int(data[2])

    queries = []
    index = 3
    for _ in range(Q):
        query_type = int(data[index])
        if query_type == 1:
            i_q = int(data[index + 1]) - 1
            c_q = data[index + 2]
            queries.append((1, i_q, c_q))
            index += 3
        elif query_type == 2:
            l_q = int(data[index + 1]) - 1
            r_q = int(data[index + 2]) - 1
            queries.append((2, l_q, r_q))
            index += 3

    # Initialize the segment tree
    segment_tree = [defaultdict(int) for _ in range(4 * N)]

    def build_segment_tree(node, start, end):
        if start == end:
            segment_tree[node][S[start]] = 1
        else:
            mid = (start + end) // 2
            build_segment_tree(2 * node + 1, start, mid)
            build_segment_tree(2 * node + 2, mid + 1, end)
            for char in segment_tree[2 * node + 1]:
                segment_tree[node][char] += segment_tree[2 * node + 1][char]
            for char in segment_tree[2 * node + 2]:
                segment_tree[node][char] += segment_tree[2 * node + 2][char]

    def update_segment_tree(node, start, end, idx, new_char):
        if start == end:
            segment_tree[node] = defaultdict(int)
            segment_tree[node][new_char] = 1
        else:
            mid = (start + end) // 2
            if start <= idx <= mid:
                update_segment_tree(2 * node + 1, start, mid, idx, new_char)
            else:
                update_segment_tree(2 * node + 2, mid + 1, end, idx, new_char)
            segment_tree[node] = defaultdict(int)
            for char in segment_tree[2 * node + 1]:
                segment_tree[node][char] += segment_tree[2 * node + 1][char]
            for char in segment_tree[2 * node + 2]:
                segment_tree[node][char] += segment_tree[2 * node + 2][char]

    def query_segment_tree(node, start, end, l, r):
        if r < start or end < l:
            return defaultdict(int)
        if l <= start and end <= r:
            return segment_tree[node]
        mid = (start + end) // 2
        left_result = query_segment_tree(2 * node + 1, start, mid, l, r)
        right_result = query_segment_tree(2 * node + 2, mid + 1, end, l, r)
        result = defaultdict(int)
        for char in left_result:
            result[char] += left_result[char]
        for char in right_result:
            result[char] += right_result[char]
        return result

    build_segment_tree(0, 0, N - 1)

    for query in queries:
        if query[0] == 1:
            i_q, c_q = query[1], query[2]
            if S[i_q] != c_q:
                update_segment_tree(0, 0, N - 1, i_q, c_q)
                S = S[:i_q] + c_q + S[i_q + 1:]
        elif query[0] == 2:
            l_q, r_q = query[1], query[2]
            result = query_segment_tree(0, 0, N - 1, l_q, r_q)
            print(len(result))

