def count_paths(n, m, labyrinth):
    dp = [[[0] * (m + 1) for _ in range(n + 1)] for _ in range(n + m + 1)]
    dp[0][1][1] = 1

    for step in range(1, n + m):
        for x in range(1, n + 1):
            for y in range(1, m + 1):
                if labyrinth[x - 1][y - 1] == 'R':
                    continue
                if x > 1:
                    dp[step][x][y] = (dp[step][x][y] + dp[step - 1][x - 1][y]) % MOD
                if y > 1:
                    dp[step][x][y] = (dp[step][x][y] + dp[step - 1][x][y - 1]) % MOD

    return dp[n + m - 2][n][m]

