def parse_input():
    import sys
    input = sys.stdin.read
    data = input().split()
    n = int(data[0])
    m = int(data[1])
    variables = []
    index = 2
    for _ in range(n):
        name = data[index]
        index += 1
        assert data[index] == ':='
        index += 1
        if data[index].isdigit():
            value = int(data[index], 2)
            variables.append((name, value))
            index += 1
        else:
            left = data[index]
            index += 1
            op = data[index]
            index += 1
            right = data[index]
            index += 1
            variables.append((name, (left, op, right)))
    return n, m, variables

def evaluate(variables, m, value):
    values = defaultdict(lambda: 0)
    for name, expr in variables:
        if isinstance(expr, int):
            values[name] = expr
        else:
            left, op, right = expr
            left_val = values[left] if left != '?' else value
            right_val = values[right] if right != '?' else value
            if op == 'AND':
                values[name] = left_val & right_val
            elif op == 'OR':
                values[name] = left_val | right_val
            elif op == 'XOR':
                values[name] = left_val ^ right_val
    return sum(values.values())

def find_min_max(n, m, variables):
    min_value = (1 << m) - 1
    max_value = 0
    for i in range(1 << m):
        value = evaluate(variables, m, i)
        if value < evaluate(variables, m, min_value):
            min_value = i
        if value > evaluate(variables, m, max_value):
            max_value = i
    return format(min_value, f'0{m}b'), format(max_value, f'0{m}b')

def main():
    n, m, variables = parse_input()
    min_value, max_value = find_min_max(n, m, variables)
    print(min_value)
    print(max_value)

