from collections import defaultdict

def find(parent, i):
    if parent[i] == i:
        return i
    parent[i] = find(parent, parent[i])
    return parent[i]

def union(parent, rank, x, y):
    rootX = find(parent, x)
    rootY = find(parent, y)
    if rootX != rootY:
        if rank[rootX] > rank[rootY]:
            parent[rootY] = rootX
        elif rank[rootX] < rank[rootY]:
            parent[rootX] = rootY
        else:
            parent[rootY] = rootX
            rank[rootX] += 1

def min_cost_to_connect_all_employees(n, m, languages):
    parent = list(range(n))
    rank = [0] * n
    language_to_employees = defaultdict(list)

    for i in range(n):
        for lang in languages[i]:
            language_to_employees[lang].append(i)

    edges = []
    for lang, employees in language_to_employees.items():
        for i in range(len(employees)):
            for j in range(i + 1, len(employees)):
                edges.append((1, employees[i], employees[j]))

    for i in range(n):
        for j in range(i + 1, n):
            edges.append((1, i, j))

    edges.sort()

    mst_cost = 0
    for cost, u, v in edges:
        if find(parent, u) != find(parent, v):
            union(parent, rank, u, v)
            mst_cost += cost

    return mst_cost

