def dot_product(v1, v2):
    return sum(x * y for x, y in zip(v1, v2))

def magnitude(v):
    return math.sqrt(dot_product(v, v))

def is_good_point(points, i):
    for j in range(len(points)):
        if j == i:
            continue
        for k in range(j + 1, len(points)):
            if k == i:
                continue
            vec_ab = [points[j][d] - points[i][d] for d in range(5)]
            vec_ac = [points[k][d] - points[i][d] for d in range(5)]
            cos_angle = dot_product(vec_ab, vec_ac) / (magnitude(vec_ab) * magnitude(vec_ac))
            if cos_angle > 0:
                return False
    return True

