        for i in range(m):
            if removed[i]:
                continue
            x, y, _ = cubes[i]
            if y == 0:
                continue
            stable = False
            for dx in [-1, 0, 1]:
                if (x + dx, y - 1) in cubes and not removed[cubes.index((x + dx, y - 1, _))]:
                    stable = True
                    break
            if not stable:
                return False
        return True

    removed = [False] * m
    result = 0
    base = m

    for i in range(m - 1, -1, -1):
        removed[i] = True
        if is_stable(cubes, removed):
            result = (result * base + cubes[i][2]) % MOD
        else:
            removed[i] = False

    print(result)

