def contains_all_substrings(s, k):
    required = 1 << k
    seen = set()
    for i in range(len(s) - k + 1):
        substring = s[i:i + k]
        if substring not in seen:
            seen.add(substring)
            required -= 1
            if required == 0:
                return True
    return False

