def is_prime(num):
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

def min_colors(n):
    colors = [0] * (n + 1)
    color_count = 0

    for i in range(2, n + 2):
        if colors[i] == 0:
            color_count += 1
            colors[i] = color_count
            for j in range(i * 2, n + 2, i):
                if is_prime(i):
                    colors[j] = color_count

    return color_count, colors[2:]

