def count_pretty_substrings(s):
    n = len(s)
    dp = [[0] * (n + 1) for _ in range(n + 1)]
    open_count = [0] * (n + 1)
    close_count = [0] * (n + 1)

    for i in range(1, n + 1):
        if s[i - 1] == '(':
            open_count[i] = open_count[i - 1] + 1
        elif s[i - 1] == ')':
            close_count[i] = close_count[i - 1] + 1
        else:
            open_count[i] = open_count[i - 1]
            close_count[i] = close_count[i - 1]

    for length in range(1, n + 1):
        for l in range(1, n - length + 2):
            r = l + length - 1
            if s[l - 1] == '(' or s[l - 1] == '?':
                if s[r - 1] == ')' or s[r - 1] == '?':
                    dp[l][r] = dp[l + 1][r - 1] + 1
            if s[l - 1] == '(' or s[l - 1] == '?':
                dp[l][r] += dp[l + 1][r]
            if s[r - 1] == ')' or s[r - 1] == '?':
                dp[l][r] += dp[l][r - 1]
            if s[l - 1] == ')' or s[l - 1] == '?':
                dp[l][r] -= dp[l + 1][r - 1]

    total_pretty = 0
    for l in range(1, n + 1):
        for r in range(l, n + 1):
            if dp[l][r] > 0:
                total_pretty += 1

    return total_pretty

