def solve(m, s):
    n = len(s)
    freq = [0] * 26
    for char in s:
        freq[ord(char) - ord('a')] += 1

    result = []
    window = deque()
    for i in range(n):
        window.append(s[i])
        freq[ord(s[i]) - ord('a')] -= 1

        if i >= m:
            freq[ord(window.popleft()) - ord('a')] += 1

        if i >= m - 1:
            for j in range(26):
                if freq[j] == 0:
                    result.append(chr(ord('a') + j))
                    freq[j] = -1
                    break

    return ''.join(result)

