from collections import deque

def max_strength_of_groups(n, heights):
    max_strengths = [0] * n
    min_stack = deque()

    for i in range(n):
        while min_stack and heights[min_stack[-1]] >= heights[i]:
            min_stack.pop()
        if min_stack:
            max_strengths[i - min_stack[0] - 1] = max(max_strengths[i - min_stack[0] - 1], heights[i])
        min_stack.append(i)

    for i in range(n - 1, -1, -1):
        if min_stack and min_stack[0] - i >= n:
            min_stack.popleft()
        if min_stack:
            max_strengths[min_stack[0] - i - 1] = max(max_strengths[min_stack[0] - i - 1], heights[i])
        min_stack.appendleft(i)

    for i in range(n - 2, -1, -1):
        max_strengths[i] = max(max_strengths[i], max_strengths[i + 1])

    return max_strengths

