MOD = 1_000_000_007

def factorial(n, mod):
    result = 1
    for i in range(2, n + 1):
        result = result * i % mod
    return result

def mod_inverse(a, mod):
    return pow(a, mod - 2, mod)

def nCr(n, r, mod):
    if r > n:
        return 0
    num = factorial(n, mod)
    den = factorial(r, mod) * factorial(n - r, mod) % mod
    return num * mod_inverse(den, mod) % mod

