def is_finite_fraction(p, q, b):
    # Reduce the fraction p/q by removing common factors
    while p % 2 == 0 and q % 2 == 0:
        p //= 2
        q //= 2
    while p % 5 == 0 and q % 5 == 0:
        p //= 5
        q //= 5

    # Check if q is a product of powers of b
    while q % b == 0:
        q //= b

    return q == 1

