import sys

def max_total_gain(n, m, a):
    # Initialize DP tables for Iahub and Iahubina
    dp_i = [[0] * m for _ in range(n)]
    dp_j = [[0] * m for _ in range(n)]

    # Fill DP table for Iahub
    dp_i[0][0] = a[0][0]
    for i in range(n):
        for j in range(m):
            if i > 0:
                dp_i[i][j] = max(dp_i[i][j], dp_i[i-1][j] + a[i][j])
            if j > 0:
                dp_i[i][j] = max(dp_i[i][j], dp_i[i][j-1] + a[i][j])

    # Fill DP table for Iahubina
    dp_j[n-1][0] = a[n-1][0]
    for i in range(n-1, -1, -1):
        for j in range(m):
            if i < n-1:
                dp_j[i][j] = max(dp_j[i][j], dp_j[i+1][j] + a[i][j])
            if j > 0:
                dp_j[i][j] = max(dp_j[i][j], dp_j[i][j-1] + a[i][j])

    # Calculate the maximum total gain
    max_gain = 0
    for i in range(n):
        for j in range(m):
            max_gain = max(max_gain, dp_i[i][j] + dp_j[i][j] - a[i][j])

    return max_gain

