def count_possible_strings(s):
    n = len(s)
    dp = [0] * (n + 1)
    dp[0] = 1

    for i in range(n):
        if s[i] == '0':
            dp[i + 1] = dp[i] * 2 % MOD
        else:
            dp[i + 1] = (dp[i] * 2 + dp[i - 1]) % MOD

    return dp[n]

