import sys

def find_palindrome_subsequence(s):
    n = len(s)
    # Create a table to store results of subproblems
    dp = [[0] * n for _ in range(n)]

    # Strings of length 1 are palindromes of length 1
    for i in range(n):
        dp[i][i] = 1

    # Build the table. The outer loop is for substrings of increasing length
    for cl in range(2, n + 1):
        for i in range(n - cl + 1):
            j = i + cl - 1
            if s[i] == s[j] and cl == 2:
                dp[i][j] = 2
            elif s[i] == s[j]:
                dp[i][j] = dp[i + 1][j - 1] + 2
            else:
                dp[i][j] = max(dp[i][j - 1], dp[i + 1][j])

    # Reconstruct the palindrome
    i = 0
    j = n - 1
    result = []
    while i <= j:
        if s[i] == s[j]:
            result.append(s[i])
            if i != j:
                result.append(s[j])
            i += 1
            j -= 1
        elif dp[i][j - 1] > dp[i + 1][j]:
            result.append(s[j])
            j -= 1
        else:
            result.append(s[i])
            i += 1

    return ''.join(result)

