def reconstruct_permutation(n, a):
    # Initialize the permutation with None
    p = [None] * n

    # Fill the permutation with the smallest possible values
    for i in range(n):
        # Find the smallest value in the i-th row that is not yet assigned
        for j in range(n):
            if a[i][j] != 0 and p[j] is None:
                p[j] = a[i][j]
                break

    # Assign the remaining values
    for i in range(n):
        if p[i] is None:
            # Find the smallest value that is not yet used
            for j in range(1, n + 1):
                if j not in p:
                    p[i] = j
                    break

    return p

