def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    k = int(data[1])

    guests = []
    index = 2
    for _ in range(k):
        x = int(data[index])
        y = int(data[index + 1])
        guests.append((x, y))
        index += 2

    # Create a graph where each node is a snack flavor
    # and there is an edge between two nodes if a guest likes both snacks
    graph = defaultdict(list)
    for x, y in guests:
        graph[x].append(y)
        graph[y].append(x)

    # Find the maximum matching in the graph
    # This can be done using the Hopcroft-Karp algorithm or any other max matching algorithm
    # Here we use a simple BFS approach for simplicity

    # Initialize the matching
    matching = {}

    # BFS to find an augmenting path
    def bfs(start):
        queue = deque([start])
        parent = {start: None}
        while queue:
            u = queue.popleft()
            for v in graph[u]:
                if v not in parent and v not in matching:
                    parent[v] = u
                    queue.append(v)
                elif v in matching and v not in parent:
                    parent[v] = u
                    u_prime = matching[v]
                    if u_prime not in parent:
                        parent[u_prime] = v
                        queue.append(u_prime)
        return parent

    # Augment the matching
    def augment(path):
        u = path[-1]
        while u is not None:
            v = path[u]
            matching[v] = u
            u = parent[u]

    # Find the maximum matching
    for u in range(1, n + 1):
        if u not in matching:
            parent = bfs(u)
            path = {}
            for v in parent:
                if parent[v] is not None:
                    path[v] = parent[v]
            if path:
                augment(path)

    # The number of sad guests is the number of guests minus the size of the matching
    print(k - len(matching) // 2)

