def find_regular_subsequence(n, k, s):
    open_count = 0
    result = []

    for char in s:
        if char == '(':
            open_count += 1
            result.append(char)
            if len(result) == k:
                break
        elif char == ')' and open_count > 0:
            open_count -= 1
            result.append(char)
            if len(result) == k:
