def bfs(grid, r, c):
    queue = deque()
    visited = [[False] * c for _ in range(r)]
    for i in range(r):
        for j in range(c):
            if grid[i][j] == 'A':
                queue.append((i, j))
                visited[i][j] = True

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    while queue:
        x, y = queue.popleft()
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < r and 0 <= ny < c and not visited[nx][ny]:
                visited[nx][ny] = True
                queue.append((nx, ny))

    for i in range(r):
        for j in range(c):
            if not visited[i][j]:
                return False
    return True

