    import sys
    import math

    def find_greatest_x(p, q):
        # Start with the largest divisor of p, which is p itself
        x = p
        while x % q == 0:
            x //= q
        # If x is now 1, we need to find the next largest divisor of p
        if x == 1:
            x = p
            # Find the largest divisor of p that is not divisible by q
            for i in range(p // 2, 0, -1):
                if p % i == 0 and i % q != 0:
                    x = i
                    break
        return x

