def is_palindrome(s):
    return s == s[::-1]

def count_palindrome_pairs(words):
    word_count = defaultdict(int)
    for word in words:
        word_count[word] += 1

    palindrome_pairs = 0

    for word in words:
        n = len(word)
        for i in range(n + 1):
            prefix = word[:i]
            suffix = word[i:]

            reversed_prefix = prefix[::-1]
            reversed_suffix = suffix[::-1]

            if is_palindrome(suffix) and reversed_prefix in word_count:
                if reversed_prefix == word:
                    palindrome_pairs += word_count[word] - 1
                else:
                    palindrome_pairs += word_count[reversed_prefix]

            if is_palindrome(prefix) and reversed_suffix in word_count:
                if reversed_suffix == word:
                    palindrome_pairs += word_count[word] - 1
                else:
                    palindrome_pairs += word_count[reversed_suffix]

    return palindrome_pairs // 2

