MOD = 10**9 + 7

def count_sequences(N, X, Y, Z):
    # Precompute the number of ways to get a sum with a given length
    dp = [[0] * 11 for _ in range(N + 1)]
    for i in range(N + 1):
        dp[i][0] = 1
    for i in range(1, N + 1):
        for j in range(1, 11):
            for k in range(max(0, j - 10), i):
                dp[i][j] = (dp[i][j] + dp[k][j - 1]) % MOD

    # Calculate the number of valid sequences
    count = 0
    for x in range(N - 2):
        for y in range(x + 1, N - 1):
            for z in range(y + 1, N):
                for w in range(z + 1, N + 1):
                    if (dp[y][X] * dp[z][Y] * dp[w][Z]) % MOD != 0:
                        count = (count + dp[x][X] * dp[y][Y] * dp[z][Z] * dp[w][Z]) % MOD

    return count

