def is_good_string(s):
    n = len(s)
    for k in range(2, n + 1):
        if n % k == 0:
            period = n // k
            if s == s[:period] * k:
                return False
    return True

def best_representation(w):
    n = len(w)
    dp = [0] * (n + 1)
    count = [0] * (n + 1)
    dp[0] = 1
    count[0] = 1

    for i in range(1, n + 1):
        dp[i] = float('inf')
        for j in range(i):
            if is_good_string(w[j:i]):
                if dp[j] + 1 < dp[i]:
                    dp[i] = dp[j] + 1
                    count[i] = count[j]
                elif dp[j] + 1 == dp[i]:
                    count[i] = (count[i] + count[j]) % MOD

    return dp[n], count[n]

