    dp[0][0] = 1

    for i in range(1, N + 1):
        for j in range(i + 1):
            if j > 0:
                dp[i][j] = (dp[i][j] + dp[i - 1][j - 1]) % MOD
            if j < i:
                dp[i][j] = (dp[i][j] + dp[i - 1][j + 1]) % MOD

