def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    edges = [(int(data[2*i+1]), int(data[2*i+2])) for i in range(n-1)]

    # Build the adjacency list for the given tree
    adj = defaultdict(list)
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    # Find the root of the tree (vertex with degree 1, except for the case of a single edge)
    root = None
    for i in range(1, n+1):
        if len(adj[i]) == 1:
            root = i
            break
    if root is None:
        # Special case where the tree is a single edge
        if n == 2:
            print("1 2")
        else:
            print("-1")
        return

    # Perform DFS to determine the parent of each node
    parent = {root: None}
    stack = [root]
    while stack:
        node = stack.pop()
        for neighbor in adj[node]:
            if neighbor != parent[node]:
                parent[neighbor] = node
                stack.append(neighbor)

    # Determine the order of nodes based on the parent relationship
    order = []
    for i in range(1, n+1):
        if parent[i] is None:
            order.append(i)
        else:
            order.append(parent[i])

    # Generate the permutation
    permutation = [0] * (n + 1)
    for i, node in enumerate(order, start=1):
        permutation[node] = i

    # Check if the generated permutation can produce the given tree
    def generate_tree_from_permutation(perm):
        adj_list = defaultdict(list)
        for i in range(2, n+1):
            j = i - 1
            while j > 0 and perm[j] >= perm[i]:
                j -= 1
            if j > 0:
                adj_list[perm[i]].append(perm[j])
                adj_list[perm[j]].append(perm[i])
        return adj_list

    generated_tree = generate_tree_from_permutation(permutation)

    # Check if the generated tree is isomorphic to the given tree
    if len(generated_tree) != n - 1:
        print("-1")
        return

    # Check if the generated tree has the same edges as the given tree
    generated_edges = set()
    for u in generated_tree:
        for v in generated_tree[u]:
            if u < v:
                generated_edges.add((u, v))
            else:
                generated_edges.add((v, u))

    if generated_edges == set(edges):
        print(" ".join(map(str, permutation[1:])))
    else:
        print("-1")

