def solve(n, p):
    max_medals = n // 2
    g = s = b = 0

    for i in range(n):
        if g == 0:
            g = 1
        elif s == 0:
            s = 1
        elif b == 0:
            b = 1
        else:
            if g + s + b > max_medals:
                break
            if p[i] < p[i + g]:
                g += 1
            elif p[i] < p[i + g + s]:
                s += 1
            elif p[i] < p[i + g + s + b]:
                b += 1
            else:
                break

    if g == 0 or s == 0 or b == 0 or g + s + b > max_medals:
        return 0, 0, 0
    return g, s, b

