def count_multisets(N, K):
    dp = [[0] * (K + 1) for _ in range(N + 1)]
    dp[0][0] = 1

    for n in range(1, N + 1):
        for k in range(K + 1):
            dp[n][k] = dp[n - 1][k]
            if k >= 1:
                dp[n][k] = (dp[n][k] + dp[n][k - 1]) % MOD
            if k >= 2:
                dp[n][k] = (dp[n][k] + dp[n][k - 2]) % MOD
            if k >= 4:
                dp[n][k] = (dp[n][k] + dp[n][k - 4]) % MOD
            if k >= 8:
                dp[n][k] = (dp[n][k] + dp[n][k - 8]) % MOD
            if k >= 16:
                dp[n][k] = (dp[n][k] + dp[n][k - 16]) % MOD
            if k >= 32:
                dp[n][k] = (dp[n][k] + dp[n][k - 32]) % MOD
            if k >= 64:
                dp[n][k] = (dp[n][k] + dp[n][k - 64]) % MOD
            if k >= 128:
                dp[n][k] = (dp[n][k] + dp[n][k - 128]) % MOD
            if k >= 256:
                dp[n][k] = (dp[n][k] + dp[n][k - 256]) % MOD
            if k >= 512:
                dp[n][k] = (dp[n][k] + dp[n][k - 512]) % MOD
            if k >= 1024:
                dp[n][k] = (dp[n][k] + dp[n][k - 1024]) % MOD
            if k >= 2048:
                dp[n][k] = (dp[n][k] + dp[n][k - 2048]) % MOD

    return dp[N][K]

