import re

def is_valid_credit_card(card_number):
    # Check if the card number starts with 4, 5, or 6
    if not re.match(r'^[456]', card_number):
        return False

    # Check if the card number contains exactly 16 digits
    if not re.match(r'^\d{16}$', card_number.replace('-', '')):
        return False

    # Check if the card number only consists of digits (0-9)
    if not re.match(r'^\d+$', card_number.replace('-', '')):
        return False

    # Check if the card number may have digits in groups of 4, separated by one hyphen "-"
    if not re.match(r'^(\d{4}-){3}\d{4}$|^\d{16}$', card_number):
        return False

    # Check if the card number must NOT use any other separator like ' ' , '_', etc.
    if re.search(r'[^0-9-]', card_number):
        return False

    # Check if the card number must NOT have 4 or more consecutive repeated digits
    if re.search(r'(\d)\1{3,}', card_number.replace('-', '')):
        return False

    return True

