def find_min_D(n, a):
    min_val = min(a)
    max_val = max(a)
    if min_val == max_val:
        return 0

    for D in range(1, (max_val - min_val) // 2 + 1):
        valid = True
        for x in a:
            if (x - min_val) % (2 * D) != 0:
                valid = False
                break
        if valid:
            return D

    return -1

