def min_moves_to_divisible_by_25(n):
    n_str = str(n)
    length = len(n_str)

    # Check for the presence of '00', '25', '50', '75'
    if '00' in n_str:
        return 0

    # Find the positions of '0', '2', '5', '7'
    zero_positions = [i for i, digit in enumerate(n_str) if digit == '0']
    two_positions = [i for i, digit in enumerate(n_str) if digit == '2']
    five_positions = [i for i, digit in enumerate(n_str) if digit == '5']
    seven_positions = [i for i, digit in enumerate(n_str) if digit == '7']

    min_moves = float('inf')

    # Check for '25'
    for pos2 in two_positions:
        for pos5 in five_positions:
            if pos5 > pos2:
                moves = pos2 + (length - pos5 - 1)
                min_moves = min(min_moves, moves)

    # Check for '50'
    for pos5 in five_positions:
        for pos0 in zero_positions:
            if pos0 > pos5:
                moves = pos5 + (length - pos0 - 1)
                min_moves = min(min_moves, moves)

    # Check for '75'
    for pos7 in seven_positions:
        for pos5 in five_positions:
            if pos5 > pos7:
                moves = pos7 + (length - pos5 - 1)
                min_moves = min(min_moves, moves)

    if min_moves == float('inf'):
        return -1
    else:
        return min_moves

