import math

def find_min_x(n, divisors):
    if n == 0:
        return -1
    if n == 1:
        return divisors[0] * 2

    # Calculate the LCM of all divisors
    def lcm(a, b):
        return a * b // math.gcd(a, b)

    lcm_value = divisors[0]
    for d in divisors[1:]:
        lcm_value = lcm(lcm_value, d)

    # Check if the LCM is divisible by all divisors
    for d in divisors:
        if lcm_value % d != 0:
            return -1

    # Check if the LCM has exactly n+2 divisors
    def count_divisors(x):
        count = 0
        for i in range(1, int(math.sqrt(x)) + 1):
            if x % i == 0:
                if i * i == x:
                    count += 1
                else:
                    count += 2
        return count

    if count_divisors(lcm_value) == n + 2:
        return lcm_value
    else:
        return -1

