import math

def is_power_of_two(x):
    return (x & (x - 1)) == 0 and x != 0

def min_elements_to_remove(n, a):
    if n == 0:
        return 0

    # Count the frequency of each element
    freq = {}
    for num in a:
        freq[num] = freq.get(num, 0) + 1

    # Create a list of unique elements
    unique_elements = list(freq.keys())

    # Precompute all possible sums that are powers of two
    max_val = max(a)
    power_of_twos = set(2**i for i in range(32) if 2**i <= 2 * max_val)

    # Create a graph where each node is a unique element
    # and there is an edge between two nodes if their sum is a power of two
    graph = {num: [] for num in unique_elements}
    for i in range(len(unique_elements)):
        for j in range(i, len(unique_elements)):
            if unique_elements[i] + unique_elements[j] in power_of_twos:
                graph[unique_elements[i]].append(unique_elements[j])
                graph[unique_elements[j]].append(unique_elements[i])

    # Function to find the maximum matching in the graph
    def max_matching(graph):
        matching = {}
        visited = set()

        def dfs(u):
            for v in graph[u]:
                if v not in visited:
                    visited.add(v)
                    if v not in matching or dfs(matching[v]):
                        matching[v] = u
                        return True
            return False

        for u in graph:
            visited.clear()
            if dfs(u):
                pass

        return matching

    # Find the maximum matching
    matching = max_matching(graph)

    # The minimum number of elements to remove is the number of unique elements
    # minus the size of the maximum matching
    return len(unique_elements) - len(matching)

