def find_kth_character(S, K):
    # Calculate the length of the string after infinite days
    length_after_infinite_days = 0
    for char in S:
        if char == '1':
            length_after_infinite_days += 1
        else:
            length_after_infinite_days += int(char) * int(char)

    # If K is within the length of the string after infinite days, find the character
    if K <= length_after_infinite_days:
        current_position = 0
        for char in S:
            if char == '1':
                current_position += 1
                if current_position == K:
                    return '1'
            else:
                repeat_count = int(char)
                if current_position + repeat_count * repeat_count >= K:
                    # Find the exact position within the repeated segment
                    position_in_segment = K - current_position
                    digit = int(char)
                    return str(digit)[(position_in_segment - 1) // digit]
                current_position += repeat_count * repeat_count
    else:
        return ''

