def main():
    import sys
    import heapq

    input = sys.stdin.read
    data = input().split()

    N = int(data[0])
    A = list(map(int, data[1:]))

    # Find the maximum value in the array
    max_value = max(A)

    # Create a max heap of all elements except the maximum value
    max_heap = []
    for a in A:
        if a != max_value:
            heapq.heappush(max_heap, -a)

    # If there are less than N-1 elements, the max heap will be empty
    if len(max_heap) < N - 1:
        max_value_in_heap = max_value
    else:
        max_value_in_heap = -heapq.heappop(max_heap)

    # Prepare the result array
    result = []
    for a in A:
        if a == max_value:
            result.append(max_value_in_heap)
        else:
            result.append(max_value)

    # Print the result
    for r in result:
        print(r)

