def main():
    import sys
    import heapq

    def read_ints():
        return map(int, sys.stdin.readline().split())

    n, m = read_ints()
    k = list(read_ints())

    offers = defaultdict(list)
    for _ in range(m):
        d, t = read_ints()
        offers[t].append(d)

    total_days = 0
    pq = []

    for i in range(1, n + 1):
        if k[i - 1] > 0:
            if offers[i]:
                heapq.heappush(pq, (offers[i][0], i, 0, 2))
            else:
                heapq.heappush(pq, (float('inf'), i, 0, 2))

    while pq:
        day, transaction_type, bought, price = heapq.heappop(pq)
        if bought < k[transaction_type - 1]:
            total_days = max(total_days, day)
            if bought + 1 < k[transaction_type - 1]:
                next_day = day + 1
                if offers[transaction_type] and offers[transaction_type][0] == next_day:
                    heapq.heappush(pq, (next_day, transaction_type, bought + 1, 1))
                else:
                    heapq.heappush(pq, (next_day, transaction_type, bought + 1, 2))

    print(total_days)

