import sys

def find_optimal_substring(n, s):
    # Calculate the final position of the robot
    x, y = 0, 0
    for move in s:
        if move == 'L':
            x -= 1
        elif move == 'R':
            x += 1
        elif move == 'U':
            y += 1
        elif move == 'D':
            y -= 1

    # If the final position is (0, 0), no need to remove any substring
    if x == 0 and y == 0:
        return -1, -1

    # Find the first and last occurrence of the final position
    first_x, first_y = 0, 0
    last_x, last_y = 0, 0
    first_pos = -1
    last_pos = -1

    for i, move in enumerate(s):
        if move == 'L':
            first_x -= 1
            last_x -= 1
        elif move == 'R':
            first_x += 1
            last_x += 1
        elif move == 'U':
            first_y += 1
            last_y += 1
        elif move == 'D':
            first_y -= 1
            last_y -= 1

        if first_x == x and first_y == y and first_pos == -1:
            first_pos = i + 1
        if last_x == x and last_y == y:
            last_pos = i + 1

    # If we can't find a valid substring, return -1
    if first_pos == -1 or last_pos == -1:
        return -1, -1

    # Return the shortest substring that can be removed
    return first_pos, last_pos

