def find_next_good_number(n):
    # Convert n to base 3
    base3 = []
    while n > 0:
        base3.append(n % 3)
        n //= 3

    # Adjust the base 3 representation to make it a good number
    carry = 0
    for i in range(len(base3)):
        base3[i] += carry
        if base3[i] >= 3:
            base3[i] -= 3
            carry = 1
        else:
            carry = 0

    # If there's a carry left, add a new digit
    if carry == 1:
        base3.append(1)

    # Convert the adjusted base 3 back to a decimal number
    m = 0
    for i in range(len(base3)):
        m += base3[i] * (3 ** i)

    return m

