    if sum(a) ^ sum(b) != 0:
        print("NO")
        return

    # Construct the matrix
    matrix = [[0] * m for _ in range(n)]

    # Fill the matrix
    for i in range(n):
        for j in range(m-1):
            matrix[i][j] = 0
        matrix[i][m-1] = a[i]
        for j in range(m-1):
            matrix[i][m-1] ^= matrix[i][j]

    # Adjust the last column to match the column XORs
    for j in range(m):
        xor_sum = 0
        for i in range(n-1):
            xor_sum ^= matrix[i][j]
        matrix[n-1][j] = b[j] ^ xor_sum

    # Verify the solution
    for i in range(n):
        if sum(matrix[i]) ^ a[i] != 0:
            print("NO")
            return

    for j in range(m):
        xor_sum = 0
        for i in range(n):
