def transform_to_perfect_longcat(x):
    if x == 0:
        return 0, []

    operations = []
    current = x
    target = 1
    while current != target:
        if current < target:
            operations.append(0)
            current ^= (1 << 0) - 1
        else:
            diff = current - target
            n = 0
            while (1 << (n + 1)) - 1 <= diff:
                n += 1
            operations.append(n)
            current ^= (1 << n) - 1
        target = (1 << (len(bin(current)) - 2)) - 1

    return len(operations), operations

