def count_camels(n, t):
    def is_valid_polyline(polyline):
        humps = 0
        valleys = 0
        for i in range(1, n - 1):
            if polyline[i - 1] < polyline[i] > polyline[i + 1]:
                humps += 1
            elif polyline[i - 1] > polyline[i] < polyline[i + 1]:
                valleys += 1
        return humps == t and valleys == t - 1

    count = 0
    for polyline in product(range(1, 5), repeat=n):
        if polyline[0] != polyline[1] and polyline[-2] != polyline[-1]:
            if is_valid_polyline(polyline):
                count += 1
    return count

