def count_enclosed_cows(x1, y1, x2, y2, x3, y3):
    # Count the number of cows enclosed by the triangle
    count = 0
    for x in range(min(x1, x2, x3), max(x1, x2, x3) + 1, 2):
        for y in range(min(y1, y2, y3), max(y1, y2, y3) + 1, 2):
            if (x, y) != (x1, y1) and (x, y) != (x2, y2) and (x, y) != (x3, y3):
                # Check if the point (x, y) is inside the triangle
                if (x - x1) * (y2 - y1) * (x3 - x1) + (x - x2) * (y3 - y2) * (x1 - x2) + (x - x3) * (y1 - y3) * (x2 - x3) > 0:
