MOD = 10**9 + 7

def bfs_distance(tree, start):
    n = len(tree)
    dist = [-1] * n
    queue = [start]
    dist[start] = 0
    while queue:
        u = queue.pop(0)
        for v in tree[u]:
            if dist[v] == -1:
                dist[v] = dist[u] + 1
                queue.append(v)
    return dist

def count_ways(tree, k):
    n = len(tree)
    total_ways = 0
    for center in range(n):
        dist = bfs_distance(tree, center)
        freq = [0] * (n + 1)
        for d in dist:
            if d != -1:
                freq[d] += 1
        for d in range(1, n):
            if freq[d] >= k:
                total_ways = (total_ways + comb(freq[d], k)) % MOD
    return total_ways

def comb(n, k):
    if k > n:
        return 0
    if k == 0 or k == n:
        return 1
    k = min(k, n - k)
    c = 1
    for i in range(k):
        c = c * (n - i) // (i + 1)
    return c

