def min_kicks(s):
    n = len(s)
    team1_goals = 0
    team2_goals = 0
    team1_max_possible = 0
    team2_max_possible = 0

    for i in range(n):
        if i % 2 == 0:
            if s[i] == '1':
                team1_goals += 1
            elif s[i] == '?':
                team1_max_possible += 1
        else:
            if s[i] == '1':
                team2_goals += 1
            elif s[i] == '?':
                team2_max_possible += 1

        if team1_goals > team2_goals + team2_max_possible:
            return i + 1
        if team2_goals > team1_goals + team1_max_possible:
            return i + 1

    return n

