def count_regular_subsequences(n, c):
    total = 0
    balance = 0
    count = [0] * (n + 1)

    for i in range(1, n + 1):
        if i % 2 == 1:
            balance += c[i - 1]
        else:
            balance -= c[i - 1]

        if balance < 0:
            balance = 0
        else:
            count[balance] += 1

    for i in range(n + 1):
        total += count[i] * (count[i] + 1) // 2

    return total

