    if sum(a) == 0:
        # All roads go from i to n+1
        return list(range(1, n+1)) + [n+1]
    elif sum(a) == n:
        # All roads go from n+1 to i
        return [n+1] + list(range(1, n+1))
    else:
        # Try to find a valid path
