def count_mathematical_states(n, m, ranges):
    from functools import lru_cache

    @lru_cache(None)
    def dp(i, sum_so_far, gcd_so_far):
        if i == n:
            return 1 if sum_so_far <= m and gcd_so_far == 1 else 0
        count = 0
        for a in range(ranges[i][0], ranges[i][1] + 1):
            new_gcd = gcd(gcd_so_far, a)
            if new_gcd == 1 or sum_so_far + a <= m:
                count = (count + dp(i + 1, sum_so_far + a, new_gcd)) % MOD
        return count

    return dp(0, 0, 0)

