    # Count the frequency of each character in t
    freq = Counter(t)

    # Find the length of the original string s
    n = len(t)
    for i in range(1, n + 1):
        if n % i == 0:
            candidate_s = t[:i]
            candidate_t = ""
            remaining_t = t
            while remaining_t:
                candidate_t += candidate_s
                if candidate_t == remaining_t[:len(candidate_t)]:
                    remaining_t = remaining_t[len(candidate_t):]
                else:
                    break
            if not remaining_t:
                # Check if the candidate_s can be formed by removing characters in order
                candidate_freq = Counter(candidate_s)
                order = ""
                for char in candidate_s:
                    if candidate_freq[char] > 0:
                        order += char
                        candidate_freq[char] = 0
                return candidate_s, order
    return -1, -1

