def f(a, i):
    if a[i] > a[i + 1]:
        a[i], a[i + 1] = a[i + 1], a[i]

def sort_permutation(n, a):
    iterations = 0
    while True:
        sorted = True
        if iterations % 2 == 0:
            for i in range(0, n - 1, 2):
                f(a, i)
                if a[i] > a[i + 1]:
                    sorted = False
        else:
            for i in range(1, n - 1, 2):
                f(a, i)
                if a[i] > a[i + 1]:
                    sorted = False
        iterations += 1
        if sorted:
            break
    return iterations - 1

