def longest_increasing_subsequence(s):
    n = len(s)
    expansion = []
    for i in range(n):
        for j in range(i + 1, n + 1):
            expansion.append(s[i:j])

    expansion.sort()

    lis = [1] * len(expansion)
    for i in range(1, len(expansion)):
        for j in range(i):
            if expansion[i] > expansion[j] and lis[i] < lis[j] + 1:
                lis[i] = lis[j] + 1

    return max(lis)

