def max_median(n, s):
    if n == 1:
        return s
    if s == 0:
        return 0
    if s < n:
        return 0
    if s == n:
        return 1
    if n % 2 == 1:
        return max(s // n, (s - n) // (n - 1))
    else:
        return max(s // n, (s - n + 1) // (n - 1))

