def mex(s):
    if '0' not in s:
        return 0
    if '1' not in s:
        return 1
    return 2

def solve(s):
    n = len(s)
    dp = [0] * (n + 1)
    for i in range(1, n + 1):
        dp[i] = dp[i - 1] + mex(s[:i])
        for j in range(i):
            dp[i] = min(dp[i], dp[j] + mex(s[j:i]))
    return dp[n]

