    data = input().split()

    n = int(data[0])
    m = int(data[1])
    k = int(data[2])

    queries = []
    index = 3
    for _ in range(k):
        x = int(data[index]) - 1
        y = int(data[index + 1]) - 1
        t = int(data[index + 2])
        queries.append((x, y, t))
        index += 3

    def count_ways(n, m, matrix):
        if n < 2 or m < 2:
            return 1

        def is_valid_2x2(x, y):
            if x + 1 >= n or y + 1 >= m:
                return True
            count = 0
            for dx in range(2):
                for dy in range(2):
                    if matrix[x + dx][y + dy] == 1:
                        count += 1
            return count == 2

        def count_ways_recursive(x, y):
            if x == n - 1 and y == m - 1:
                return 1 if is_valid_2x2(x - 1, y - 1) else 0

            if y == m - 1:
                return count_ways_recursive(x + 1, 0)

            if matrix[x][y] != -1:
                return count_ways_recursive(x, y + 1)

            ways = 0
            for value in [0, 1]:
                matrix[x][y] = value
                if is_valid_2x2(x, y):
                    ways = (ways + count_ways_recursive(x, y + 1)) % MOD
                matrix[x][y] = -1

            return ways

        return count_ways_recursive(0, 0)

    matrix = [[-1] * m for _ in range(n)]
    results = []

    for x, y, t in queries:
        if t == -1:
            matrix[x][y] = -1
        else:
            matrix[x][y] = t

        result = count_ways(n, m, matrix)
        results.append(result)

