def count_valid_numbers(s):
    n = len(s)
    count = 0

    # Helper function to check if a number is divisible by 25
    def is_divisible_by_25(num):
        return num % 25 == 0

    # Generate all possible numbers by replacing '_' and 'X'
    def generate_numbers(index, current, x_value):
        nonlocal count
        if index == n:
            # Remove leading zeros
            current = current.lstrip('0')
            if current and is_divisible_by_25(int(current)):
                count += 1
            return

        if s[index] == '_':
            for digit in '0123456789':
                generate_numbers(index + 1, current + digit, x_value)
        elif s[index] == 'X':
            if x_value is None:
                for digit in '0123456789':
                    generate_numbers(index + 1, current + digit, digit)
            else:
                generate_numbers(index + 1, current + x_value, x_value)
        else:
            generate_numbers(index + 1, current + s[index], x_value)

    generate_numbers(0, '', None)
    print(count)

