    def is_valid_tick(i, j, d):
        if i - d < 0 or j - d < 0 or i + d >= n or j + d >= m:
            return False
        for h in range(d + 1):
            if field[i - h][j - h] != '*' or field[i - h][j + h] != '*':
                return False
        return True

    for i in range(n):
        for j in range(m):
            if field[i][j] == '*':
                found = False
                for d in range(k, min(n, m) + 1):
                    if is_valid_tick(i, j, d):
                        found = True
                        break
                if not found:
                    return "NO"
    return "YES"

