def min_operations_to_portal(n, m, grid):
    def is_portal(a, b, x, y):
        if a < 5 or b < 4:
            return float('inf')
        operations = 0
        for i in range(1, a-1):
            if grid[x+i][y] != '1' or grid[x+i][y+b-1] != '1':
                operations += 1
        for j in range(1, b-1):
            if grid[x][y+j] != '1' or grid[x+a-1][y+j] != '1':
                operations += 1
        for i in range(1, a-1):
            for j in range(1, b-1):
                if grid[x+i][y+j] != '0':
                    operations += 1
        return operations

    min_operations = float('inf')
    for x in range(n-4):
        for y in range(m-3):
            for a in range(5, n-x+1):
                for b in range(4, m-y+1):
                    min_operations = min(min_operations, is_portal(a, b, x, y))
    return min_operations

