def solve(a, b, c):
    total_duration = a + 2 * b + 3 * c
    half_total = total_duration // 2

    # Initialize a DP array to keep track of possible sums
    dp = [False] * (half_total + 1)
    dp[0] = True

    # Try to include each type of song
    for i in range(a):
        for j in range(half_total, -1, -1):
            if dp[j]:
                dp[j + 1] = True
    for i in range(b):
        for j in range(half_total, -1, -1):
            if dp[j]:
                dp[j + 2] = True
    for i in range(c):
        for j in range(half_total, -1, -1):
            if dp[j]:
                dp[j + 3] = True

    # Find the closest possible sum to half_total
    for i in range(half_total, -1, -1):
        if dp[i]:
            return total_duration - 2 * i

