import random

def find(parent, i):
    if parent[i] == i:
        return i
    parent[i] = find(parent, parent[i])
    return parent[i]

def union(parent, rank, x, y):
    rootX = find(parent, x)
    rootY = find(parent, y)
    if rootX != rootY:
        if rank[rootX] > rank[rootY]:
            parent[rootY] = rootX
        elif rank[rootX] < rank[rootY]:
            parent[rootX] = rootY
        else:
            parent[rootY] = rootX
            rank[rootX] += 1

def generate_tree(n, restrictions):
    parent = list(range(n + 1))
    rank = [0] * (n + 1)
    edges = []

    # Generate a random tree
    for i in range(2, n + 1):
        j = random.randint(1, i - 1)
        edges.append((j, i))
        union(parent, rank, j, i)

    # Check and adjust the tree to satisfy restrictions
    for a, b, c in restrictions:
        while find(parent, a) == find(parent, b) == find(parent, c):
            # Find a random node not in the same set as b
            for i in range(1, n + 1):
                if i != a and i != b and i != c and find(parent, i) != find(parent, b):
                    # Remove the edge connected to b and add a new edge
                    for u, v in edges:
                        if b in (u, v):
                            edges.remove((u, v))
                            edges.append((b, i))
                            union(parent, rank, b, i)
                            break
                    break

    return edges

