def is_determinable(grid, n, m, x1, x2):
    # Create a grid to mark exitable cells
    exitable = [[False] * m for _ in range(n)]

    # Mark all cells in the first row and first column as exitable
    for i in range(n):
        if grid[i][0] == '.':
            exitable[i][0] = True
    for j in range(m):
        if grid[0][j] == '.':
            exitable[0][j] = True

    # Propagate exitability from the first row and first column
    for i in range(1, n):
        for j in range(1, m):
            if grid[i][j] == '.' and (exitable[i-1][j] or exitable[i][j-1]):
                exitable[i][j] = True

    # Check if the subgrid is determinable
    for i in range(n):
        for j in range(x1-1, x2):
            if grid[i][j] == '.' and not exitable[i][j]:
                return False
            if grid[i][j] == 'X' and exitable[i][j]:
                return False
    return True

