from collections import defaultdict

def find_clique_or_independent_set(n, edges):
    # Build the graph
    graph = defaultdict(set)
    for u, v in edges:
        graph[u].add(v)
        graph[v].add(u)

    # Check for a clique of size 5
    for i in range(1, n-3):
        for j in range(i+1, n-2):
            if j in graph[i]:
                for k in range(j+1, n-1):
                    if k in graph[i] and k in graph[j]:
                        for l in range(k+1, n):
                            if l in graph[i] and l in graph[j] and l in graph[k]:
                                for m in range(l+1, n+1):
                                    if m in graph[i] and m in graph[j] and m in graph[k] and m in graph[l]:
                                        return [i, j, k, l, m]

    # Check for an independent set of size 5
    for i in range(1, n-3):
        for j in range(i+1, n-2):
            if j not in graph[i]:
                for k in range(j+1, n-1):
                    if k not in graph[i] and k not in graph[j]:
                        for l in range(k+1, n):
                            if l not in graph[i] and l not in graph[j] and l not in graph[k]:
                                for m in range(l+1, n+1):
                                    if m not in graph[i] and m not in graph[j] and m not in graph[k] and m not in graph[l]:
                                        return [i, j, k, l, m]

    return [-1]

