from collections import deque

def get_neighbors(x, y, n, m):
    neighbors = []
    if x > 0:
        neighbors.append((x-1, y))
    if x < n-1:
        neighbors.append((x+1, y))
    if y > 0:
        neighbors.append((x, y-1))
    if y < m-1:
        neighbors.append((x, y+1))
    return neighbors

def bfs(x, y, grid, visited, n, m):
    queue = deque([(x, y)])
    visited[x][y] = True
    size = 0
    while queue:
        cx, cy = queue.popleft()
        size += 1
        for nx, ny in get_neighbors(cx, cy, n, m):
            if not visited[nx][ny] and (grid[cx][cy] & (1 << (3 - (nx > cx) + 2 * (ny > cy)))) == 0:
                visited[nx][ny] = True
                queue.append((nx, ny))
    return size

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    m = int(data[1])
    grid = []
    index = 2
    for i in range(n):
        row = list(map(int, data[index:index + m]))
        grid.append(row)
        index += m

    visited = [[False] * m for _ in range(n)]
    room_sizes = []

    for i in range(n):
        for j in range(m):
            if not visited[i][j]:
                room_size = bfs(i, j, grid, visited, n, m)
                room_sizes.append(room_size)

    room_sizes.sort(reverse=True)
    print(' '.join(map(str, room_sizes)))

