def min_steps_to_equal_ab_ba(s):
    ab_count = s.count("ab")
    ba_count = s.count("ba")

    if ab_count == ba_count:
        return s

    # If ab_count > ba_count, we need to reduce ab_count or increase ba_count
    # If ab_count < ba_count, we need to reduce ba_count or increase ab_count

    # Strategy: Change characters to balance the counts
    # If ab_count > ba_count, change 'b' to 'a' to reduce ab_count
    # If ab_count < ba_count, change 'a' to 'b' to reduce ba_count

    if ab_count > ba_count:
        # Change 'b' to 'a' to reduce ab_count
        s_list = list(s)
        for i in range(len(s_list)):
            if s_list[i] == 'b':
                s_list[i] = 'a'
                ab_count -= 1
                if ab_count == ba_count:
                    break
        return ''.join(s_list)
    else:
        # Change 'a' to 'b' to reduce ba_count
        s_list = list(s)
        for i in range(len(s_list)):
            if s_list[i] == 'a':
                s_list[i] = 'b'
                ba_count -= 1
                if ab_count == ba_count:
                    break
        return ''.join(s_list)

