import sys

def solve(x0, n):
    if n == 0:
        return x0
    if n == 1:
        return x0 - 1
    if n == 2:
        return x0 + 1

    # Determine the parity of n
    if n % 2 == 0:
        # Even n
        return x0 + (n // 2) * (n + 1)
    else:
        # Odd n
        return x0 - ((n + 1) // 2) * (n + 1)

