def solve():
    import sys
    import heapq

    def read_int():
        return int(sys.stdin.readline())

    def read_ints():
        return list(map(int, sys.stdin.readline().split()))

    t = read_int()
    results = []

    for _ in range(t):
        n = read_int()
        if n == 1:
            a = read_ints()
            results.append(a[0])
            continue

        a = read_ints()
        heapq.heapify(a)
        min_value = 0

        while len(a) > 1:
            m = heapq.heappop(a)
            min_value = max(min_value, m)
            for i in range(len(a)):
                a[i] -= m
            heapq.heapify(a)

        results.append(max(min_value, a[0]))

    for result in results:
        print(result)

