MOD = 998244353

def count_valid_colorings(n, dominoes):
    # Count the number of dominoes with each possible left and right color combination
    left_counts = {'BW': 0, 'WB': 0, 'BB': 0, 'WW': 0}
    right_counts = {'BW': 0, 'WB': 0, 'BB': 0, 'WW': 0}
    uncolored_left = 0
    uncolored_right = 0

    for domino in dominoes:
        left, right = domino
        if left == '?':
            uncolored_left += 1
        if right == '?':
            uncolored_right += 1
        if left != '?' and right != '?':
            left_counts[left + right] += 1
        elif left != '?':
            left_counts[left + '?'] += 1
        elif right != '?':
            left_counts['?' + right] += 1
        else:
            left_counts['??'] += 1

    # Calculate the number of valid colorings
    total_ways = 1
    for i in range(n):
        if dominoes[i] == '??':
            total_ways *= 2
            total_ways %= MOD

    # Adjust for fixed dominoes
    if uncolored_left > 0:
        total_ways *= (2 ** uncolored_left)
        total_ways %= MOD
    if uncolored_right > 0:
        total_ways *= (2 ** uncolored_right)
        total_ways %= MOD

    return total_ways

