def dfs(node, parent, tree, sizes):
    size = 1
    for neighbor in tree[node]:
        if neighbor != parent:
            sizes[node] += dfs(neighbor, node, tree, sizes)
            size += sizes[neighbor]
    return size

def solve(n, k, edges):
    tree = defaultdict(list)
    for u, v in edges:
        tree[u].append(v)
        tree[v].append(u)

    sizes = [1] * (n + 1)
    dfs(1, -1, tree, sizes)

    def get_score(node, parent, k_left):
        if k_left == 0:
            return sizes[node]
        if k_left < 0:
            return float('-inf')

        max_score = float('-inf')
        for neighbor in tree[node]:
            if neighbor != parent:
                score = get_score(neighbor, node, k_left - 1)
                if score != float('-inf'):
                    max_score = max(max_score, score)

        if max_score == float('-inf'):
            return sizes[node]

        return sizes[node] - max_score

    max_score = float('-inf')
    for node in range(1, n + 1):
        score = get_score(node, -1, k - 1)
        if score != float('-inf'):
            max_score = max(max_score, score)

    return max_score

