def is_subsequence(s, t):
    it = iter(s)
    return all(char in it for char in t)

def find_lexicographically_smallest_permutation(S, T):
    S = list(S)
    S.sort()
    n = len(S)

    # Try to find the smallest permutation that does not contain T as a subsequence
    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                candidate = S[:]
                candidate[i], candidate[j], candidate[k] = candidate[j], candidate[k], candidate[i]
                if not is_subsequence(candidate, T):
                    return ''.join(candidate)

    # If no such permutation is found, return the sorted S
    return ''.join(S)

