import sys

def reconstruct_word(bigrams):
    n = len(bigrams) + 2
    word = ['a'] * n

    for i in range(n - 1):
        if i < n - 2:
            word[i + 1] = bigrams[i][1]
        if word[i] + word[i + 1] != bigrams[i]:
            word[i] = 'b' if word[i] == 'a' else 'a'

    return ''.join(word)

