import sys

def find_xth_lexicographical(n, k, x, s):
    result = []
    asterisk_count = s.count('*')
    total_combinations = 1
    for i in range(asterisk_count):
        total_combinations *= (k + 1)

    if x > total_combinations:
        return ""

    x -= 1
    for char in s:
        if char == '*':
            for b_count in range(k, -1, -1):
                if x >= (k + 1) ** (asterisk_count - 1):
                    x -= (k + 1) ** (asterisk_count - 1)
                else:
                    result.append('b' * b_count)
                    asterisk_count -= 1
                    break
        else:
            result.append('a')

    return ''.join(result)

