def solve_case(n, p):
    a = [0] * n
    visited = [False] * n
    stack = []

    def dfs(u):
        visited[u] = True
        stack.append(u)
        for v in range(u + 1, n):
            if p[v] == p[u]:
                continue
            if visited[v]:
                if a[v] == a[u]:
                    return False
            else:
                a[v] = -a[u]
                if not dfs(v):
                    return False
        stack.pop()
        return True

    for i in range(n):
        if not visited[i]:
            a[i] = 1
            if not dfs(i):
                return "NO", []

    return "YES", a

