def factorial(n, mod):
    result = 1
    for i in range(2, n + 1):
        result = result * i % mod
    return result

def inv_factorial(n, mod):
    return pow(factorial(n, mod), mod - 2, mod)

def nCr(n, r, mod):
    if r > n:
        return 0
    return factorial(n, mod) * inv_factorial(r, mod) % mod * inv_factorial(n - r, mod) % mod

def count_ways(n, k, s):
    if k == 0:
        return 1

    count_ones = s.count('1')
    if count_ones < k:
        return 0

    total_ways = 0
    for i in range(n - k + 1):
        ones_in_substring = s[i:i + k].count('1')
        zeros_in_substring = k - ones_in_substring
        total_ways = (total_ways + nCr(k, ones_in_substring, MOD)) % MOD

    return total_ways

