def is_quadratic(num):
    prime_factors = {}
    temp = num
    for i in range(2, int(math.sqrt(num)) + 1):
        while temp % i == 0:
            if i in prime_factors:
                prime_factors[i] += 1
            else:
                prime_factors[i] = 1
            temp //= i
    if temp > 1:
        if temp in prime_factors:
            prime_factors[temp] += 1
        else:
            prime_factors[temp] = 1
    for count in prime_factors.values():
        if count % 2 != 0:
            return False
    return True

def find_quadratic_subset(n):
    subset = []
    for i in range(1, n + 1):
        if is_quadratic(i):
            subset.append(i)
    return subset

