def max_square_brackets(sequence):
    n = len(sequence)
    max_count = 0
    best_sequence = ""

    # Stack to keep track of open brackets
    stack = []
    # Dictionary to keep track of the number of '[' in the current valid sequence
    square_count = {}

    for i, char in enumerate(sequence):
        if char in "([":
            stack.append((char, i))
            if char == '[':
                square_count[i] = square_count.get(i, 0) + 1
        else:
            if stack:
                last_char, last_index = stack.pop()
                if (char == ')' and last_char == '(') or (char == ']' and last_char == '['):
                    if last_char == '[':
                        square_count[last_index] = square_count.get(last_index, 0) + square_count.get(i, 0)
                    if stack:
                        square_count[stack[-1][1]] = square_count.get(stack[-1][1], 0) + square_count.get(last_index, 0)
                    else:
                        current_count = square_count.get(last_index, 0)
                        if current_count > max_count:
                            max_count = current_count
                            best_sequence = sequence[last_index:i+1]
                else:
                    stack.clear()
                    square_count.clear()
            else:
                stack.clear()
                square_count.clear()

    print(max_count)
    print(best_sequence)

