def interpret_program(sequence):
    cp = 0
    dp = 1
    counts = [0] * 10
    while 0 <= cp < len(sequence):
        if sequence[cp].isdigit():
            digit = int(sequence[cp])
            counts[digit] += 1
            if digit == 0:
                sequence = sequence[:cp] + sequence[cp+1:]
            else:
                sequence = sequence[:cp] + str(digit - 1) + sequence[cp+1:]
            cp += dp
        else:
            dp = -1 if sequence[cp] == '<' else 1
            cp += dp
            if 0 <= cp < len(sequence) and sequence[cp] in '<>':
                sequence = sequence[:cp] + sequence[cp+1:]
    return counts

