def min_boxes(k, a, b, v):
    def can_fit(nuts, sections, v):
        return nuts <= sections * v

    def min_boxes_needed(k, a, b, v):
        min_boxes = 0
        remaining_nuts = a
        for divisors in range(b, -1, -1):
            sections = divisors + 1
            if sections > k:
                continue
            if can_fit(remaining_nuts, sections, v):
                min_boxes += 1
                remaining_nuts -= sections * v
                if remaining_nuts <= 0:
                    break
        return min_boxes if remaining_nuts <= 0 else float('inf')

    result = float('inf')
    for i in range(b + 1):
        result = min(result, min_boxes_needed(k, a, i, v))

    return result if result != float('inf') else -1

