def parse_golorp_name(name):
    # Remove the prefix and suffix
    name = name[2:-1]
    # Split by '>' to get the parts
    parts = name.split('>')
    # The first part is the input pattern
    input_pattern = parts[0]
    # The rest are the output patterns
    output_patterns = parts[1:]
    return input_pattern, output_patterns

def find_lexicographically_smallest_sequence(input_pattern, output_patterns):
    # Initialize the sequence with the minimum possible values
    sequence = [0] * len(input_pattern)
    # Try to find a valid sequence
    while True:
        # Check if the current sequence satisfies all output patterns
        valid = True
        for output_pattern in output_patterns:
            # Replace '?' with the current sequence values
            current_output = output_pattern
            for i, char in enumerate(output_pattern):
                if char == '?':
                    current_output = current_output[:i] + str(sequence[i]) + current_output[i+1:]
            # Check if the current output matches the input pattern
            if current_output != input_pattern:
                valid = False
                break
        if valid:
            return ''.join(map(str, sequence))
        # Increment the sequence lexicographically
        for i in range(len(sequence) - 1, -1, -1):
            if sequence[i] < 9:
                sequence[i] += 1
                break
            else:
                sequence[i] = 0
        else:
            return "false"

