def min_compressed_length(s):
    n = len(s)
    dp = [0] * (n + 1)

    for i in range(1, n + 1):
        dp[i] = dp[i - 1] + 1
        for j in range(i - 1, -1, -1):
            if s[j:i] == s[j:i - (i - j)]:
                length = len(str(i - j))
                dp[i] = min(dp[i], dp[j] + length + (1 if length > 0 else 0))

    return dp[n]

