def find_operations(n, s, t):
    if s == t:
        return 0, []

    # Try all possible shifts
    for shift in range(1, n + 1):
        new_s = s[-shift:] + s[:-shift]
        if new_s == t:
            return 1, [shift]

    # Try combinations of shifts
    for i in range(1, 6101):
        for shift1 in range(1, n + 1):
            new_s = s[-shift1:] + s[:-shift1]
            for j in range(1, 6101 - i):
                for shift2 in range(1, n + 1):
                    new_s = new_s[-shift2:] + new_s[:-shift2]
                    if new_s == t:
                        return i + j, [shift1] + [shift2]

    return -1, []

