    def can_reach_roof(walls):
        dp = [float('inf')] * (n + 1)
        dp[0] = 0
        for i in range(n):
            if dp[i] == float('inf'):
                continue
            if walls[i] == 0:
                dp[i + 1] = min(dp[i + 1], dp[i] + 1)
            elif walls[i] == 1:
                dp[i + 2] = min(dp[i + 2], dp[i] + 1)
            elif walls[i] == 2:
                j = i
                while j < n and walls[j] == 2:
                    j += 1
                if j < n and walls[j] == 1:
                    dp[j + 1] = min(dp[j + 1], dp[i] + 1)
        return dp[n] if dp[n] != float('inf') else float('inf')

    jumps_a = can_reach_roof(a)
    jumps_b = can_reach_roof(b)

    if jumps_a == float('inf') and jumps_b == float('inf'):
        return "NA"
    else:
        return min(jumps_a, jumps_b)

