def sieve_of_eratosthenes(max_num):
    is_prime = [True] * (max_num + 1)
    p = 2
    while (p * p <= max_num):
        if (is_prime[p] == True):
            for i in range(p * p, max_num + 1, p):
                is_prime[i] = False
        p += 1
    prime_numbers = [p for p in range(2, max_num + 1) if is_prime[p]]
    return prime_numbers

def prime_factors(n, primes):
    factors = set()
    for p in primes:
        if p * p > n:
            break
        if n % p == 0:
            factors.add(p)
            while n % p == 0:
                n //= p
    if n > 1:
        factors.add(n)
    return factors

def is_coprime_sortable(N, a):
    primes = sieve_of_eratosthenes(10**5)
    prime_factor_map = defaultdict(set)

    for i in range(N):
        prime_factor_map[i] = prime_factors(a[i], primes)

    for i in range(N):
        if a[i] != min(a[i:]):
            found = False
            for j in range(i + 1, N):
                if a[j] == min(a[i:]) and prime_factor_map[i] & prime_factor_map[j]:
                    a[i], a[j] = a[j], a[i]
                    found = True
                    break
            if not found:
                return 0
    return 1

