def get_neighbors(N, i, j):
    neighbors = []
    if i > 0:
        neighbors.append((i - 1, j))
    if i < N - 1:
        neighbors.append((i + 1, j))
    if j > 0:
        neighbors.append((i, j - 1))
    if j < N - i - 1:
        neighbors.append((i, j + 1))
    return neighbors

def find_groups(board, N):
    groups = {}
    visited = set()
    for i in range(N):
        for j in range(N - i):
            if board[i][j] != 0 and (i, j) not in visited:
                group = []
                stack = [(i, j)]
                while stack:
                    x, y = stack.pop()
                    if (x, y) in visited:
                        continue
                    visited.add((x, y))
                    group.append((x, y))
                    for nx, ny in get_neighbors(N, x, y):
                        if board[nx][ny] == board[i][j] and (nx, ny) not in visited:
                            stack.append((nx, ny))
                groups[(i, j)] = group
    return groups

def can_remove_group(group, board):
    for x, y in group:
        for nx, ny in get_neighbors(len(board), x, y):
            if board[nx][ny] == 0:
                return True
    return False

def calculate_points(board, N, C, i, j):
    original_board = [row[:] for row in board]
    board[i][j] = C
    groups = find_groups(board, N)
    gain = 0
    lose = 0
    for group in groups.values():
        if can_remove_group(group, board):
            for x, y in group:
                if board[x][y] == C:
                    lose += 1
                else:
                    gain += 1
    return gain - lose

def solve(N, C, board):
    max_points = -float('inf')
    for i in range(N):
        for j in range(N - i):
            if board[i][j] == 0:
                points = calculate_points(board, N, C, i, j)
                max_points = max(max_points, points)
    return max_points

