MOD = 1000000007

def find(parent, i):
    if parent[i] == i:
        return i
    parent[i] = find(parent, parent[i])
    return parent[i]

def union(parent, rank, x, y):
    rootX = find(parent, x)
    rootY = find(parent, y)
    if rootX != rootY:
        if rank[rootX] > rank[rootY]:
            parent[rootY] = rootX
        elif rank[rootX] < rank[rootY]:
            parent[rootX] = rootY
        else:
            parent[rootY] = rootX
            rank[rootX] += 1

def count_numbers(N, M, rules):
    parent = list(range(N + 1))
    rank = [0] * (N + 1)

    for S, D in rules:
        union(parent, rank, S, D)

    unique_roots = set()
    for i in range(1, N + 1):
        unique_roots.add(find(parent, i))

    return pow(2, len(unique_roots), MOD)

