def recover_audio_signal(N, signal):
    broken_indices = [i for i in range(N) if signal[i] == 'x']
    if len(broken_indices) == 0:
        return "none"

    possible_values = set()

    for value in range(-10**9, 10**9 + 1):
        valid = True
        for i in broken_indices:
            if i % 2 == 0:  # odd-indexed (1-based), even-indexed (0-based)
                if (i > 0 and signal[i-1] >= value) or (i < N-1 and signal[i+1] >= value):
                    valid = False
                    break
            else:  # even-indexed (1-based), odd-indexed (0-based)
                if (i > 0 and signal[i-1] <= value) or (i < N-1 and signal[i+1] <= value):
                    valid = False
                    break
        if valid:
            possible_values.add(value)

    if len(possible_values) == 0:
        return "none"
    elif len(possible_values) == 1:
        return str(possible_values.pop())
    else:
        return "ambiguous"

