def calculate_possible_indices(N, S, T):
    def compare(s1, s2):
        for c1, c2 in zip(s1, s2):
            if c1 != c2:
                return c1 < c2
        return len(s1) < len(s2)

    def count_less_than(T, S):
        count = 0
        for s in S:
            if compare(s, T):
                count += 1
        return count

    def count_equal(T, S):
        count = 0
        for s in S:
            if s == T:
                count += 1
        return count

    less_than_count = count_less_than(T, S)
    equal_count = count_equal(T, S)
    possible_indices = list(range(less_than_count + 1, less_than_count + equal_count + 1))
    return possible_indices

