def search(arr, n):
    low, high = 0, n - 1
    while low <= high:
        mid = (low + high) // 2
        if (mid == 0 or arr[mid - 1] != arr[mid]) and (mid == n - 1 or arr[mid] != arr[mid + 1]):
            return arr[mid]
        if mid % 2 == 0:
            if arr[mid] == arr[mid + 1]:
                low = mid + 2
            else:
                high = mid - 2
        else:
            if arr[mid] == arr[mid + 1]:
                high = mid - 1
            else:
                low = mid + 1
    return -1

