def max_sum_increasing_subseq(arr, n, i, k):
    if k <= i:
        return 0
    dp = [0] * n
    dp[i] = arr[i]
    for j in range(i + 1, n):
        if arr[j] > arr[i]:
            dp[j] = max(dp[j], dp[i] + arr[j])
    max_sum = 0
    for j in range(i + 1, k):
        max_sum = max(max_sum, dp[j])
    return max_sum

