import heapq

def k_smallest_pairs(nums1, nums2, k):
    heap = []
    for x in nums1:
        for y in nums2:
            if len(heap) < k:
                heapq.heappush(heap, (-(x + y), [x, y]))
            else:
                if -(x + y) > heap[0][0]:
                    heapq.heappop(heap)
                    heapq.heappush(heap, (-(x + y), [x, y]))
    return [pair for _, pair in heap]

