def get_maxgold(gold_matrix, n, m):
    dp = [[0] * m for _ in range(n)]
    for col in range(m - 1, -1, -1):
        for row in range(n):
            if col == m - 1:
                dp[row][col] = gold_matrix[row][col]
            elif row == 0:
                dp[row][col] = gold_matrix[row][col] + max(dp[row][col + 1], dp[row + 1][col + 1])
            elif row == n - 1:
                dp[row][col] = gold_matrix[row][col] + max(dp[row][col + 1], dp[row - 1][col + 1])
            else:
                dp[row][col] = gold_matrix[row][col] + max(dp[row][col + 1], dp[row + 1][col + 1], dp[row - 1][col + 1])
    return max(dp[i][0] for i in range(n))

