def count_Squares(m, n):
    if m < n:
        m, n = n, m
    dp = [[0] * n for _ in range(m)]
    count = 0
    for i in range(m):
        for j in range(n):
            if i == 0 or j == 0:
                dp[i][j] = 1
            else:
                dp[i][j] = min(dp[i-1][j], dp[i][j-1], dp[i-1][j-1]) + 1
            count += dp[i][j]
    return count

