def find_permutations(a):
    n = len(a)
    for l1 in range(1, n):
        p1 = a[:l1]
        p2 = a[l1:]
        if sorted(p1) == list(range(1, l1 + 1)) and sorted(p2) == list(range(1, n - l1 + 1)):
