def min_grid_area(s):
    x, y = 0, 0
    min_x, max_x = 0, 0
    min_y, max_y = 0, 0

    for cmd in s:
        if cmd == 'W':
            y += 1
        elif cmd == 'S':
            y -= 1
        elif cmd == 'A':
            x -= 1
        elif cmd == 'D':
            x += 1
        min_x = min(min_x, x)
        max_x = max(max_x, x)
        min_y = min(min_y, y)
        max_y = max(max_y, y)

    width = max_x - min_x + 1
    height = max_y - min_y + 1
    area = width * height

    # Check inserting one of the extra letters
    for insert in 'WASD':
        x, y = 0, 0
        min_x, max_x = 0, 0
        min_y, max_y = 0, 0
        for cmd in s + insert:
            if cmd == 'W':
                y += 1
            elif cmd == 'S':
                y -= 1
            elif cmd == 'A':
                x -= 1
            elif cmd == 'D':
                x += 1
            min_x = min(min_x, x)
            max_x = max(max_x, x)
            min_y = min(min_y, y)
            max_y = max(max_y, y)
        width = max_x - min_x + 1
        height = max_y - min_y + 1
        area = min(area, width * height)

    return area

