            continue
        if a[i] == 0:
            return "NO"
        if diff[i] % 2 != 0:
            return "NO"
        j = i + 1
        while j < n and diff[j] != 0:
            j += 1
        if j - i == 1 and diff[i] != 0:
            return "NO"
        if j - i > 1:
            if diff[i] != diff[i - 1]:
