from collections import defaultdict

def min_subscriptions(n, k, d, shows):
    show_count = defaultdict(int)
    min_subs = float('inf')
    unique_shows = 0

    for i in range(n):
        if i >= d:
            if show_count[shows[i - d]] == 1:
                unique_shows -= 1
            show_count[shows[i - d]] -= 1

        if show_count[shows[i]] == 0:
            unique_shows += 1
        show_count[shows[i]] += 1

        if i >= d - 1:
            min_subs = min(min_subs, unique_shows)

    return min_subs

