def find_kth_good_permutation(n, k):
    if k > (n // 2) * (n // 2 + n % 2):
        return -1
    perm = []
    used = [False] * (n + 1)
    for i in range(n):
        if k <= (n // 2) * (n // 2 + n % 2):
            for j in range(1, n + 1):
                if not used[j]:
                    if i % 2 == 0 or (i % 2 == 1 and j > n // 2):
                        perm.append(j)
                        used[j] = True
                        break
                    else:
                        k -= (n // 2) * (n // 2 + n % 2)
        else:
            k -= (n // 2) * (n // 2 + n % 2)
            for j in range(n, 0, -1):
                if not used[j]:
                    if i % 2 == 1 or (i % 2 == 0 and j <= n // 2):
                        perm.append(j)
                        used[j] = True
                        break
    return perm

def main():
    t = int(input())
    for _ in range(t):
        n, k = map(int, input().split())
        result = find_kth_good_permutation(n, k)
        if result == -1:
