def can_have_no_winner(n, k, d1, d2):
    if k == 0:
        return "yes" if n % 3 == 0 and 2 * max(d1, d2) <= n else "no"
    if k == n:
        return "yes" if n % 3 == 0 and 2 * max(d1, d2) <= n else "no"

    # Try all possible ways to distribute the remaining games
    for w1 in range(4):
        for w2 in range(4):
            for w3 in range(4):
                wins = [w1, w2, w3]
                if sum(wins) != k:
                    continue
                if abs(wins[0] - wins[1]) != d1 or abs(wins[1] - wins[2]) != d2:
                    continue
                total_wins = wins[0] + wins[1] + wins[2] + (n - k)
                if total_wins % 3 == 0 and 2 * max(d1, d2) <= total_wins:
                    return "yes"
    return "no"

