def min_cost_to_break_chocolate(n, m, k):
    if k == n * m:
        return 0
    min_cost = float('inf')
    for horizontal_cut in range(1, n):
        for vertical_cut in range(1, m):
            cost = (n - horizontal_cut) ** 2 + (m - vertical_cut) ** 2
            if horizontal_cut * m + vertical_cut * n == k:
                min_cost = min(min_cost, cost)
            for horizontal_pieces in range(1, horizontal_cut):
                for vertical_pieces in range(1, vertical_cut):
                    cost = (horizontal_pieces ** 2) + ((horizontal_cut - horizontal_pieces) ** 2) + \
                           (vertical_pieces ** 2) + ((vertical_cut - vertical_pieces) ** 2)
                    if horizontal_pieces * m + vertical_pieces * n == k:
                        min_cost = min(min_cost, cost)
    return min_cost

