def min_replacements_to_k_complete(n, k, s):
    replacements = 0
    for i in range(k // 2):
        freq = {}
        # Count the frequency of characters in the positions [i, n - i - 1]
        for j in range(i, n, k):
            freq[s[j]] = freq.get(s[j], 0) + 1
            # Also count the corresponding position in the other half
            freq[s[n - i - 1]] = freq.get(s[n - i - 1], 0) + 1
        # Find the character that needs the least replacements
        max_freq = max(freq.values(), default=0)
        replacements += len(freq) - max_freq
    return replacements

