    p = [0] * n
    max_val = 0
    for i in range(n):
        if q[i] > max_val:
            p[i] = q[i]
            max_val = q[i]
        else:
            if p[i] == 0:
                for j in range(n):
                    if p[j] == 0 and q[i] < j + 1:
                        p[j] = j + 1
                        break
            else:
