def max_teams(c, m, x):
    teams = 0
    while c > 0 and m > 0 and x > 0:
        if c <= m:
            if x >= c:
                teams += c
                m -= c
                x -= c
            else:
                teams += x
                m -= x
                c -= x
        else:
            if x >= m:
                teams += m
                c -= m
                x -= m
            else:
                teams += x
                c -= x
                m -= x
    return teams

