def is_compressible(block, k):
    target = block[0][0]
    for i in range(k):
        for j in range(k):
            if block[i][j] != target:
                return False
    return True

def toggle_block(block, k):
    count = 0
    for i in range(k):
        for j in range(k):
            if block[i][j] == '0':
                block[i][j] = '1'
                count += 1
            else:
                block[i][j] = '0'
                count += 1
    return count

def main():
    n, m = read_ints()
    image = read_matrix(n, m)

    min_toggles = float('inf')
    for k in range(2, min(n, m) + 1):
        if n % k == 0 and m % k == 0:
            padded_image = [['0'] * m for _ in range(n)]
            for i in range(n):
                for j in range(m):
                    padded_image[i][j] = image[i][j]

            blocks = []
            for i in range(0, n, k):
                for j in range(0, m, k):
                    block = [row[j:j+k] for row in padded_image[i:i+k]]
                    blocks.append(block)

            toggles = 0
            for block in blocks:
                if not is_compressible(block, k):
                    toggles += toggle_block(block, k)

            min_toggles = min(min_toggles, toggles)

    print(min_toggles)

