        edges_with_time = [(u, v, a if c == a else b) for u, v, c in edges]
        edges_with_time.sort(key=lambda x: x[2])
        mst_edges = kruskal_mst(edges_with_time, n)
        result = [0] * n
        for u, v, w in mst_edges:
            if find(parent, u - 1) != find(parent, v - 1):
                union(parent, rank, u - 1, v - 1)
                result[u - 1] = w
                result[v - 1] = w
        for j in range(n):
            if find(parent, 0) != find(parent, j):
                result[j] = float('inf')
        print(result[i], end=' ')

