def dijkstra(start, end, n, d, coords, a):
    dist = [float('inf')] * n
    dist[start] = 0
    pq = [(0, start)]

    while pq:
        current_dist, u = heapq.heappop(pq)
        if u == end:
            break
        for v in range(n):
            if v != u:
                dist_uv = distance(u, v)
                if dist_uv <= d:
                    new_dist = current_dist + dist_uv * d + a[u - 1]
                    if new_dist < dist[v]:
                        dist[v] = new_dist
                        heapq.heappush(pq, (new_dist, v))
    return dist[end]

