import sys
from collections import defaultdict

def parse_input(n, m, lines):
    variables = {}
    for line in lines:
        parts = line.split()
        var_name = parts[0]
        if len(parts) == 3:
            value = parts[2]
            variables[var_name] = value
        else:
            op1 = parts[2]
            op_type = parts[3]
            op2 = parts[4]
            if op1.isdigit():
                op1 = int(op1, 2)
            if op2.isdigit():
                op2 = int(op2, 2)
            variables[var_name] = (op_type, op1, op2)
    return variables

def evaluate(variables, var_name, cache):
    if var_name in cache:
        return cache[var_name]
    op_type, op1, op2 = variables[var_name]
    if isinstance(op1, int) and isinstance(op2, int):
        result = eval(f"{op1} {op_type} {op2}")
        cache[var_name] = result
        return result
    else:
        val1 = evaluate(variables, op1, cache) if isinstance(op1, str) else op1
        val2 = evaluate(variables, op2, cache) if isinstance(op2, str) else op2
        result = eval(f"{val1} {op_type} {val2}")
        cache[var_name] = result
        return result

def main():
    n, m = map(int, sys.stdin.readline().split())
    lines = [sys.stdin.readline().strip() for _ in range(n)]
    variables = parse_input(n, m, lines)
    cache = {}
    min_values = []
    max_values = []
    for var_name in variables:
        if var_name == '?':
            continue
        val = evaluate(variables, var_name, cache)
        min_values.append(val)
        max_values.append(val)
    min_values.sort()
    max_values.sort()
    print(bin(min_values[0])[2:].zfill(m))
    print(bin(max_values[-1])[2:].zfill(m))

