def mod_pow(x, n, mod):
    result = 1
    while n > 0:
        if n & 1:
            result = result * x % mod
        x = x * x % mod
        n >>= 1
    return result

def mod_inv(x, mod):
    return mod_pow(x, mod - 2, mod)

def mod_comb(n, k, mod):
    numerator = 1
    denominator = 1
    for i in range(k):
        numerator = numerator * (n - i) % mod
        denominator = denominator * (i + 1) % mod
    return numerator * mod_inv(denominator, mod) % mod

