    dp = [[0] * n for _ in range(n)]
    count = 0

    for i in range(n):
        if s[i] == '(':
            dp[i][i] = 1
        elif s[i] == ')':
            dp[i][i] = -1
        elif s[i] == '?':
            dp[i][i] = 0

    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            if s[i] == '(' and s[j] == ')' or s[i] == '?' and s[j] == '?' or s[i] == '?' and s[j] == ')':
                if dp[i + 1][j - 1] == length - 2:
                    dp[i][j] = dp[i + 1][j - 1] + 2
                else:
                    dp[i][j] = dp[i + 1][j - 1]
            else:
                dp[i][j] = -1

            if dp[i][j] >= 0:
