def is_finite(p, q, b):
    if p % q == 0:
        return "Finite"
    g = gcd(p, q)
    p //= g
    q //= g
    while q % b == 0:
        q //= b
    while q % 2 == 0:
        q //= 2
    while q % 5 == 0:
        q //= 5
    return "Finite" if q == 1 else "Infinite"

