def largest_prime_below(n):
    if n < 2:
        return None
    if n == 2:
        return 2
    if n % 2 == 0:
        n -= 1
    while n > 1:
        if is_prime(n):
            return n
        n -= 2

def smallest_prime_above(n):
    if n < 2:
        return 2
    if n == 2:
        return 3
    if n % 2 == 0:
        n += 1
    while True:
        if is_prime(n):
            return n
        n += 2

def is_prime(num):
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

