        for j in range(i+1, len(fav_nums)):
            for k in range(j+1, len(fav_nums)):
                if fav_nums[i]**2 + fav_nums[j]**2 + fav_nums[k]**2 == x**2:
                    return 3
                if fav_nums[i]**2 + fav_nums[j]**2 + fav_nums[k]**2 > x**2:
