def find_largest_divisor(p, q):
    if p % q != 0:
        return p
    factors = []
    for i in range(2, int(math.sqrt(q)) + 1):
        if q % i == 0:
            factors.append(i)
            while q % i == 0:
                q //= i
    if q > 1:
        factors.append(q)

    result = 1
    for factor in factors:
        while p % factor == 0 and p % (p // factor) == 0:
            p //= factor
    return p

