def min_time_to_move_box(x1, y1, x2, y2):
    if x1 == x2 and y1 == y2:
        return 0
    if x1 != x2 and y1 != y2:
        return (abs(x2 - x1) + abs(y2 - y1))
    return (abs(x2 - x1) + abs(y2 - y1) + 1)

