import sys

def reflect(x, y, n, m):
    if x == 0:
        return (1, y)
    elif x == n:
        return (n - 1, y)
    elif y == 0:
        return (x, 1)
    elif y == m:
        return (x, m - 1)

def main():
    n, m, k = map(int, sys.stdin.readline().split())
    sensors = [tuple(map(int, sys.stdin.readline().split())) for _ in range(k)]

    times = []
    x, y = 0, 0
    dx, dy = 1, 1
    time = 0

    while True:
        if (x, y) in sensors:
            times.append(time)
            sensors.remove((x, y))

        if x == 0 and y == 0:
            break

        if x == n and y == m:
            break

        if x == 0 or x == n:
            dx = -dx
        if y == 0 or y == m:
            dy = -dy

        x += dx
        y += dy
        time += 1

    for sensor in sensors:
        if sensor not in times:
            times.append(-1)

    print(' '.join(map(str, times)))

if __name__ == "__main__":
    main()

