    elif event_type == 3:
        t = event[1]
        for i in range(min(t, unread_count)):
            for j in range(n):
                if notifications[j] > 0:
                    notifications[j] -= 1
                    unread_count -= 1
                else:
                    break
    print(unread_count)

import sys

def min_moves(n, A, B):
    moves = 0
    used_chars = set()
    for i in range(n):
        if A[i] != B[i]:
            if A[i] not in used_chars:
                used_chars.add(A[i])
            if B[i] not in used_chars:
                used_chars.add(B[i])
            moves += 1
    return moves

