import sys
from collections import defaultdict, deque

input = sys.stdin.readline
MOD = 10**9 + 7

def main():
    N, M = map(int, input().split())
    S, T = map(int, input().split())
    edges = [list(map(int, input().split())) for _ in range(M)]

    graph = defaultdict(list)
    for u, v, d in edges:
        graph[u].append((v, d))
        graph[v].append((u, d))

    def bfs(start):
        dist = [float('inf')] * (N + 1)
        dist[start] = 0
        queue = deque([start])
        while queue:
            node = queue.popleft()
            for neighbor, d in graph[node]:
                if dist[neighbor] > dist[node] + d:
                    dist[neighbor] = dist[node] + d
                    queue.append(neighbor)
        return dist

    dist_from_S = bfs(S)
    dist_from_T = bfs(T)

    if dist_from_S[T] % 2 != 0:
        print(0)
        return

    even_nodes = set()
    odd_nodes = set()
    for i in range(1, N + 1):
        if dist_from_S[i] % 2 == 0 and dist_from_T[i] % 2 == 0:
            even_nodes.add(i)
        elif dist_from_S[i] % 2 != 0 and dist_from_T[i] % 2 != 0:
            odd_nodes.add(i)

    graph_even = defaultdict(list)
    graph_odd = defaultdict(list)
    for u, v, d in edges:
        if dist_from_S[u] % 2 == 0 and dist_from_T[u] % 2 == 0:
            if dist_from_S[v] % 2 == 0 and dist_from_T[v] % 2 == 0:
                graph_even[u].append(v)
                graph_even[v].append(u)
            else:
                graph_odd[u].append(v)
                graph_odd[v].append(u)
        elif dist_from_S[u] % 2 != 0 and dist_from_T[u] % 2 != 0:
            if dist_from_S[v] % 2 != 0 and dist_from_T[v] % 2 != 0:
                graph_odd[u].append(v)
                graph_odd[v].append(u)
            else:
                graph_even[u].append(v)
                graph_even[v].append(u)

    def count_paths(graph, start, end):
        queue = deque([start])
        ways = [0] * (N + 1)
        ways[start] = 1
        while queue:
            node = queue.popleft()
            for neighbor in graph[node]:
                if ways[neighbor] == 0:
                    queue.append(neighbor)
                ways[neighbor] += ways[node]
                ways[neighbor] %= MOD
        return ways[end]

    ways_even = count_paths(graph_even, S, T)
    ways_odd = count_paths(graph_odd, S, T)
    print(ways_even * ways_odd % MOD)

if __name__ == "__main__":
    main()

