def count_haikus(N, X, Y, Z):
    dp = [[[[-1] * (Z + 1) for _ in range(N + 1)] for _ in range(Y + 1)] for _ in range(X + 1)]

    def dfs(x, y, z, length):
        if dp[x][y][z][length] != -1:
            return dp[x][y][z][length]
        if length == N:
            return 1 if x == X and y == Y and z == Z else 0

        res = 0
        for i in range(1, 11):
            if x + i <= X:
                res += dfs(x + i, y, z, length + 1)
            elif y + i <= Y:
                res += dfs(x, y + i, z, length + 1)
            elif z + i <= Z:
                res += dfs(x, y, z + i, length + 1)
            res %= MOD

        dp[x][y][z][length] = res
        return res

    return dfs(0, 0, 0, 0)

