    p = list(map(int, input().split()))
    swaps = [tuple(map(int, input().split())) for _ in range(M)]

    # Create a graph where each node represents a position in the permutation
    # and edges represent possible swaps.
    graph = {i: [] for i in range(1, N + 1)}
    for x, y in swaps:
        graph[x].append(y)
        graph[y].append(x)

    # Find the number of cycles in the graph.
    visited = [False] * (N + 1)
    cycles = []

    def dfs(node, path):
        if visited[node]:
            return
        visited[node] = True
        path.append(node)
        for neighbor in graph[node]:
            if not visited[neighbor]:
                dfs(neighbor, path)

    for i in range(1, N + 1):
        if not visited[i]:
            cycle = []
            dfs(i, cycle)
            cycles.append(cycle)

    # For each cycle, we can swap to make at most one element correct.
    max_correct = 0
    for cycle in cycles:
        correct_count = 0
        for node in cycle:
            if p[node - 1] == node:
                correct_count += 1
        # We can swap to make at most one element correct in this cycle.
        # The rest will be incorrect.
        max_correct += len(cycle) - correct_count

    print(max_correct)

