def count_valid_parabolas(points):
    valid_parabolas = set()
    for i in range(len(points)):
        for j in range(i + 1, len(points)):
            if points[i][0] != points[j][0]:
                a, b = points[i][0], points[j][0]
                x1, y1 = points[i]
                x2, y2 = points[j]
                if a < b:
                    a, b = b, a
                    x1, y1, x2, y2 = x2, y2, x1, y1
                c = (y1 - y2 + b * x2 - a * x1) / (b - a)
                b = -(a + b)
                parabola = (a, b, c)
                if parabola not in valid_parabolas:
                    if not any((x - a) ** 2 + b * (x - a) + c < y for x, y in points):
                        valid_parabolas.add(parabola)
    return len(valid_parabolas)

