def is_good(s):
    for k in range(2, len(s) + 1):
        if s * k == s:
            return False
    return True

def find_best_representation(w):
    n = len(w)
    dp = [[] for _ in range(n + 1)]
    dp[0] = [[]]

    for i in range(1, n + 1):
        for j in range(i):
            if is_good(w[j:i]):
                for prev in dp[j]:
                    dp[i].append(prev + [w[j:i]])

    best_len = min(len(rep) for rep in dp[n])
    best_count = sum(1 for rep in dp[n] if len(rep) == best_len)

    return best_len, best_count % MOD

