                if s[i] == '0':
                    dp[i + 1][j + 1] = (dp[i + 1][j + 1] + dp[i][j]) % MOD
                elif s[i] == '1':
                    dp[i + 1][j + 1] = (dp[i + 1][j + 1] + dp[i][j]) % MOD
            if j > 0:
                dp[i][j] = (dp[i][j] + dp[i][j - 1]) % MOD
            if i > 0 and j > 0:
                dp[i][j] = (dp[i][j] + dp[i - 1][j - 1]) % MOD
            if i > 0 and j > 0:
                dp[i][j] = (dp[i][j] - dp[i - 1][j] + MOD) % MOD

    return dp[len(s)][len(s)]

