def can_reverse(n, a, b, edges):
    if a == b:
        return "YES"

    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    queue = deque([a])
    visited = set([a])
    parent = {a: None}

    while queue:
        node = queue.popleft()
        if node == b:
            break
        for neighbor in graph[node]:
            if neighbor not in visited:
                visited.add(neighbor)
                parent[neighbor] = node
                queue.append(neighbor)

    if b not in parent:
        return "NO"

    path = []
    current = b
    while current is not None:
        path.append(current)
        current = parent[current]
    path.reverse()

    if len(path) % 2 == 0:
        return "NO"

    return "YES"

