def solve(n, p):
    if n % 2 == 1:
        return 0, 0, 0
    half = n // 2
    if p[0] <= half:
        return 0, 0, 0
    g = 1
    while g < n and p[g] == p[0]:
        g += 1
    if g >= half:
        return 0, 0, 0
    s = g + 1
    while s < n and p[s] == p[g]:
        s += 1
    if s >= half:
        return 0, 0, 0
    b = s + 1
    while b < n and p[b] == p[s]:
        b += 1
    if b > half:
        return 0, 0, 0
    return g, s - g, b - s

