def binomial_coefficient(n, k):
    if k > n:
        return 0
    k = min(k, n - k)
    numer = 1
    denom = 1
    for i in range(1, k + 1):
        numer = (numer * (n - i + 1)) % MOD
        denom = (denom * i) % MOD
    return (numer * pow(denom, MOD - 2, MOD)) % MOD

