import sys

def min_operations_to_sort(n, a):
    # Find the position where the array is not sorted
    last_sorted = 0
    for i in range(1, n):
        if a[i] < a[i - 1]:
            last_sorted = i
            break
    else:
        return 0

    # Count the number of elements that need to be moved to the beginning
    moves_to_beginning = last_sorted
    for i in range(last_sorted):
        if a[i] > a[last_sorted]:
            moves_to_beginning += 1

    # The minimum number of operations is the minimum of moves_to_beginning and n - last_sorted
    return min(moves_to_beginning, n - last_sorted)

