def min_lexicographical_string(n, k, s):
    s = list(s)
    for i in range(n - 1):
        if k == 0:
            break
        if s[i] == '1':
            continue
        j = i
        while j < n - 1 and s[j] == '0':
            j += 1
        if j == n or s[j] == '1':
            j -= 1
        if j - i > k:
            continue
        k -= j - i
        for l in range(j - i):
            s[i + l], s[i + l + 1] = s[i + l + 1], s[i + l]
        s[i], s[i + 1] = s[i + 1], s[i]
    return ''.join(s)

