import sys

def find_shortest_substring(s):
    n = len(s)
    if n == 1:
        return -1

    # Calculate the final position of the robot
    x_e, y_e = 0, 0
    for move in s:
        if move == 'L':
            x_e -= 1
        elif move == 'R':
            x_e += 1
        elif move == 'U':
            y_e += 1
        elif move == 'D':
            y_e -= 1

    # Check all possible substrings
    min_len = float('inf')
    best_l, best_r = -1, -1
    for l in range(n):
        x_curr, y_curr = 0, 0
        for r in range(l, n):
            if s[r] == 'L':
                x_curr -= 1
            elif s[r] == 'R':
                x_curr += 1
            elif s[r] == 'U':
                y_curr += 1
            elif s[r] == 'D':
                y_curr -= 1

            if x_curr == x_e and y_curr == y_e:
                if r - l + 1 < min_len:
                    min_len = r - l + 1
                    best_l, best_r = l + 1, r + 1

    return (best_l, best_r) if min_len != float('inf') else -1

