def max_candies(n, k):
    if k == 1:
        return n
    if n <= 2 * (k // 2):
        return 0
    base = n // k
    extra = n % k
    max_a = base
    if extra <= k // 2:
        max_a += extra
    else:
        max_a += k // 2
    return max_a * (k - (max_a - (n // k)))

