def can_make_equal(n, a, b):
    diff = [b[i] - a[i] for i in range(n)]
    i = 0
    while i < n:
        if diff[i] == 0:
            i += 1
            continue
        if diff[i] != 0:
            if i + 1 < n and diff[i + 1] == 0:
                i += 1
                continue
            if diff[i] != diff[i + 1]:
                return "NO"
            if diff[i] == diff[i + 1]:
                i += 2
                continue
        return "NO"
    return "YES"

