def factorial(x):
    f = 1
    for i in range(1, x + 1):
        f = (f * i) % MOD
    return f

def power(x, y, p):
    res = 1
    x = x % p
    while y > 0:
        if (y & 1):
            res = (res * x) % p
        y = y >> 1
        x = (x * x) % p
    return res

def modInverse(n, p):
    return power(n, p - 2, p)

def nCk(n, k, p):
    if (k > n):
        return 0
    if (k == 0 or k == n):
        return 1
    fact = [1] * (n + 1)
    for i in range(2, n + 1):
        fact[i] = fact[i - 1] * i % p
    return (fact[n] * modInverse(fact[k], p) % p * modInverse(fact[n - k], p) % p)

