def can_transform(n, a, b):
    if a == b:
        return "Yes"
    for k in range(1, n // 2 + 1):
        a_prefix = a[:k]
        a_suffix = a[n - k:]
        a_middle = a[k:n - k]
        for i in range(k):
            a_prefix[i], a_suffix[i] = a_suffix[i], a_prefix[i]
        if a_prefix + a_middle + a_suffix == b:
            return "Yes"
    return "No"

