def solve():
    t = int(input())
    for _ in range(t):
        n, k = map(int, input().split())
        graph = defaultdict(list)
        degree = [0] * (n + 1)
        for _ in range(n - 1):
            u, v = map(int, input().split())
            graph[u].append(v)
            graph[v].append(u)
            degree[u] += 1
            degree[v] += 1

        leaves = deque()
        for i in range(1, n + 1):
            if degree[i] == 1:
                leaves.append(i)

        moves = 0
        while leaves:
            size = len(leaves)
            if size >= k:
                moves += size // k
                for _ in range(size // k):
                    for _ in range(k):
                        leaf = leaves.pop()
                        for neighbor in graph[leaf]:
                            degree[neighbor] -= 1
                            if degree[neighbor] == 1:
                                leaves.append(neighbor)
            else:
                break
        print(moves)

