import sys

def probability_of_winning(w, b):
    memo = {}

    def dp(w, b):
        if w <= 0:
            return 0
        if b == 0:
            return 1
        if (w, b) in memo:
            return memo[(w, b)]

        prob_win = w / (w + b)
        prob_lose = (b / (w + b)) * (dp(w, b - 1) if b > 0 else 0)

        memo[(w, b)] = max(prob_win, prob_lose)
        return memo[(w, b)]

    return dp(w, b)

