def count_camels(n, t):
    if t > n - 2:
        return 0

    def is_camel(y):
        humps = [y[i] < y[i+1] > y[i+2] or y[i] > y[i+1] < y[i+2] for i in range(n - 2)]
        return humps.count(True) == t and humps.count(False) == n - 2 - t

    count = 0
    for ys in product(range(1, 5), repeat=n):
        if is_camel(list(ys)):
            count += 1
    return count

