def count_ways(n, k, graph):
    ways = 0
    for mask in range(1 << n):
        if bin(mask).count('1') == k:
            dists = [[] for _ in range(n)]
            for i in range(n):
                if mask & (1 << i):
                    dist = [0] * n
                    dfs(i, -1, dist, graph, dists)
            valid = True
            for i in range(k):
                for j in range(i + 1, k):
                    if dists[i][j] != dists[i][j - 1]:
                        valid = False
                        break
                if not valid:
                    break
            if valid:
                ways = (ways + 1) % MOD
    return ways

