def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def bfs(graph, start, n):
    visited = [False] * (n + 1)
    distance = [float('inf')] * (n + 1)
    queue = deque([start])
    visited[start] = True
    distance[start] = 0
    while queue:
        node = queue.popleft()
        for neighbor in graph[node]:
            if not visited[neighbor]:
                visited[neighbor] = True
                distance[neighbor] = distance[node] + 1
                queue.append(neighbor)
    return distance[n]

