def count_regular_subsequences(c):
    dp = [[0] * (n + 1) for _ in range(n + 1)]
    for length in range(1, n + 1):
        for start in range(n - length + 1):
            end = start + length
            if length == 1:
                if c[start] % 2 == 0:
                    dp[start][end] = 1
            else:
                if c[start] % 2 == 0 and c[start + length - 1] % 2 == 0:
                    dp[start][end] = dp[start + 1][end - 1] + 1
                else:
                    for mid in range(start + 1, end, 2):
                        if c[mid - 1] % 2 == 0 and c[mid] % 2 == 0:
                            dp[start][end] += dp[start][mid] + dp[mid][end] - dp[start][mid - 1]
    return dp[0][n]

