def min_moves_to_power_of_2(n):
    def is_power_of_2(num):
        return (num & (num - 1) == 0) and num != 0

    def count_moves(num):
        if is_power_of_2(num):
            return 0
        for digit in str(num):
            if digit != '0':
                new_num = num * 10 + int(digit)
                if is_power_of_2(new_num):
                    return 1
        return float('inf')

    moves = float('inf')
    for digit in str(n):
        if digit != '0':
            new_num = n * 10 + int(digit)
            moves = min(moves, count_moves(new_num))
        else:
            new_num = n
            moves = min(moves, count_moves(new_num))
    return moves

