MOD = 998244353

def mod_pow(base, exponent, modulus):
    result = 1
    while exponent > 0:
        if exponent % 2 == 1:
            result = (result * base) % modulus
        exponent = exponent >> 1
        base = (base * base) % modulus
    return result

def mod_inv(a, modulus):
    return mod_pow(a, modulus - 2, modulus)

def solve(n, tasks):
    fact = [1] * (n + 1)
    ifact = [1] * (n + 1)
    for i in range(2, n + 1):
        fact[i] = (fact[i - 1] * i) % MOD
        ifact[i] = mod_inv(fact[i], MOD)

    def nCr(n, r):
        if r < 0 or r > n:
            return 0
        return (fact[n] * ifact[r] % MOD) * ifact[n - r] % MOD

    def nHr(n, r):
        return nCr(n + r - 1, r)

    nice_perms = 0
    for k in range(1, n + 1):
        if tasks[k - 1] < k:
            continue
        nice_perms = (nice_perms + nHr(n - k, tasks[k - 1] - 1)) % MOD

    return nice_perms

def main():
    t = int(input().strip())
    for _ in range(t):
        n = int(input().strip())
        tasks = list(map(int, input().strip().split()))
        print(solve(n, tasks))

