def min_operations_to_zero(n, digits):
    if n == 1 and digits[0] == '0':
        return 0
    if digits == ['0'] * n:
        return 0

    operations = 0
    while digits != ['0'] * n:
        if digits[0] != '0':
            idx = digits.index(max(digits))
            operations += len(digits) - 1 - idx
            digits = ['0'] * (len(digits) - 1 - idx) + digits[:idx]
        else:
            idx = digits.index('0')
            operations += idx
            digits = digits[idx:] + ['0'] * idx
    return operations

