    for d in range(1, k + 1):
        for i in range(n):
            for j in range(m):
                if field[i][j] == '*':
                    valid = True
                    for h in range(d + 1):
                        if (i - h, j) not in field or (i - h, j) == '*' or \
                           (i - h, j - h) not in field or (i - h, j - h) == '*' or \
                           (i - h, j + h) not in field or (i - h, j + h) == '*':
                            valid = False
                            break
                    if valid:
                        for h in range(d + 1):
