def factorial_mod(n):
    fact = [1] * (n + 1)
    for i in range(2, n + 1):
        fact[i] = (fact[i - 1] * i) % MOD
    return fact

def mod_inverse(n, mod):
    return pow(n, mod - 2, mod)

def binomial_coefficient_mod(n, k, fact, mod):
    if k > n:
        return 0
    return (fact[n] * mod_inverse(fact[k], mod) * mod_inverse(fact[n - k], mod)) % mod

def count_permutations(n):
    fact = factorial_mod(2 * n)
    return binomial_coefficient_mod(2 * n, n, fact, MOD)

