from collections import defaultdict

def find_parent(parent, i):
    if parent[i] != i:
        parent[i] = find_parent(parent, parent[i])
    return parent[i]

def union(parent, rank, x, y):
    xroot = find_parent(parent, x)
    yroot = find_parent(parent, y)

    if rank[xroot] < rank[yroot]:
        parent[xroot] = yroot
    elif rank[xroot] > rank[yroot]:
        parent[yroot] = xroot
    else:
        parent[yroot] = xroot
        rank[xroot] += 1

def main():
    input_lines = sys.stdin.readlines()
    t = int(input_lines[0].strip())
    line_index = 1

    for _ in range(t):
        n, m = map(int, input_lines[line_index].strip().split())
        line_index += 1
        restrictions = [list(map(int, input_lines[line_index].strip().split())) for line_index in range(line_index, line_index + m)]
        line_index += m

        parent = [i for i in range(n + 1)]
        rank = [0] * (n + 1)
        edges = []

        for a, b, c in restrictions:
            if find_parent(parent, a) != find_parent(parent, b) and find_parent(parent, b) != find_parent(parent, c) and find_parent(parent, c) != find_parent(parent, a):
                union(parent, rank, b, a)
                union(parent, rank, b, c)
                union(parent, rank, a, c)

        for i in range(1, n):
            if find_parent(parent, i) != find_parent(parent, i + 1):
                union(parent, rank, i, i + 1)
                edges.append((i, i + 1))

        for edge in edges:
            print(edge[0], edge[1])

