def find_imposters(n, comments):
    graph = {i: [] for i in range(1, n + 1)}
    for i, j, c in comments:
        graph[i].append((j, c))
        graph[j].append((i, c))

    imposters = [-1] * (n + 1)

    def dfs(node, is_imposter):
        if imposters[node] != -1 and imposters[node] != is_imposter:
            return False
        if imposters[node] == is_imposter:
            return True
        imposters[node] = is_imposter
        for neighbor, role in graph[node]:
            if not dfs(neighbor, is_imposter if role == 'crewmate' else not is_imposter):
                return False
        return True

    for i in range(1, n + 1):
        if imposters[i] == -1:
            if not dfs(i, True):
                return -1

    return imposters.count(True)

