def can_complete_level(n, top, bottom):
    # Check if there is a path from (1, 1) to (2, n)
    # Monocarp can move to adjacent cells or diagonally
    # The cells (1, 1) and (2, n) are safe

    # Initialize a 2D array to store the minimum steps to reach each cell
    dp = [[float('inf')] * n for _ in range(2)]
    dp[0][0] = 0
    dp[1][0] = 0

    for j in range(1, n):
        if top[j] == '0':
            dp[0][j] = min(dp[0][j], dp[0][j-1] + 1)
        if bottom[j] == '0':
            dp[1][j] = min(dp[1][j], dp[1][j-1] + 1)
        if top[j] == '0' and bottom[j] == '0':
            dp[0][j] = min(dp[0][j], dp[1][j-1] + 1)
            dp[1][j] = min(dp[1][j], dp[0][j-1] + 1)

    return "YES" if dp[1][n-1] <= n else "NO"

