def dfs(x, y, grid, visited):
    if (x, y) in visited:
        return 0
    visited.add((x, y))
    count = 1
    directions = [(0, -1), (1, 0), (0, 1), (-1, 0)]
    for dx, dy in directions:
        nx, ny = x + dx, y + dy
        if 0 <= nx < len(grid) and 0 <= ny < len(grid[0]) and (nx, ny) not in visited:
            if grid[nx][ny] & (1 << dx):
                count += dfs(nx, ny, grid, visited)
    return count

