def min_operations_to_equalize_candles(n, a, b):
    if a == b:
        return 0
    if a.count('1') != b.count('1'):
        return -1

    operations = 0
    for i in range(n):
        if a[i] != b[i]:
            if a[i] == '1':
                for j in range(i, n):
                    if a[j] == '1':
                        a = a[:j] + '0' + a[j+1:]
                        a = a[:i] + '0' + a[i+1:]
                        a = a[:i] + '1' + a[i+1:]
                        operations += 1
                        break
            else:
                for j in range(i, n):
                    if a[j] == '0':
                        a = a[:j] + '1' + a[j+1:]
                        a = a[:i] + '1' + a[i+1:]
                        operations += 1
                        break
    return operations

