def dfs(node, parent):
    subtree_size = 1
    red_count = 0
    for child in tree[node]:
        if child != parent:
            child_size, child_red_count = dfs(child, node)
            subtree_size += child_size
            red_count += child_red_count
    if red_count >= k:
        return 0, 0
    if subtree_size <= k - red_count:
        return subtree_size, red_count + subtree_size
    return subtree_size, red_count

