def minimax(node, parent, is_red_turn):
    global white_count, red_count, blue_count
    subtree_size, red_in_subtree = dfs(node, parent)
    if is_red_turn:
        if red_in_subtree <= k:
            red_count += red_in_subtree
            white_count -= subtree_size
        else:
            red_count += k
            white_count -= k
    else:
        if red_in_subtree == 0:
            blue_count += subtree_size
            white_count -= subtree_size
        else:
            blue_count += subtree_size - red_in_subtree
            white_count -= red_in_subtree

    if red_count + blue_count == n:
        return white_count * (red_count - blue_count)

    if red_count + blue_count < n:
        if is_red_turn:
            return minimax(node, parent, False)
        else:
            return max(minimax(child, node, True) for child in tree[node] if child != parent)

    return white_count * (red_count - blue_count)

