def count_polycarp_likes(n):
    count = 0
    limit = int(math.pow(n, 1/3))
    for i in range(1, limit + 1):
        square = i * i
        cube = i * i * i
        if square <= n:
            count += 1
        if cube <= n:
            count += 1
        if square <= n and cube <= n:
            common = i * i * i
            if common <= n:
