import sys
from itertools import product

def generate_b_strings(k, length):
    for combo in product('b', repeat=length):
        yield ''.join(combo)

def find_kth_string(n, k, s):
    asterisks = [i for i in range(n) if s[i] == '*']
    if not asterisks:
        return s

    # Calculate the number of different BA-strings
    total_strings = 0
    for length in range(len(asterisks) + 1):
        for combo in product('b', repeat=length):
            total_strings += k ** (len(asterisks) - length)

    # Find the x-th lexicographically smallest BA-string
    x = x - 1  # Convert to zero-based index
    result = list(s)
    for i, pos in enumerate(asterisks):
        if i == 0:
            num_bs = x // (k ** (len(asterisks) - i)) % k
        else:
            num_bs = x // (k ** (len(asterisks) - i)) % k
        result[pos] = 'b' * num_bs

    return ''.join(result)

