MOD = 998244353

def count_ways(s, k):
    n = len(s)
    if k == 0:
        return 1
    if k > n:
        return 0

    # Calculate the number of ways to shuffle a substring of length k with k 1s
    ways = 0
    for i in range(n - k + 1):
        substring = s[i:i + k]
        count_1 = substring.count('1')
        if count_1 == k:
            ways += 1
            for j in range(i, i + k):
                for l in range(j + 1, i + k):
                    if s[j] == '1' and s[l] == '1':
                        ways += 1
                        ways %= MOD
    return ways

