import math
from collections import defaultdict

def is_square(n):
    root = int(math.sqrt(n))
    return n == root * root

def prime_factors(n):
    factors = defaultdict(int)
    d = 2
    while d * d <= n:
        while (n % d) == 0:
            factors[d] += 1
            n //= d
        d += 1
    if n > 1:
        factors[n] += 1
    return factors

def factorial_square(n):
    factors = prime_factors(n)
    for factor, count in factors.items():
        if count % 2 != 0:
            return False
    return True

