def time_to_clean_cell(n, m, r_b, c_b, r_d, c_d):
    time = 0
    dr, dc = 1, 1
    while (r_b, c_b) != (r_d, c_d):
        if r_b + dr > n or r_b + dr < 1:
            dr = -dr
        if c_b + dc > m or c_b + dc < 1:
            dc = -dc
        r_b += dr
        c_b += dc
        time += 1
    return time

