import sys

def find_max_correct_bracket_sequence(s):
    stack = []
    max_depth = 0
    depth_to_sequence = {}

    for i, ch in enumerate(s):
        if ch == '(':
            if stack:
                stack.append(ch)
        elif ch == '[':
            if stack:
                stack.append(ch)
        elif ch == ')':
            if stack and stack[-1] == '(':
                stack.pop()
                depth = len(stack)
                if depth not in depth_to_sequence:
                    depth_to_sequence[depth] = ([], 0)
                depth_to_sequence[depth] = (depth_to_sequence[depth][0] + [ch], depth_to_sequence[depth][1])
        elif ch == ']':
            if stack and stack[-1] == '[':
                stack.pop()
                depth = len(stack)
                if depth not in depth_to_sequence:
                    depth_to_sequence[depth] = ([], 0)
                depth_to_sequence[depth] = (depth_to_sequence[depth][0] + [ch], depth_to_sequence[depth][1] + 1)

    max_depth = max(depth_to_sequence.keys(), default=0)
    return max_depth, depth_to_sequence[max_depth][0]

