def run_program(s):
    CP, DP = 0, 1
    count = [0] * 10
    while CP < len(s):
        if s[CP].isdigit():
            digit = int(s[CP])
            count[digit] += 1
            CP += 1
            s = s[:CP] + str(digit - 1) + s[CP+1:]
            if digit - 1 == 0:
                s = s[:CP] + s[CP+1:]
        elif s[CP] == '<':
            DP = -1
            CP += 1
            if CP < len(s) and s[CP] == '>':
                s = s[:CP-1] + s[CP+1:]
        elif s[CP] == '>':
            DP = 1
            CP += 1
            if CP < len(s) and s[CP] == '<':
                s = s[:CP-1] + s[CP+1:]
        if CP >= len(s):
            break
    return count

