MOD = 10**9 + 7

def count_worlds(n, m):
    dp = [[[0] * (m + 1) for _ in range(n + 1)] for _ in range(n + 1)]
    dp[2][1][1] = 1

    for i in range(3, n + 1):
        for j in range(1, m + 1):
            for k in range(1, i):
                dp[i][j][k] = (dp[i][j][k] + dp[i - 1][j][k] * k) % MOD
                dp[i][j][k] = (dp[i][j][k] + dp[i - 1][j][k - 1] * (i - 2 - (k - 1))) % MOD
                if j > 1:
                    dp[i][j][k] = (dp[i][j][k] + dp[i - 1][j - 1][k] * k * (k + 1) // 2) % MOD
                    dp[i][j][k] = (dp[i][j][k] + dp[i - 1][j - 1][k - 1] * k * (i - 2 - (k - 1))) % MOD

    result = 0
    for j in range(1, m + 1):
        result = (result + dp[n][j][m]) % MOD
    return result

