def max_of_mins(n, k, a):
    if k == 1:
        return max(a)
    if k == n:
        return min(a)

    right_min = [a[-1]] * n
    for i in range(n - 2, -1, -1):
        right_min[i] = min(right_min[i + 1], a[i])

    max_min = float('-inf')
    for i in range(n - k + 1):
        max_min = max(max_min, min(right_min[i], a[i + k - 1]))

