import sys
from math import gcd

def find_parent(parent, x):
    if parent[x] != x:
        parent[x] = find_parent(parent, parent[x])
    return parent[x]

def union(parent, rank, x, y):
    xroot = find_parent(parent, x)
    yroot = find_parent(parent, y)

    if rank[xroot] < rank[yroot]:
        parent[xroot] = yroot
    elif rank[xroot] > rank[yroot]:
        parent[yroot] = xroot
    else:
        parent[yroot] = xroot
        rank[xroot] += 1

def is_coprime_sortable(N, sequence):
    parent = list(range(max(sequence) + 1))
    rank = [0] * (max(sequence) + 1)

    for i in range(N):
        for j in range(i + 1, N):
            if gcd(sequence[i], sequence[j]) > 1:
                union(parent, rank, sequence[i], sequence[j])

    sorted_sequence = sorted(sequence)
    for i in range(N):
        if find_parent(parent, sequence[i]) != find_parent(parent, sorted_sequence[i]):
            return 0
    return 1

