from itertools import product

def find_groups(board, N):
    groups = {}
    visited = [[False] * (N + i) for i in range(1, N + 1)]
    for i in range(N):
        for j in range(N + i):
            if board[i][j] == 0 or visited[i][j]:
                continue
            group_id = f"{i},{j}"
            stack = [(i, j)]
            group = []
            while stack:
                x, y = stack.pop()
                if x < 0 or x >= N or y < 0 or y >= N + x or visited[x][y] or board[x][y] == 0:
                    continue
                visited[x][y] = True
                group.append((x, y))
                if x > 0 and not visited[x - 1][y] and board[x - 1][y] == 0:
                    stack.append((x - 1, y))
                if x < N - 1 and not visited[x + 1][y] and board[x + 1][y] == 0:
                    stack.append((x + 1, y))
                if y > 0 and not visited[x][y - 1] and board[x][y - 1] == 0:
                    stack.append((x, y - 1))
                if y < N + x - 1 and not visited[x][y + 1] and board[x][y + 1] == 0:
                    stack.append((x, y + 1))
            groups[group_id] = group
    return groups

def calculate_points(board, N, C):
    points = 0
    for i in range(N):
        for j in range(N + i):
            if board[i][j] == C:
                groups = find_groups(board, N)
                for group_id, group in groups.items():
                    x, y = map(int, group_id.split(','))
                    if all(board[dx][dy] == 0 for dx, dy in group):
                        points += len(group)
                    elif any(board[dx][dy] == 0 for dx, dy in group):
                        points -= len(group)
    return points

