def min_reverse_operations(N, A):
    from itertools import permutations

    def is_sorted(arr):
        return all(arr[i] <= arr[i + 1] for i in range(len(arr) - 1))

    def reverse(arr, i, j):
        return arr[:i] + arr[i:j+1][::-1] + arr[j+1:]

    min_ops = float('inf')
    for perm in permutations(range(1, N + 1)):
        B = list(perm)
        ops = 0
        while not is_sorted(B):
            for i in range(N - 1):
                for j in range(i + 1, N):
                    if is_sorted(reverse(B, i, j)):
                        B = reverse(B, i, j)
                        ops += 1
                        break
            else:
                break
        min_ops = min(min_ops, ops)
    return min_ops

