def congestion_degree(N, holidays):
    days_in_year = 360
    congestion = [0] * days_in_year

    for i in range(N):
        Mi, Di, Vi, Si = holidays[i]
        start_date = (Mi - 1) * 30 + Di - 1
        end_date = start_date + Vi - 1

        for day in range(start_date, end_date + 1):
            if day < 0 or day >= days_in_year:
                continue
            if day < start_date:
                influence = Si - (start_date - day)
            elif day > end_date:
                influence = Si - (day - end_date)
            else:
                influence = Si
            congestion[day] = max(congestion[day], influence)

    return min(congestion)

