        return False
    for row in matrix:
        if len(row) != n:
            return False
    magic_sum = sum(matrix[0])
    for row in matrix:
        if sum(row) != magic_sum:
            return False
    for col in range(n):
        column_sum = sum(row[col] for row in matrix)
