def answer(x, y):
    min_lcm = y + 1  # Initialize to a value larger than any possible LCM
    result = None
    for a in range(x, y + 1):
        for b in range(a + 1, y + 1):
            current_gcd = math.gcd(a, b)
            current_lcm = (a * b) // current_gcd
            if current_lcm < x or current_lcm > y:
                continue
            # Update the result if a smaller LCM is found
            if current_lcm < min_lcm:
                min_lcm = current_lcm
                result = (a, b)
            elif current_lcm == min_lcm:
                # Compare a and b with the current result to maintain order
                current_a, current_b = result
                if a < current_a or (a == current_a and b < current_b):
                    result = (a, b)
    return result

