def max_sum(triangle, n):
    if not triangle:
        return 0
    prev_row = triangle[0].copy()
    for i in range(1, n):
        current_row = []
        for j in range(i + 1):
            if j == 0:
                current_val = triangle[i][j] + prev_row[j]
            elif j == i:
                current_val = triangle[i][j] + prev_row[j - 1]
            else:
                current_val = triangle[i][j] + max(prev_row[j - 1], prev_row[j])
            current_row.append(current_val)
        prev_row = current_row
    return max(prev_row)

