def min_cost(cost, m, n):
    if m < 0 or n < 0 or m >= len(cost) or n >= len(cost[0]):
        return float('inf')
    dp = [[float('inf')] * len(cost[0]) for _ in range(len(cost))]
    dp[0][0] = cost[0][0]
    for i in range(len(cost)):
        for j in range(len(cost[0])):
            if i == 0 and j == 0:
                continue
            top = dp[i-1][j] if i-1 >= 0 else float('inf')
            left = dp[i][j-1] if j-1 >= 0 else float('inf')
            topleft = dp[i-1][j-1] if i-1 >= 0 and j-1 >= 0 else float('inf')
            dp[i][j] = cost[i][j] + min(top, left, topleft)
    return dp[m][n]

