def magic_square_test(matrix):
    # Check if the matrix is square
    n = len(matrix)
    if n == 0:
        return False
    for row in matrix:
        if len(row) != n:
            return False

    # Calculate the magic constant
    magic_constant = sum(matrix[0])

    # Check each row
    for row in matrix:
        if sum(row) != magic_constant:
            return False

    # Check each column
    for col in range(n):
        column_sum = 0
        for row in matrix:
            column_sum += row[col]
        if column_sum != magic_constant:
            return False

    # Check main diagonal
    main_diagonal = sum(matrix[i][i] for i in range(n))
    if main_diagonal != magic_constant:
        return False

    # Check other diagonal
    other_diagonal = sum(matrix[i][n-1-i] for i in range(n))
    if other_diagonal != magic_constant:
        return False

    return True

