        return 0
    prev_dp = triangle[0]
    for i in range(1, n):
        current_row = triangle[i]
        current_dp = []
        for j in range(len(current_row)):
            if j == 0:
                current_dp.append(current_row[j] + prev_dp[j])
            else:
                option1 = current_row[j] + prev_dp[j-1]
                option2 = current_row[j] + prev_dp[j] if j < len(prev_dp) else -float('inf')
