def max_chain_length(pairs):
    # Sort the pairs by the first element, and if equal, by the second in descending order
    sorted_pairs = sorted(pairs, key=lambda x: (x.first, -x.second))
    tails = []
    for pair in sorted_pairs:
        a = pair.first
        b = pair.second
        idx = bisect.bisect_left(tails, a)
        if idx == len(tails):
            tails.append(b)
        else:
            if b < tails[idx]:
                tails[idx] = b
    return len(tails)

